def _purge_expired_quiz_delivery_suppressions() -> None:
    now_ts = pytime.time()
    expired = [chat_id for chat_id, until_ts in scheduled_quiz_delivery_suppress_until.items() if float(until_ts or 0) <= now_ts]
    for chat_id in expired:
        scheduled_quiz_delivery_suppress_until.pop(chat_id, None)


def _suppress_quiz_delivery_target(chat_id: int, *, seconds: int | None = None) -> None:
    ttl = max(60, int(seconds if seconds is not None else QUIZ_DELIVERY_SUPPRESS_SECONDS))
    scheduled_quiz_delivery_suppress_until[int(chat_id)] = pytime.time() + ttl


def _is_quiz_delivery_target_suppressed(chat_id: int) -> bool:
    _purge_expired_quiz_delivery_suppressions()
    until_ts = scheduled_quiz_delivery_suppress_until.get(int(chat_id))
    return bool(until_ts and float(until_ts) > pytime.time())


def _is_permanent_quiz_delivery_error(exc: Exception) -> bool:
    if isinstance(exc, Forbidden):
        return True
    if not isinstance(exc, BadRequest):
        return False
    message = str(exc or "").strip().lower()
    permanent_fragments = (
        "chat not found",
        "bot was kicked",
        "user is deactivated",
        "need administrator rights",
        "have no rights",
        "polls can't be sent",
        "poll can't be stopped",
        "not enough rights",
        "group chat was upgraded",
    )
    return any(fragment in message for fragment in permanent_fragments)


def _get_quiz_schedule_now() -> datetime:
    try:
        tz = ZoneInfo(QUIZ_SCHEDULE_TZ_NAME)
    except Exception:
        tz = ZoneInfo("Europe/Vienna")
    return datetime.now(tz)


# Quiet window: NO interactive task/quiz (poll, rebus, crossword, article,
# anagram, aufgabe, sprint, artikel-sprint, listening) is delivered between
# QUIET_HOURS_START and QUIET_HOURS_END (local schedule tz). Pool-prep, reports,
# reminders and digests are NOT affected. Default 22:00 → 07:30.
QUIET_HOURS_START = (
    max(0, min(23, int((os.getenv("QUIET_HOURS_START_HOUR") or "22").strip() or "22"))),
    max(0, min(59, int((os.getenv("QUIET_HOURS_START_MINUTE") or "0").strip() or "0"))),
)
QUIET_HOURS_END = (
    max(0, min(23, int((os.getenv("QUIET_HOURS_END_HOUR") or "7").strip() or "7"))),
    max(0, min(59, int((os.getenv("QUIET_HOURS_END_MINUTE") or "30").strip() or "30"))),
)


def _is_quiet_hours_now(now: datetime | None = None) -> bool:
    """True when interactive task delivery is paused (default 22:00–07:30, local
    schedule tz). The window wraps across midnight."""
    n = now or _get_quiz_schedule_now()
    cur = n.hour * 60 + n.minute
    start = QUIET_HOURS_START[0] * 60 + QUIET_HOURS_START[1]
    end = QUIET_HOURS_END[0] * 60 + QUIET_HOURS_END[1]
    if start == end:
        return False
    if start < end:
        return start <= cur < end
    return cur >= start or cur < end  # wraps midnight


