async def _track_telegram_message_async(message, message_type: str = "text") -> None:
    try:
        if not message:
            return
        chat_id = int(message.chat_id)
        message_id = int(message.message_id)
        await asyncio.to_thread(
            record_telegram_system_message,
            chat_id,
            message_id,
            message_type,
        )
    except Exception:
        logging.debug("Failed to track telegram system message", exc_info=True)


async def _preserve_system_message(message, message_type: str) -> None:
    """Re-tag an already-sent message so the nightly cleanup never deletes it.
    Used for achievement keepsakes (грамоты / battle podiums) — see
    ALWAYS_PRESERVE_MESSAGE_TYPES."""
    try:
        if not message:
            return
        await asyncio.to_thread(
            update_telegram_system_message_type,
            chat_id=int(message.chat_id),
            message_id=int(message.message_id),
            message_type=message_type,
        )
    except Exception:
        logging.debug("Failed to preserve system message", exc_info=True)


# Сообщения, которые пишет в чат сам ПОЛЬЗОВАТЕЛЬ, нажимая меню или набирая команду
# («⚙️ Настройки», «▶️ Следующее задание», /start …). Ответы бота вычищаются ночью,
# и без этого в чате остаётся столбик из одних только нажатий.
USER_MENU_MESSAGE_TYPE = "user_menu"


def _is_disposable_user_message(message) -> bool:
    """True, если это сообщение пользователя в личке, отправленное НАЖАТИЕМ кнопки
    меню или командой. Набранный руками текст (переводы, слова, вопросы учителю)
    сюда не попадает никогда — он остаётся в чате."""
    try:
        chat = getattr(message, "chat", None)
        if str(getattr(chat, "type", "") or "") != "private":
            return False
        sender = getattr(message, "from_user", None)
        if sender is None or getattr(sender, "is_bot", False):
            return False
        text = str(getattr(message, "text", "") or "").strip()
        if not text:
            return False
        # Команда: /start, /streak, /admin_… — только если она в самом начале.
        for entity in (getattr(message, "entities", None) or ()):
            if str(getattr(entity, "type", "") or "") == "bot_command" and int(getattr(entity, "offset", 0) or 0) == 0:
                return True
        return _is_known_reply_menu_button(text)
    except Exception:
        return False


async def _track_user_menu_message(update: Update, context: CallbackContext) -> None:
    """Регистрирует нажатия меню и команды пользователя для ночной чистки — тем же
    механизмом, что и служебные сообщения бота. Best-effort, никогда не падает и
    ничего не блокирует."""
    try:
        message = getattr(update, "effective_message", None)
        if not _is_disposable_user_message(message):
            return
        await _track_telegram_message_async(message, USER_MENU_MESSAGE_TYPE)
    except Exception:
        logging.debug("Failed to track user menu message", exc_info=True)


def _inbox_kb_json(markup) -> list | None:
    """Serialize an InlineKeyboardMarkup → [[{text, url|callback_data}, …], …] so
    the interactive-inbox can later restore the card's buttons + prepend a ✅ row."""
    try:
        rows = getattr(markup, "inline_keyboard", None)
        if not rows:
            return None
        out: list[list[dict]] = []
        for row in rows:
            r: list[dict] = []
            for b in row:
                item = {"text": str(getattr(b, "text", "") or "")}
                if getattr(b, "url", None):
                    item["url"] = str(b.url)
                elif getattr(b, "callback_data", None):
                    item["callback_data"] = str(b.callback_data)
                else:
                    continue
                r.append(item)
            if r:
                out.append(r)
        return out or None
    except Exception:
        return None


def _inbox_kb_from_json(keyboard_json) -> list:
    """Rebuild inline-keyboard rows (list[list[InlineKeyboardButton]]) from the
    stored JSON, skipping any malformed buttons."""
    rows: list[list[InlineKeyboardButton]] = []
    for row in (keyboard_json or []):
        built: list[InlineKeyboardButton] = []
        for it in (row or []):
            if not isinstance(it, dict):
                continue
            text = str(it.get("text") or "").strip()
            if not text:
                continue
            if it.get("url"):
                built.append(InlineKeyboardButton(text, url=str(it["url"])))
            elif it.get("callback_data"):
                built.append(InlineKeyboardButton(text, callback_data=str(it["callback_data"])))
        if built:
            rows.append(built)
    return rows


