class TrackingExtBot(ExtBot):
    # ⛔️ Сообщение, на котором висит reply-клавиатура, удалять НЕЛЬЗЯ: Telegram снимает
    # клавиатуру вместе с ним, и у человека пропадает сама иконка ⌨ — кнопки «исчезают».
    # Ночная чистка это уже учитывала (тип reply_keyboard в исключениях), но обычные потоки
    # удаляют свои служебные сообщения напрямую (например, разбор переводов чистит за собой
    # хвост), и якорь мог попасть под нож. Здесь единственная дверь наружу: любой
    # delete_message в боте идёт через этот класс, поэтому проверка стоит один раз тут.
    _anchor_cache: dict[int, int] = {}

    @classmethod
    def remember_anchor(cls, chat_id: int, message_id: int) -> None:
        try:
            cls._anchor_cache[int(chat_id)] = int(message_id)
        except Exception:
            pass

    @classmethod
    async def _is_keyboard_anchor(cls, chat_id, message_id) -> bool:
        try:
            cid, mid = int(chat_id), int(message_id)
        except Exception:
            return False
        if cid <= 0:              # группы/каналы — там reply-клавиатуры нет
            return False
        cached = cls._anchor_cache.get(cid)
        if cached is not None:
            return cached == mid
        try:
            stored = await asyncio.to_thread(get_reply_keyboard_anchor, cid)
        except Exception:
            return False
        if stored is None:
            return False
        cls._anchor_cache[cid] = int(stored)
        return int(stored) == mid

    async def delete_message(self, chat_id, message_id, *args, **kwargs):
        if await self._is_keyboard_anchor(chat_id, message_id):
            logging.info(
                "reply_keyboard_anchor_delete_skipped chat_id=%s message_id=%s",
                chat_id, message_id,
            )
            return True
        return await super().delete_message(chat_id, message_id, *args, **kwargs)

    async def _track_single(self, msg, message_type: str):
        await _track_telegram_message_async(msg, message_type)
        return msg

    @staticmethod
    def _strip_internal_kwargs(kwargs):
        kwargs.pop("language_tutor_button", None)
        kwargs.pop("suppress_private_keyboard_attach", None)
        return kwargs

    @staticmethod
    def _resolve_dm_chat_id(args, kwargs) -> int | None:
        """Positive chat_id (a private chat) from args/kwargs, else None."""
        chat_id = kwargs.get("chat_id")
        if chat_id is None and args:
            chat_id = args[0]
        return int(chat_id) if isinstance(chat_id, int) and chat_id > 0 else None

    async def _ensure_dm_keyboard_after_send(self, args, kwargs, suppress: bool) -> None:
        """Guarantee the DM reply-keyboard for a message that could not carry it
        itself (photo/poll/inline-markup message). Honors suppress + swallows errors."""
        if suppress:
            return
        chat_id = self._resolve_dm_chat_id(args, kwargs)
        if chat_id is None:
            return
        try:
            await _ensure_reply_keyboard_delivered(self, chat_id)
        except Exception:
            pass

    async def send_message(self, *args, **kwargs):
        suppress_private_keyboard_attach = bool(kwargs.get("suppress_private_keyboard_attach"))
        kwargs = self._strip_internal_kwargs(kwargs)
        # Keep the DM reply-keyboard alive silently: piggyback it onto ordinary DM
        # text replies that don't already carry a markup (throttled per user), so
        # chatty users never lose the buttons and we never send standalone "menu"
        # messages to them. Whether we managed to carry the keyboard on THIS message
        # decides whether the guaranteed-delivery fallback needs to run below.
        chat_id = self._resolve_dm_chat_id(args, kwargs)
        carried_keyboard = False
        try:
            if chat_id is not None and not suppress_private_keyboard_attach:
                rm = kwargs.get("reply_markup")
                if rm is None:
                    if _kb_should_attach(chat_id):
                        kwargs["reply_markup"] = _build_private_language_tutor_reply_keyboard(chat_id)
                        carried_keyboard = True
                elif isinstance(rm, ReplyKeyboardMarkup):
                    _kb_last_attach[chat_id] = pytime.time()
                    carried_keyboard = True
        except Exception:
            pass
        msg = await super().send_message(*args, **kwargs)
        if chat_id is not None and not suppress_private_keyboard_attach:
            if carried_keyboard:
                await _mark_kb_delivered(chat_id)
                # This DM message carries the reply keyboard → make it the cleanup-exempt
                # anchor (records it itself) instead of a deletable "text" row, so the
                # nightly purge can't delete it and drop the keyboard.
                await _set_reply_keyboard_anchor(chat_id, msg)
                return msg
            await self._ensure_dm_keyboard_after_send(args, kwargs, suppress_private_keyboard_attach)
        return await self._track_single(msg, "text")

    async def send_photo(self, *args, **kwargs):
        suppress = bool(kwargs.get("suppress_private_keyboard_attach"))
        kwargs = self._strip_internal_kwargs(kwargs)
        msg = await super().send_photo(*args, **kwargs)
        await self._ensure_dm_keyboard_after_send(args, kwargs, suppress)
        return await self._track_single(msg, "photo")

    async def send_audio(self, *args, **kwargs):
        suppress = bool(kwargs.get("suppress_private_keyboard_attach"))
        kwargs = self._strip_internal_kwargs(kwargs)
        msg = await super().send_audio(*args, **kwargs)
        await self._ensure_dm_keyboard_after_send(args, kwargs, suppress)
        return await self._track_single(msg, "audio")

    async def send_voice(self, *args, **kwargs):
        suppress = bool(kwargs.get("suppress_private_keyboard_attach"))
