def _next_task_button_label(idx: int, task: dict) -> str:
    """Numbered, emoji-titled button label (≤60 chars for Telegram)."""
    title = str(task.get("title") or "").strip()
    if not title:
        title = _INBOX_KIND_DISPLAY.get(str(task.get("kind") or ""), "Задание")
    return f"▶️ {idx}. {title}"[:60]


async def _send_next_task_card(context: CallbackContext, chat_id: int, tasks: list,
                               open_count: int, *, kind_label: str | None = None,
                               show_chooser: bool = True, title_override: str | None = None) -> None:
    """Render the branded «Следующее задание» card with up to 3 deeplink buttons
    (+ optional «🎯 Выбрать тип» row). Shared by the button handler, the chooser and
    the windowed-release batch (title_override)."""
    rows = [[InlineKeyboardButton(_next_task_button_label(i, t), url=get_webapp_deeplink(str(t["deeplink"])))]
            for i, t in enumerate([t for t in tasks if t.get("deeplink")], 1)]
    if not rows:
        return
    if show_chooser:
        rows.append([InlineKeyboardButton("🎯 Выбрать тип", callback_data="nxt:menu")])
    kb = InlineKeyboardMarkup(rows)
    n = len(rows) - (1 if show_chooser else 0)
    scope = f" · {kind_label}" if kind_label else ""
    head = title_override or (f"Твоё невыполненное задание за сегодня{scope}" if n == 1
                              else f"Твои {n} самых старых невыполненных за сегодня{scope}")
    more = f"\nВсего не сделано сегодня: <b>{open_count}</b>." if open_count > n else ""
    streak_line = ""
    try:
        _blk = await _streak_status_block(int(chat_id))
        if _blk:
            streak_line = f"{_blk}\n"
    except Exception:
        pass
    caption = f"{streak_line}📋 <b>{head}</b>\nОткрой и реши прямо тут, не листая чат 👇{more}"
    poster = await asyncio.to_thread(_next_task_card_bytes)
    if poster:
        await context.bot.send_photo(chat_id=int(chat_id), photo=io.BytesIO(poster),
                                     caption=caption, parse_mode="HTML", reply_markup=kb)
    else:
        await context.bot.send_message(chat_id=int(chat_id), text=caption,
                                       parse_mode="HTML", reply_markup=kb)


def _pull_budget_for(user_id: int) -> tuple[int, bool]:
    """Daily budget for an ON-DEMAND «Следующее задание» pull, and whether the user is
    Pro. Unlike push budgets this ignores the Free inactivity suppression (an explicit
    tap IS activity) and lets «Тишина» Pro pull a normal amount (silent = no auto push,
    but pull-on-demand still serves them)."""
    try:
        is_pro = bool(_is_user_pro_cached(int(user_id)))
    except Exception:
        is_pro = False
    if not is_pro:
        return FREE_SEND_BUDGET, False
    preset = None
    try:
        prefs = get_user_prefs(int(user_id))
        preset = (prefs or {}).get("preset")
    except Exception:
        prefs = None
    budget = _preset_budget(preset)
    if budget <= 0:  # «Тишина»: no automatic push, but on-demand pull still delivers
        budget = DEFAULT_PRO_SEND_BUDGET
    return budget, True


async def _try_pull_next_task(context: CallbackContext, user_id: int, chat_id: int,
                              since_ts, now) -> str:
    """Silent pull-from-pool for «Следующее задание» when the inbox is empty. Within the
    user's REMAINING daily budget, stock up to NEXT_TASK_PULL_BATCH tasks into the inbox
    WITHOUT sending each card (held=True), then show them on ONE branded plaque — same UX
    as a non-empty inbox. The daily total never exceeds the preset budget; this only changes
    pacing (a batch of up to 3 of the remaining allowance per tap instead of one at a time).
    Returns "sent" | "exhausted" (budget used up) | "none" (pool gave nothing). Serves Free
    (cap stays a conversion lever), «Тишина» Pro, and fresh accounts the schedule hasn't
    reached yet."""
    budget, is_pro = await asyncio.to_thread(_pull_budget_for, int(user_id))
    if budget <= 0:
        return "exhausted"
    try:
        count, _last = await asyncio.to_thread(get_inbox_delivery_stats_today, int(user_id), since_ts)
    except Exception:
        count = 0
    if count >= budget:
        return "exhausted"
    want = min(NEXT_TASK_PULL_BATCH, budget - count)
    pulled = 0
    for _ in range(want):
        try:
            if await _drip_deliver_one(context, int(user_id), int(count + pulled), now, held=True):
                pulled += 1
            else:
                break  # pool is dry for every kind right now
        except Exception:
            logging.warning("next_task batch pull failed user=%s", user_id, exc_info=True)
            break
    if pulled <= 0:
        return "none"
    logging.info("next_task: stocked-on-demand user=%s pulled=%s count=%s budget=%s",
                 user_id, pulled, count, budget)
    try:
        data = await asyncio.to_thread(get_inbox_open_today, int(user_id),
                                       since_ts=since_ts, limit=NEXT_TASK_PULL_BATCH)
        tasks = [t for t in (data.get("tasks") or []) if t.get("deeplink")]
        open_count = int(data.get("open_count") or 0)
    except Exception:
        logging.warning("next_task: post-pull lookup failed user=%s", user_id, exc_info=True)
        tasks, open_count = [], 0
    if not tasks:
        return "none"
    # The plaque below IS the delivery of these freshly-stocked held rows — flip them to
    # pushed so the windowed-release job won't re-send them later as a second batch. Safe
    # here because this path only runs on an empty inbox (no pre-existing held rows today).
    try:
        await asyncio.to_thread(mark_inbox_pushed, int(user_id), since_ts=since_ts)
    except Exception:
        logging.warning("next_task: mark_inbox_pushed failed user=%s", user_id, exc_info=True)
    await _send_next_task_card(context, chat_id, tasks, open_count)
    return "sent"


async def _send_next_open_task(update: Update, context: CallbackContext) -> None:
    """«▶️ Следующее задание» — collect the user's oldest still-open tasks FROM TODAY
    as up to 3 buttons on one branded card, so they don't scroll the chat to find them."""
    if not update.effective_message or not update.effective_user:
        return
    user_id = int(update.effective_user.id)
    chat_id = int(update.effective_chat.id) if update.effective_chat else user_id
    t0 = pytime.time()
    logging.info("next_task: tapped user=%s", user_id)
    # Instant "typing…" so the tap never feels like it crashed while we look up.
    try:
        await context.bot.send_chat_action(chat_id=chat_id, action="typing")
    except Exception:
        pass
    now = _get_quiz_schedule_now()
    since_ts = now.replace(hour=0, minute=0, second=0, microsecond=0)
    try:
        data = await asyncio.to_thread(get_inbox_open_today, user_id, since_ts=since_ts, limit=3)
        tasks = [t for t in (data.get("tasks") or []) if t.get("deeplink")]
        open_count = int(data.get("open_count") or 0)
    except Exception:
        logging.warning("next-task lookup failed user=%s", user_id, exc_info=True)
        tasks, open_count = [], 0
    logging.info("next_task: lookup done user=%s open_today=%s shown=%s elapsed_ms=%d",
                 user_id, open_count, len(tasks), int((pytime.time() - t0) * 1000))
    if not tasks:
        # Inbox empty for today — don't assume "всё решено". The schedule may not have
        # reached this user yet (fresh/Free account), or they chose «Тишина» (no push).
        # Pull the next task from the pre-stocked pool ON DEMAND, within their daily
        # budget (Free cap stays a conversion lever). The pulled card is the answer.
        status = await _try_pull_next_task(context, user_id, chat_id, since_ts, now)
        if status == "sent":
            return
        if status == "exhausted":
            try:
                is_pro = await asyncio.to_thread(_is_user_pro_cached, user_id)
            except Exception:
                is_pro = True
            if not is_pro:
                await update.message.reply_text(
                    "✅ <b>На сегодня всё!</b>\n\n"
                    "Ты разобрал все задания на сегодня. Хочешь больше прямо сейчас — "
                    "это открывается в «Полном доступе» 🔒. Иначе новые придут завтра 👍",
                    parse_mode="HTML",
                )
            else:
                await update.message.reply_text(
                    "✅ <b>На сегодня всё решено!</b>\n\n"
                    "Эта кнопка собирает твои невыполненные задания за сегодня (квиз, ребус, кроссворд, "
                    "анаграмма, Aufgabe, аудирование). Новые приходят по расписанию — загляни позже 👍",
                    parse_mode="HTML",
                )
            return
        # status == "none": budget remained but the pool gave nothing right now.
        await update.message.reply_text(
            "⏳ <b>Секунду — новые задания готовятся.</b>\n\n"
            "Сейчас в очереди пусто. Загляни чуть позже — подвезём свежие 👍",
            parse_mode="HTML",
        )
        return
    await _send_next_task_card(context, chat_id, tasks, open_count)


async def _next_task_chooser_callback(update: Update, context: CallbackContext) -> None:
    """«🎯 Выбрать тип» on the next-task card. nxt:menu → list the kinds the user has
    open today; nxt:k:<kind> → that kind's 3 oldest; nxt:all → back to the mix; for
    Free users a «🔒 Другие типы — в «Полном доступе»» hint nudges conversion at the point of interest."""
    query = update.callback_query
    if not query or not query.from_user:
        return
    data = str(query.data or "")
    user_id = int(query.from_user.id)
    chat_id = int(query.message.chat_id) if query.message else user_id
    now = _get_quiz_schedule_now()
    since_ts = now.replace(hour=0, minute=0, second=0, microsecond=0)

    if data == "nxt:locked":
        await query.answer("Эти типы заданий открываются в «Полном доступе» 🔒", show_alert=True)
        return

    if data == "nxt:menu":
        try:
            kinds = await asyncio.to_thread(get_inbox_open_kinds_today, user_id, since_ts=since_ts)
        except Exception:
            kinds = []
        await query.answer()
        if not kinds:
            await context.bot.send_message(chat_id=chat_id, text="✅ На сегодня всё решено — выбирать нечего.")
            return
        rows = [[InlineKeyboardButton(f"{_INBOX_KIND_DISPLAY.get(k, k)} · {cnt}", callback_data=f"nxt:k:{k}")]
                for k, cnt in kinds]
        try:
            is_pro = await asyncio.to_thread(_is_user_pro_cached, user_id)
        except Exception:
            is_pro = True
        if not is_pro:
            rows.append([InlineKeyboardButton("🔒 Другие типы — в «Полном доступе»", callback_data="nxt:locked")])
        rows.append([InlineKeyboardButton("⬅️ Все вперемешку", callback_data="nxt:all")])
        await context.bot.send_message(
            chat_id=chat_id, text="🎯 <b>Какой тип задания показать?</b>", parse_mode="HTML",
            reply_markup=InlineKeyboardMarkup(rows))
        return

    if data == "nxt:all" or data.startswith("nxt:k:"):
        kind = None if data == "nxt:all" else data.split(":", 2)[2]
        try:
            res = await asyncio.to_thread(get_inbox_open_today, user_id, since_ts=since_ts, limit=3, kind=kind)
            tasks = [t for t in (res.get("tasks") or []) if t.get("deeplink")]
            open_count = int(res.get("open_count") or 0)
        except Exception:
            tasks, open_count = [], 0
        await query.answer()
        if not tasks:
            await context.bot.send_message(chat_id=chat_id, text="✅ Заданий этого типа на сегодня нет.")
            return
        label = _INBOX_KIND_DISPLAY.get(kind) if kind else None
        await _send_next_task_card(context, chat_id, tasks, open_count, kind_label=label)
        return

    await query.answer()


# Pro delivery presets (Этап 3c). «custom» (per-type mask) lands with the Mini-App UI.
_PRESET_PICKER = [
    ("intensive", "🔥 Интенсивно", "~20 заданий в день — весь поток"),
    ("normal",    "🙂 Обычно",     "~12 в день (по умолчанию)"),
    ("rare",      "🌙 Редко",      "~8 в день"),
    ("silent",    "🔕 Тишина",     "не присылаю автоматически"),
]
_PRESET_LABELS = {code: label for code, label, _ in _PRESET_PICKER}


def _sched_labels(prefs) -> tuple:
    """(preset_code, window_key, preset_label, window_label) for the current prefs."""
    cur = str((prefs or {}).get("preset") or "normal")
    cur_win = _current_window_key((prefs or {}).get("schedule"))
    preset_label = _PRESET_LABELS.get(cur, "🙂 Обычно")
    win_label = _WINDOW_PRESETS.get(cur_win or "allday", ("⚙️ свои часы", None))[0] if cur_win is not None else "⚙️ свои часы"
    return cur, cur_win, preset_label, win_label


def _render_sched_step1(prefs) -> tuple:
    """Step 1/2 — pick intensity."""
    cur, _, _, _ = _sched_labels(prefs)
    lines = ["🗓 <b>Расписание · шаг 1 из 2</b>", "", "<b>Сколько заданий в день?</b>", ""]
    for code, label, desc in _PRESET_PICKER:
        lines.append(("✅ " if code == cur else "• ") + f"<b>{label}</b> — {desc}")
    rows = [[InlineKeyboardButton(("✅ " if code == cur else "") + label, callback_data=f"pset:{code}")]
            for code, label, _ in _PRESET_PICKER]
    return "\n".join(lines), InlineKeyboardMarkup(rows)


def _render_sched_step2a(prefs) -> tuple:
    """Step 2, hours pick — ONLY the window options + «К интенсивности». No «Подтвердить»
    yet (it must not sit among the hour options). Picking a window advances to 2b."""
    _, cur_win, preset_label, _ = _sched_labels(prefs)
    lines = ["🗓 <b>Расписание · шаг 2 из 2</b>", "",
             f"Интенсивность: <b>{preset_label}</b>", "",
             "<b>В какие часы присылать?</b> (по твоему времени)"]
    rows = [[InlineKeyboardButton(("✅ " if key == cur_win else "") + label, callback_data=f"pwin:{key}")]
            for key, (label, _w) in _WINDOW_PRESETS.items()]
    rows.append([InlineKeyboardButton("⬅️ К интенсивности", callback_data="sch:open")])
    return "\n".join(lines), InlineKeyboardMarkup(rows)


def _render_sched_step2b(prefs) -> tuple:
    """Step 2, after a window is chosen — the hour options DISAPPEAR; only «Подтвердить»
    + «К выбору времени» remain (one confirm, one back), so the screen stays clean."""
    _, _, preset_label, win_label = _sched_labels(prefs)
    lines = ["🗓 <b>Расписание · шаг 2 из 2</b>", "",
             f"Интенсивность: <b>{preset_label}</b>",
             f"Время: <b>{win_label}</b>", "",
             "Всё верно?"]
    rows = [[InlineKeyboardButton("✅ Подтвердить расписание", callback_data="sch:done")],
            [InlineKeyboardButton("⬅️ К выбору времени", callback_data="sch:time")]]
    return "\n".join(lines), InlineKeyboardMarkup(rows)


def _render_sched_collapsed(prefs) -> tuple:
    """Collapsed — one button showing the current settings; tap to re-edit."""
    _, _, preset_label, win_label = _sched_labels(prefs)
    text = ("🗓 <b>Расписание сохранено</b>\n"
            f"Сейчас: <b>{preset_label} · {win_label}</b>.\nНажми кнопку, чтобы изменить.")
    rows = [[InlineKeyboardButton(f"🗓 {preset_label} · {win_label}", callback_data="sch:open")]]
    return text, InlineKeyboardMarkup(rows)


async def _send_schedule_picker(update: Update, context: CallbackContext) -> None:
    """«🗓 Расписание» — Pro: 2-step wizard (intensity → hours → confirm)."""
    if not update.effective_message or not update.effective_user:
        return
    user_id = int(update.effective_user.id)
    if not await asyncio.to_thread(is_user_pro, user_id):
        await update.message.reply_text(
            "🗓 <b>Расписание</b> — настройка для «Полного доступа».\n\n"
            "На бесплатном тарифе — подборка из 4 заданий в день. "
            "«Полный доступ» открывает гибкое расписание и до 20 заданий в день 🔓",
            parse_mode="HTML")
        return
    prefs = await asyncio.to_thread(get_user_prefs, user_id)
    text, kb = _render_sched_step1(prefs)
    await update.message.reply_text(text, parse_mode="HTML", reply_markup=kb)


async def _sched_edit(query, render_fn, user_id: int) -> None:
    prefs = await asyncio.to_thread(get_user_prefs, user_id)
    text, kb = render_fn(prefs)
    try:
        await query.edit_message_text(text, parse_mode="HTML", reply_markup=kb)
    except Exception:
        pass


async def _schedule_preset_callback(update: Update, context: CallbackContext) -> None:
    """pset:<preset> — save intensity, advance to the hours step."""
    query = update.callback_query
    if not query or not query.from_user:
        return
    user_id = int(query.from_user.id)
    code = (query.data or "").split(":", 1)[1] if ":" in (query.data or "") else ""
    if code not in _PRESET_LABELS:
        await query.answer()
        return
    if not await asyncio.to_thread(is_user_pro, user_id):
        await query.answer("Расписание доступно в «Полном доступе» 🔒", show_alert=True)
        return
    ok = await asyncio.to_thread(set_user_preset, user_id, code)
    await query.answer("Сохранено ✅" if ok else "Не удалось сохранить")
    if ok:
        await _sched_edit(query, _render_sched_step2a, user_id)


async def _schedule_window_callback(update: Update, context: CallbackContext) -> None:
    """pwin:<key> — save active hours, stay on the hours step (now ticked)."""
    query = update.callback_query
    if not query or not query.from_user:
        return
    user_id = int(query.from_user.id)
    key = (query.data or "").split(":", 1)[1] if ":" in (query.data or "") else ""
    if key not in _WINDOW_PRESETS:
        await query.answer()
        return
    if not await asyncio.to_thread(is_user_pro, user_id):
        await query.answer("Расписание доступно в «Полном доступе» 🔒", show_alert=True)
        return
    ok = await asyncio.to_thread(set_user_schedule, user_id, _window_schedule_for(key))
    await query.answer("Сохранено ✅ — жми «Подтвердить»" if ok else "Не удалось сохранить")
    if ok:
        # Window picked → hour options disappear; show only «Подтвердить» / «К выбору времени».
        await _sched_edit(query, _render_sched_step2b, user_id)


async def _schedule_nav_callback(update: Update, context: CallbackContext) -> None:
    """sch:done → collapse to one button; sch:time → back to the hours pick (step 2a);
    sch:open → reopen the wizard at step 1 (intensity)."""
    query = update.callback_query
    if not query or not query.from_user:
        return
    user_id = int(query.from_user.id)
    action = (query.data or "").split(":", 1)[1] if ":" in (query.data or "") else ""
    if not await asyncio.to_thread(is_user_pro, user_id):
        await query.answer("Расписание доступно в «Полном доступе» 🔒", show_alert=True)
        return
    await query.answer()
    render_fn = {
        "done": _render_sched_collapsed,
        "time": _render_sched_step2a,
    }.get(action, _render_sched_step1)
    await _sched_edit(query, render_fn, user_id)


