async def _interaktiv_test_command(update: Update, context: CallbackContext) -> None:
    """/interaktiv_test — меню со всеми интерактивами: по кнопке на каждый вид."""
    if not update.effective_user or not update.effective_message:
        return
    uid = int(update.effective_user.id)
    try:
        from backend.database import get_latest_interactive_dispatch_ids
        latest = await asyncio.to_thread(get_latest_interactive_dispatch_ids, uid)
    except Exception as exc:
        logging.warning("interaktiv_test_lookup_failed uid=%s err=%s", uid, exc)
        latest = {}

    rows: list[list[InlineKeyboardButton]] = []
    pending: list[InlineKeyboardButton] = []
    for label, kind in _INTERACTIVE_ALWAYS:
        pending.append(InlineKeyboardButton(label, url=get_webapp_deeplink(f"ans_{kind}_0")))
        if len(pending) == 2:
            rows.append(pending); pending = []
    missing: list[str] = []
    for label, kind, note in _INTERACTIVE_BY_TASK:
        task_id = latest.get(kind)
        if not task_id:
            missing.append(f"{label} — {note}")
            continue
        pending.append(InlineKeyboardButton(label, url=get_webapp_deeplink(f"ans_{kind}_{int(task_id)}")))
        if len(pending) == 2:
            rows.append(pending); pending = []
    if pending:
        rows.append(pending)

    lines = ["🧪 <b>Интерактивы — открыть вручную</b>",
             "Каждая кнопка открывает свой вид игры прямо в приложении."]
    if missing:
        lines.append("")
        lines.append("Пока нечего открыть (нужно задание, оно придёт само):")
        lines.extend(f"• {m}" for m in missing)
    await update.effective_message.reply_text(
        "\n".join(lines),
        parse_mode="HTML",
        reply_markup=InlineKeyboardMarkup(rows) if rows else None,
        disable_web_page_preview=True,
    )


async def _streak_command(update: Update, context: CallbackContext) -> None:
    """/streak — quiet alias (no longer a menu button): the status block + freeze/
    earned-Pro detail."""
    if not update.effective_user or not update.effective_message:
        return
    uid = int(update.effective_user.id)
    block = await _streak_status_block(uid)
    st = await asyncio.to_thread(get_user_streak, uid)
    cur = int(st.get("current_streak") or 0); longest = int(st.get("longest_streak") or 0)
    freezes = int(st.get("freezes") or 0)
    try:
        grant_until = await asyncio.to_thread(get_active_pro_grant, uid)
    except Exception:
        grant_until = None
    lines = [block or "🔥 Стрик: 0"]
    if longest > cur:
        lines.append(f"🏆 Рекорд: {longest}")
    if freezes:
        lines.append(f"❄️ Заморозки: {freezes} (спасают стрик при одном пропуске)")
    if grant_until:
        try:
            lines.append(f"⭐ Заработанный доступ активен до {grant_until.strftime('%d.%m %H:%M')}")
        except Exception:
            pass
    await update.effective_message.reply_text("\n".join(lines), parse_mode="HTML")


async def _maybe_capture_referral(context: CallbackContext, update: Update, invited_uid: int) -> None:
    """Parse a ?start=ref_<referrer_id> deeplink → first-touch attribution. Only NEW
    users (not yet allowed) are referrable; the referrer must be a real allowed user.
    DMs the referrer once when a new referral row is created. Reward fires later, when
    the invited user reaches REFERRAL_STREAK_TRIGGER (in _update_streaks_job)."""
    args = context.args or []
    if not args:
        return
    payload = str(args[0] or "").strip()
    if not payload.startswith("ref_"):
        return
    try:
        referrer_uid = int(payload[4:])
    except Exception:
        return
    if referrer_uid <= 0 or referrer_uid == int(invited_uid):
        return
    # Existing (already-allowed) users can't be "referred".
    if await asyncio.to_thread(is_telegram_user_allowed, int(invited_uid)):
        return
    # Guard ref_<garbage>: the referrer must be a real allowed user.
    if not await asyncio.to_thread(is_telegram_user_allowed, referrer_uid):
        return
    newly = await asyncio.to_thread(record_referral, int(invited_uid), referrer_uid)
    if not newly:
        return
    inv_name = (update.effective_user.first_name if update.effective_user else "") or "Друг"
    try:
        await context.bot.send_message(
            chat_id=referrer_uid, parse_mode="HTML",
            text=(f"🎉 <b>{html.escape(inv_name)}</b> перешёл по твоей ссылке!\n"
                  f"Как только он позанимается {REFERRAL_STREAK_TRIGGER} дня подряд — "
                  f"вы <b>оба</b> получите <b>+{REFERRAL_REWARD_DAYS} дней полного доступа</b> 🔥"))
    except Exception:
        pass


