async def _deliver_shortcut_connect_flow(user_id: int, reply_text: Callable[[str], Any]) -> None:
    base_url = get_public_web_url()
    admin_secret, admin_secret_source = _shortcut_admin_secret()
    if not base_url or not admin_secret:
        logging.error(
            "shortcut pairing unavailable base_url=%s secret_present=%s secret_source=%s app_base_url=%s backend_web_url=%s",
            bool(base_url),
            bool(admin_secret),
            admin_secret_source or "-",
            bool((os.getenv("APP_BASE_URL") or "").strip()),
            bool((os.getenv("BACKEND_WEB_URL") or "").strip()),
        )
        await reply_text("Подключение временно недоступно. Попробуйте позже.")
        return

    try:
        def _request_pairing_code() -> dict:
            logging.info(
                "shortcut pairing request start user_id=%s base_url=%s secret_source=%s",
                int(user_id),
                base_url,
                admin_secret_source or "-",
            )
            response = requests.post(
                f"{base_url.rstrip('/')}/api/shortcut/pairing-code",
                headers={
                    "Authorization": f"Bearer {admin_secret}",
                    "Content-Type": "application/json",
                },
                json={"user_id": int(user_id)},
                timeout=12,
            )
            try:
                payload = response.json()
            except Exception:
                payload = {"error": response.text[:500]}
            if response.status_code != 200:
                error_text = str(payload.get("error") or "").strip()
                logging.error(
                    "shortcut pairing request failed user_id=%s base_url=%s secret_source=%s http_status=%s error=%s body=%s",
                    int(user_id),
                    base_url,
                    admin_secret_source or "-",
                    response.status_code,
                    error_text or "-",
                    json.dumps(payload, ensure_ascii=False)[:500],
                )
                raise RuntimeError(
                    f"shortcut pairing code request failed http={response.status_code} error={error_text}"
                )
            logging.info(
                "shortcut pairing request success user_id=%s base_url=%s secret_source=%s http_status=%s",
                int(user_id),
                base_url,
                admin_secret_source or "-",
                response.status_code,
            )
            return payload

        result = await asyncio.to_thread(_request_pairing_code)
    except Exception as exc:
        logging.exception("shortcut connect failed user_id=%s: %s", int(user_id), exc)
        await reply_text("Не удалось создать pairing code. Попробуйте еще раз.")
        return

    await reply_text(
        _build_shortcut_onboarding_code_text(
            pairing_code=str(result.get("pairing_code") or "").strip(),
            expires_at=result.get("expires_at"),
        )
    )
    await reply_text(_build_shortcut_onboarding_instructions())


async def handle_shortcut_connect_callback(update: Update, context: CallbackContext):
    query = update.callback_query
    user = update.effective_user
    if not query or not user:
        return
    if not is_telegram_user_allowed(int(user.id)):
        try:
            await query.answer("Shortcut доступен только после выдачи доступа.", show_alert=True)
        except Exception:
            pass
        return

    try:
        await query.answer("Генерирую pairing code...", show_alert=False)
    except Exception:
        pass

    if query.message:
        try:
            await query.message.reply_text("⏳ Генерирую pairing code...")
        except Exception:
            pass

    async def _reply(text: str) -> None:
        if query.message:
            await query.message.reply_text(text)
        else:
            await context.bot.send_message(chat_id=int(user.id), text=text)
    try:
        context.application.create_task(_deliver_shortcut_connect_flow(int(user.id), _reply))
    except Exception:
        await _deliver_shortcut_connect_flow(int(user.id), _reply)


# ===== Semi-annual "Классика" (public library) audit → admin DM + checkbox delete ======
# Twice a year the admin gets a readership report of the public-domain shelf and can
# prune books nobody reads. Selection state lives in Redis (Pattern A, mirrors the
# autosave digest below); deleting a book removes its row (cascades audio-page +
# progress rows), the book text/pages (columns), and its R2 mp3 objects.

def _pubaudit_digest_redis_key(digest_id: str) -> str:
    return f"pubaudit_digest:{digest_id}"


def _pubaudit_read_digest(digest_id: str) -> dict | None:
    from backend.job_queue import get_redis_client
    client = get_redis_client()
    if client is None:
        return None
    raw = client.get(_pubaudit_digest_redis_key(digest_id))
    if not raw:
        return None
    try:
        return json.loads(raw.decode("utf-8") if isinstance(raw, bytes) else raw)
    except Exception:
        return None


def _pubaudit_write_digest(digest_id: str, state: dict, ttl: int = 604800) -> None:
    from backend.job_queue import get_redis_client
    client = get_redis_client()
    if client is None:
        return
    client.set(_pubaudit_digest_redis_key(digest_id), json.dumps(state, ensure_ascii=False), ex=ttl)


def _pubaudit_delete_digest(digest_id: str) -> None:
    from backend.job_queue import get_redis_client
    client = get_redis_client()
    if client is not None:
        try:
            client.delete(_pubaudit_digest_redis_key(digest_id))
        except Exception:
            pass


def _pubaudit_build_keyboard(digest_id: str, items: list, selected: list) -> InlineKeyboardMarkup:
    """Number-toggle checkboxes (the book titles live in the message body), 5 per row.
    Nothing is pre-selected — the admin opts IN the books to delete. The delete footer
    appears only once ≥1 book is checked (so an empty tap can't trigger anything)."""
    rows = []
    row = []
    for idx in range(len(items)):
        on = idx < len(selected) and selected[idx]
        row.append(InlineKeyboardButton(
            f"{'☑️' if on else '⬜️'} {idx + 1}",
            callback_data=f"pubaud_tog:{digest_id}:{idx}",
        ))
        if len(row) == 5:
            rows.append(row)
            row = []
    if row:
        rows.append(row)
    count = sum(1 for s in selected if s)
    if count > 0:
        rows.append([InlineKeyboardButton(
            f"🗑 Удалить выбранные ({count})", callback_data=f"pubaud_del:{digest_id}")])
    return InlineKeyboardMarkup(rows)


def _pubaudit_build_confirm_keyboard(digest_id: str, count: int) -> InlineKeyboardMarkup:
    return InlineKeyboardMarkup([
        [InlineKeyboardButton(f"⚠️ Да, удалить {count} — навсегда", callback_data=f"pubaud_go:{digest_id}")],
        [InlineKeyboardButton("↩️ Отмена", callback_data=f"pubaud_cancel:{digest_id}")],
    ])


def _pubaudit_format_report(rows: list, period_months: int) -> str:
    lines = [
        f"📚 <b>Аудит «Классики» за {period_months} мес.</b>",
        "Кто сколько читал + вес аудио. Отметь книги галочками и нажми «Удалить».",
        "",
    ]
    for idx, r in enumerate(rows):
        title = html.escape(str(r.get("title") or "—"))
        author = html.escape(str(r.get("public_author") or "").strip())
        who = f" — {author}" if author else ""
        readers = int(r.get("readers_period") or 0)
        fin = int(r.get("finishers_period") or 0)
        avg = float(r.get("avg_progress") or 0)
        allr = int(r.get("readers_all") or 0)
        mb = float(r.get("audio_bytes") or 0) / (1024 * 1024)
        pages = int(r.get("pages_cached") or 0)
        lines.append(
            f"<b>{idx + 1}. {title}</b>{who}\n"
            f"   👥 читали: {readers} · дочитали: {fin} · ср. {avg:.0f}% · за всё время: {allr}\n"
            f"   🎧 аудио: {pages} стр (~{mb:.0f} МБ)"
        )
    lines.append("")
    lines.append("Ничего не выбрано → ничего не удаляется. Кнопка удаления появится после выбора.")
    return "\n".join(lines)


async def send_public_library_audit_report(application, *, period_months: int = 6) -> dict:
    """DM every admin the Классика readership audit with a checkbox keyboard to prune
    unread books. Scheduled twice a year (1 Jan / 1 Jul); also on-demand via
    /reader_public_audit. Each admin gets their own Redis-backed digest."""
    from backend.database import get_admin_telegram_ids, get_public_library_audit_rows
    try:
        rows = await asyncio.to_thread(get_public_library_audit_rows, period_months)
    except Exception:
        logging.exception("public library audit: fetch rows failed")
        rows = []
    try:
        admin_ids = [int(a) for a in (await asyncio.to_thread(get_admin_telegram_ids) or []) if int(a) > 0]
    except Exception:
        admin_ids = []
    if not admin_ids:
        return {"ok": False, "error": "no_admins"}
    if not rows:
        for admin_id in admin_ids:
            try:
                await application.bot.send_message(
                    chat_id=admin_id, text="📚 <b>Аудит «Классики»</b>\n\nВ полке пока нет книг.",
                    parse_mode="HTML")
            except Exception:
                logging.warning("public library audit: empty DM failed admin=%s", admin_id, exc_info=True)
        return {"ok": True, "books": 0}

    text = _pubaudit_format_report(rows, period_months)
    items = [{"document_id": int(r.get("id")), "title": str(r.get("title") or "")} for r in rows]
    sent = 0
    for admin_id in admin_ids:
        digest_id = hashlib.sha1(os.urandom(16)).hexdigest()[:16]
        state = {"user_id": int(admin_id), "items": items, "selected": [False] * len(items)}
        _pubaudit_write_digest(digest_id, state)
        try:
            await application.bot.send_message(
                chat_id=admin_id,
                text=text,
                parse_mode="HTML",
                reply_markup=_pubaudit_build_keyboard(digest_id, items, state["selected"]),
            )
            sent += 1
        except Exception:
            logging.warning("public library audit: DM failed admin=%s", admin_id, exc_info=True)
    return {"ok": True, "books": len(items), "sent": sent}


async def _public_library_audit_report_job(context: CallbackContext) -> None:
    """Scheduler entry (twice a year). Kept tiny; the real work is in the sender."""
    try:
        result = await send_public_library_audit_report(context.application, period_months=6)
        logging.info("public library audit report result=%s", result)
    except Exception:
        logging.exception("public library audit report job failed")


async def handle_pubaudit_toggle_callback(update: Update, context: CallbackContext) -> None:
    query = update.callback_query
    if not query or not query.from_user:
        return
    parts = (query.data or "").split(":")
    if len(parts) != 3:
        await query.answer("Неверный формат.")
        return
    digest_id = parts[1]
    try:
        idx = int(parts[2])
    except ValueError:
        await query.answer("Неверный индекс.")
        return
    state = _pubaudit_read_digest(digest_id)
    if not state:
        await query.answer("Отчёт устарел.", show_alert=True)
        return
    if int(state.get("user_id", 0)) != int(query.from_user.id):
        await query.answer("Доступно только администратору.", show_alert=True)
        return
    selected = state.get("selected") or []
    items = state.get("items") or []
    if idx < 0 or idx >= len(selected):
        await query.answer("Книга не найдена.")
        return
    selected[idx] = not bool(selected[idx])
    state["selected"] = selected
    _pubaudit_write_digest(digest_id, state)
    try:
        await query.edit_message_reply_markup(
            reply_markup=_pubaudit_build_keyboard(digest_id, items, selected))
    except Exception:
        pass
    await query.answer("Отмечена к удалению ☑️" if selected[idx] else "Снята")


async def handle_pubaudit_delete_callback(update: Update, context: CallbackContext) -> None:
    """First tap on «Удалить» → show a confirm keyboard (deletion is irreversible)."""
    query = update.callback_query
    if not query or not query.from_user:
        return
    parts = (query.data or "").split(":")
    digest_id = parts[1] if len(parts) >= 2 else ""
    state = _pubaudit_read_digest(digest_id)
    if not state:
        await query.answer("Отчёт устарел.", show_alert=True)
        return
    if int(state.get("user_id", 0)) != int(query.from_user.id):
        await query.answer("Доступно только администратору.", show_alert=True)
        return
    count = sum(1 for s in (state.get("selected") or []) if s)
    if count <= 0:
        await query.answer("Отметьте хотя бы одну книгу.", show_alert=True)
        return
    try:
        await query.edit_message_reply_markup(reply_markup=_pubaudit_build_confirm_keyboard(digest_id, count))
    except Exception:
        pass
    await query.answer()


async def handle_pubaudit_cancel_callback(update: Update, context: CallbackContext) -> None:
    query = update.callback_query
    if not query or not query.from_user:
        return
    parts = (query.data or "").split(":")
    digest_id = parts[1] if len(parts) >= 2 else ""
    state = _pubaudit_read_digest(digest_id)
    if not state:
        await query.answer("Отчёт устарел.", show_alert=True)
        return
    try:
        await query.edit_message_reply_markup(
            reply_markup=_pubaudit_build_keyboard(digest_id, state.get("items") or [], state.get("selected") or []))
    except Exception:
        pass
    await query.answer("Отменено")


async def handle_pubaudit_go_callback(update: Update, context: CallbackContext) -> None:
    """Confirmed delete: purge each selected public book fully (row + cascaded audio/
    progress rows + R2 mp3 objects). Consumes the digest so a stray tap can't re-run."""
    query = update.callback_query
    if not query or not query.from_user:
        return
    parts = (query.data or "").split(":")
    digest_id = parts[1] if len(parts) >= 2 else ""
    state = _pubaudit_read_digest(digest_id)
    if not state:
        await query.answer("Отчёт устарел.", show_alert=True)
        return
    if int(state.get("user_id", 0)) != int(query.from_user.id) or not _is_admin_user(query.from_user.id):
        await query.answer("Доступно только администратору.", show_alert=True)
        return
    items = state.get("items") or []
    selected = state.get("selected") or []
    chosen = [items[i] for i in range(len(items)) if i < len(selected) and selected[i]]
    if not chosen:
        await query.answer("Ничего не выбрано.", show_alert=True)
        return
    try:
        await query.answer("Удаляю…")
    except Exception:
        pass
    try:
        await query.edit_message_reply_markup(reply_markup=None)
    except Exception:
        pass
    _pubaudit_delete_digest(digest_id)  # consume → no double-processing

    from backend.database import delete_public_library_document
    from backend.r2_storage import r2_delete_prefix, r2_delete_object, r2_key_from_public_url

    deleted_titles: list[str] = []
    failed: list[str] = []
    for it in chosen:
        doc_id = int(it.get("document_id") or 0)
        if doc_id <= 0:
            continue
        try:
            res = await asyncio.to_thread(delete_public_library_document, doc_id)
        except Exception:
            logging.exception("public audit delete: DB delete failed doc=%s", doc_id)
            res = {"ok": False}
        if not res.get("ok"):
            failed.append(str(it.get("title") or doc_id))
            continue
        # R2 mp3s are NOT FK-cascaded — remove the whole per-book prefix, then mop up any
        # stragglers by their stored URLs (belt-and-suspenders; the prefix should cover all).
        try:
            await asyncio.to_thread(r2_delete_prefix, f"reader-audio-pages/0/{doc_id}/")
        except Exception:
            logging.warning("public audit delete: R2 prefix delete failed doc=%s", doc_id, exc_info=True)
        for url in (res.get("audio_urls") or []):
            key = r2_key_from_public_url(url)
            if key:
                try:
                    await asyncio.to_thread(r2_delete_object, key)
                except Exception:
                    pass
        deleted_titles.append(str(res.get("title") or doc_id))

    lines = [f"🗑 <b>Удалено книг: {len(deleted_titles)}</b>"]
    for t in deleted_titles:
        lines.append(f"• {html.escape(str(t))}")
    if failed:
        lines.append("")
        lines.append(f"⚠️ Не удалось: {html.escape(', '.join(str(f) for f in failed))}")
    lines.append("")
    if deleted_titles:
        lines.append("✅ Книга больше не вернётся — даже при ре-ингесте (slug занесён в список исключений автоматически).")
    try:
        await query.edit_message_text("\n".join(lines), parse_mode="HTML")
    except Exception:
        try:
            await context.bot.send_message(chat_id=query.from_user.id, text="\n".join(lines), parse_mode="HTML")
        except Exception:
            pass

    # Offer replacements for what was just removed — a separate follow-up message with
    # tap-to-add candidates from Gutendex's most-popular German books. Best-effort: a
    # network hiccup here must never break the delete confirmation above.
    if deleted_titles:
        level = ""
        for it in chosen:
            if it.get("level"):
                level = str(it.get("level"))
                break
        try:
            await _offer_public_replacements(context, int(query.from_user.id), digest_id, level=level)
        except Exception:
            logging.warning("public audit: replacement suggestion failed", exc_info=True)


# ===== Replacement suggestions after a classics deletion ================================
# After the admin deletes a book, we surface a few popular public-domain German books
# (not yet in the shelf, not retired) as tappable buttons. One tap ingests the chosen
# book as a normal public row (nightly audio pregen + cover follow automatically). The
# candidate list lives in Redis, mirroring the audit-digest pattern above.

def _pubrepl_redis_key(repl_id: str) -> str:
    return f"pubrepl_digest:{repl_id}"


def _pubrepl_read(repl_id: str) -> dict | None:
    from backend.job_queue import get_redis_client
    client = get_redis_client()
    if client is None:
        return None
    raw = client.get(_pubrepl_redis_key(repl_id))
    if not raw:
        return None
    try:
        return json.loads(raw.decode("utf-8") if isinstance(raw, bytes) else raw)
    except Exception:
        return None


def _pubrepl_write(repl_id: str, state: dict, ttl: int = 604800) -> None:
    from backend.job_queue import get_redis_client
    client = get_redis_client()
    if client is None:
        return
    client.set(_pubrepl_redis_key(repl_id), json.dumps(state, ensure_ascii=False), ex=ttl)


def _pubrepl_delete(repl_id: str) -> None:
    from backend.job_queue import get_redis_client
    client = get_redis_client()
    if client is not None:
        try:
            client.delete(_pubrepl_redis_key(repl_id))
        except Exception:
            pass


def _pubrepl_build_keyboard(repl_id: str, candidates: list) -> InlineKeyboardMarkup:
    rows = []
    for idx, c in enumerate(candidates):
        title = str(c.get("title") or "")[:40]
        author = str(c.get("author") or "")
        label = f"➕ {title}" + (f" — {author}" if author else "")
        rows.append([InlineKeyboardButton(label[:64], callback_data=f"pubrepl_add:{repl_id}:{idx}")])
    rows.append([InlineKeyboardButton("Не нужно", callback_data=f"pubrepl_close:{repl_id}")])
    return InlineKeyboardMarkup(rows)


async def _offer_public_replacements(context, user_id: int, base_id: str, *, level: str = "") -> None:
    """Suggest replacement classics and DM the admin a tap-to-add keyboard."""
    from backend.backend_server import suggest_public_library_replacements

    candidates = await asyncio.to_thread(suggest_public_library_replacements, level=level, limit=3)
    if not candidates:
        return
    repl_id = f"{base_id}r"
    _pubrepl_write(repl_id, {"user_id": int(user_id), "candidates": candidates})
    lines = ["📚 <b>Заменить удалённое?</b>", "Популярные книги публичного домена, которых ещё нет на полке:"]
    for c in candidates:
        lvl = f" · {html.escape(str(c.get('level')))}" if c.get("level") else ""
        lines.append(f"• {html.escape(str(c.get('title') or ''))} — {html.escape(str(c.get('author') or ''))}{lvl}")
    lines.append("")
    lines.append("Нажми, чтобы добавить. Аудио к новой книге наполнится ночью.")
    try:
        await context.bot.send_message(
            chat_id=int(user_id), text="\n".join(lines), parse_mode="HTML",
            reply_markup=_pubrepl_build_keyboard(repl_id, candidates),
        )
    except Exception:
        logging.warning("public audit: could not DM replacement suggestions", exc_info=True)


async def handle_pubrepl_add_callback(update: Update, context: CallbackContext) -> None:
    """Admin tapped a replacement candidate → ingest it as a public book."""
    query = update.callback_query
    if not query or not query.from_user:
        return
    parts = (query.data or "").split(":")
    repl_id = parts[1] if len(parts) >= 2 else ""
    try:
        idx = int(parts[2]) if len(parts) >= 3 else -1
    except ValueError:
        idx = -1
    state = _pubrepl_read(repl_id)
    if not state:
        await query.answer("Список устарел.", show_alert=True)
        return
    if int(state.get("user_id", 0)) != int(query.from_user.id) or not _is_admin_user(query.from_user.id):
        await query.answer("Доступно только администратору.", show_alert=True)
        return
    candidates = state.get("candidates") or []
    if idx < 0 or idx >= len(candidates):
        await query.answer("Не найдено.", show_alert=True)
        return
    chosen = candidates[idx]
    try:
        await query.answer("Добавляю…")
    except Exception:
        pass

    from backend.backend_server import ingest_adhoc_public_book
    try:
        res = await asyncio.to_thread(
            ingest_adhoc_public_book,
            gutenberg_id=int(chosen.get("gutenberg_id")),
            title=str(chosen.get("title") or ""),
            author=str(chosen.get("author") or ""),
            level=str(chosen.get("level") or ""),
            sort=int(chosen.get("sort") or 0),
            slug=str(chosen.get("slug") or "") or None,
        )
    except Exception:
        logging.exception("pubrepl add: ingest failed gid=%s", chosen.get("gutenberg_id"))
        res = {"ok": False, "error": "exception"}

    if res.get("ok"):
        # Drop the added one; keep the rest tappable so the admin can add several.
        remaining = [c for i, c in enumerate(candidates) if i != idx]
        _pubrepl_write(repl_id, {"user_id": int(query.from_user.id), "candidates": remaining})
        note = f"✅ Добавлено: {html.escape(str(chosen.get('title') or ''))}. Аудио наполнится ночью."
        try:
            if remaining:
                await query.edit_message_text(
                    note + "\n\nДобавить ещё?", parse_mode="HTML",
                    reply_markup=_pubrepl_build_keyboard(repl_id, remaining),
                )
            else:
                _pubrepl_delete(repl_id)
                await query.edit_message_text(note, parse_mode="HTML")
        except Exception:
            pass
    else:
        # Stub/too-short or download error → drop this candidate, offer the others.
        err = str(res.get("error") or "")
        remaining = [c for i, c in enumerate(candidates) if i != idx]
        _pubrepl_write(repl_id, {"user_id": int(query.from_user.id), "candidates": remaining})
        await query.answer(
            "Не получилось (файл пустой или битый). Попробуй другую." if "short" in err or "empty" in err
            else "Не удалось добавить. Попробуй другую.",
            show_alert=True,
        )
        try:
            if remaining:
                await query.edit_message_reply_markup(reply_markup=_pubrepl_build_keyboard(repl_id, remaining))
            else:
                _pubrepl_delete(repl_id)
                await query.edit_message_reply_markup(reply_markup=None)
        except Exception:
            pass


async def handle_pubrepl_close_callback(update: Update, context: CallbackContext) -> None:
    """Admin dismissed the replacement suggestions."""
    query = update.callback_query
    if not query or not query.from_user:
        return
    parts = (query.data or "").split(":")
    repl_id = parts[1] if len(parts) >= 2 else ""
    _pubrepl_delete(repl_id)
    try:
        await query.answer("Ок")
        await query.edit_message_reply_markup(reply_markup=None)
    except Exception:
        pass


async def reader_public_audit_command(update: Update, context: CallbackContext) -> None:
    """Admin: send the Классика readership audit on demand (same as the twice-a-year DM)."""
    user = update.effective_user
