def _reserve_telegram_ask_gpt_daily(
    *,
    user_id: int,
    source_lang: str | None,
    target_lang: str | None,
    origin: str,
    request_key: str,
    question_len: int = 0,
    has_context: bool = False,
) -> dict:
    # Per-user daily EUR cost cap (Free €0.2 / Pro €0.5), bot-side. Blocks BEFORE the count
    # reservation so a Pro user (higher/no count limit) is still bounded by cost. Cheap:
    # cached entitlement + one spent-today sum. Fail-open. Callers already handle "blocked".
    try:
        from backend.database import enforce_daily_cost_cap
        if enforce_daily_cost_cap(user_id=int(user_id), tz="Europe/Vienna"):
            return {"blocked": True, "reason": "cost_cap"}
    except Exception:
        pass
    return reserve_free_feature_usage(
        user_id=int(user_id),
        feature_key="ask_gpt_daily",
        idempotency_key=(
            f"askgpt:{int(user_id)}:{str(origin or 'telegram').strip().lower()}:"
            f"{hashlib.sha1(str(request_key or '').encode('utf-8', 'ignore')).hexdigest()[:24]}"
        ),
        source_lang=source_lang,
        target_lang=target_lang,
        metadata={
            "origin": str(origin or "telegram").strip().lower(),
            "request_key": str(request_key or "").strip()[:120],
            "question_len": max(0, int(question_len or 0)),
            "has_context": bool(has_context),
        },
        tz="Europe/Vienna",
    )


def _format_admin_datetime(value: str | None) -> str:
    raw_value = str(value or "").strip()
    if not raw_value:
        return "-"
    try:
        parsed = datetime.fromisoformat(raw_value.replace("Z", "+00:00"))
        if parsed.tzinfo is None:
            parsed = parsed.replace(tzinfo=ZoneInfo("UTC"))
        return parsed.astimezone(ZoneInfo(USER_REMOVAL_REVIEW_TZ)).strftime("%d.%m.%Y %H:%M")
    except Exception:
        return raw_value


