def _send_pool_enrich_morning_report() -> None:
    """Утренний отчёт (07:00 Вена) об итогах ночного добора пула.

    Читает heartbeat, который записала сама ночная работа, поэтому отчёт честно скажет и
    «упало», и «не запускалось» — молчание планировщика иначе неотличимо от успеха."""
    try:
        from backend.database import get_admin_telegram_ids, get_latest_scheduler_run_guard
        row = get_latest_scheduler_run_guard(job_key="pool_night_enrichment")
        meta = (row or {}).get("metadata") or {}
        status = str((row or {}).get("status") or "").lower()
        finished_at = (row or {}).get("finished_at")
        stamp = finished_at.astimezone(ZoneInfo("Europe/Vienna")).strftime("%d.%m %H:%M") if finished_at else "—"
        if not row:
            text = ("🌙 <b>Ночной добор словаря</b>\n\n"
                    "⚠️ Записей о запуске нет — работа ни разу не отрабатывала. "
                    "Проверь, жив ли планировщик бота.")
        elif status == "failed":
            text = (f"🌙 <b>Ночной добор словаря</b> — {stamp}\n\n"
                    f"❌ Упал. {meta.get('error') or 'Подробности в логах.'}")
        else:
            enriched = int(meta.get("enriched") or 0)
            remaining = int(meta.get("remaining") or 0)
            cap = int(meta.get("cap") or 0)
            nights_left = (remaining + cap - 1) // cap if cap else 0
            skipped = int(meta.get("skipped") or 0)
            skipped_empty = int(meta.get("skipped_empty") or 0)
            skipped_thin = int(meta.get("skipped_thin") or 0)
            # Split the "skipped" total by root cause + show a few example words, so it's
            # clear WHY GPT «не дал карточку»: пусто (запрос упал/молчит) vs неполная
            # (обычно мусорный токен/имя собственное — часто чинится чисткой пула, не промптом).
            skip_lines = ""
            if skipped:
                skip_lines = f"Пропущено: {skipped}\n"
                if skipped_empty or skipped_thin:
                    skip_lines += (
                        f"   • пусто от GPT (запрос упал/молчит): {skipped_empty}\n"
                        f"   • вернул, но карточка неполная (часто мусор/имя): {skipped_thin}\n"
                    )
                samples = meta.get("skipped_samples") or []
                sample_words = []
                for it in samples:
                    w = str((it or {}).get("word") or "").strip() if isinstance(it, dict) else str(it or "").strip()
                    if w:
                        sample_words.append(w)
                if sample_words:
                    from html import escape as _esc
                    shown = ", ".join(_esc(w) for w in sample_words[:10])
                    more = f" …(+{len(sample_words) - 10})" if len(sample_words) > 10 else ""
                    skip_lines += f"   примеры: <i>{shown}{more}</i>\n"
            else:
                skip_lines = "Пропущено: 0\n"
            # Карантин: неисправимый мусор, выпавший из очереди после 3 провалов. Показываем
            # число + подсказку на команду с полным списком, чтобы админ мог разобрать.
            quarantine_line = ""
            try:
                from backend.database import count_quarantined_pool_entries
                q = int(count_quarantined_pool_entries() or 0)
                if q:
                    quarantine_line = (
                        f"🗑 В карантине: <b>{q}</b> (GPT не собрать — мусор/опечатки; "
                        f"весь список и разбор: /admin_pool_quarantine)\n"
                    )
            except Exception:
                logging.debug("quarantine count for morning report failed", exc_info=True)
            text = (
                f"🌙 <b>Ночной добор словаря</b> — {stamp}\n\n"
                f"Наполнено за ночь: <b>{enriched}</b> из {int(meta.get('picked') or 0)} взятых\n"
                f"{skip_lines}"
                f"Ошибок: {int(meta.get('errors') or 0)}\n\n"
                f"Осталось наполнить: <b>{remaining}</b>\n"
                + (f"Это ещё ~{nights_left} ноч{'ь' if nights_left == 1 else 'и' if nights_left < 5 else 'ей'} "
                   f"по {cap} слов." if remaining else "✅ Пул наполнен полностью.")
                + (f"\n{quarantine_line}" if quarantine_line else "")
            )
        token = os.getenv("TELEGRAM_Deutsch_BOT_TOKEN")
        admin_ids = sorted(int(a) for a in (get_admin_telegram_ids() or []) if int(a) > 0)
        if not token or not admin_ids:
            return
        for uid in admin_ids:
            requests.post(
                f"https://api.telegram.org/bot{token}/sendMessage",
                json={"chat_id": uid, "text": text, "parse_mode": "HTML",
                      "disable_web_page_preview": True},
                timeout=20,
            )
    except Exception:
        logging.exception("pool enrich morning report failed")


