async def refund_star_command(update: Update, context: CallbackContext) -> None:
    """/refund_star — admin-only. Lists recent Stars charges with a button to refund each
    (Telegram refundStarPayment). Lets us test a real payment cheaply: buy → verify in
    /stars → refund the stars back to our balance. Refunds are per-charge and idempotent."""
    from datetime import datetime as _dt, timezone as _tz
    user = update.effective_user
    message = update.effective_message
    if not user or not message or not _is_admin_user(int(user.id)):
        return
    rows = await asyncio.to_thread(_list_refundable_star_txns, 10)
    if not rows:
        await message.reply_text(
            "⭐ Пока нет входящих оплат звёздами для возврата (Telegram не отдал ни одной)."
        )
        return
    lines = ["⭐ <b>Возврат звёзд</b>\nВходящие оплаты из Telegram — нажми, чтобы вернуть:"]
    keyboard = []
    for r in rows:
        when_s = _dt.fromtimestamp(r["date"], _tz.utc).strftime("%d.%m %H:%M") if r["date"] else "—"
        label = r["label"]
        suffix = f" · {label}" if label else ""
        lines.append(f"• {r['stars']}⭐ · {when_s} · user {r['user_id']}{suffix}")
        # callback_data ≤64 bytes: charge ids are long → pass the last 48 chars + user id.
        keyboard.append([InlineKeyboardButton(
            f"↩️ Вернуть {r['stars']}⭐{suffix}",
            callback_data=f"rfst:{r['user_id']}:{r['charge_id'][-48:]}",
        )])
    markup = InlineKeyboardMarkup(keyboard) if keyboard else None
    await message.reply_text("\n".join(lines), parse_mode="HTML", reply_markup=markup)


async def refund_star_callback(update: Update, context: CallbackContext) -> None:
    """Handle a ↩️ refund button: call refundStarPayment, stamp the row, report the result."""
    from backend.database import mark_star_payment_refunded, revoke_star_payment_fulfillment
    query = update.callback_query
    if not query or not query.from_user or not _is_admin_user(int(query.from_user.id)):
        if query:
            await query.answer("Только для админа", show_alert=True)
        return
    try:
        _, uid_s, charge_tail = str(query.data or "").split(":", 2)
        uid = int(uid_s)
    except Exception:
        await query.answer("Плохие данные", show_alert=True)
        return
    # The button carries only the tail of the charge id — resolve the full one from the
    # Telegram ledger (falls back to our DB for invoice purchases if the ledger rolled over).
    row = await asyncio.to_thread(_resolve_refundable_star_txn_by_tail, uid, charge_tail)
    if not row:
        row = await asyncio.to_thread(_resolve_star_payment_by_tail, uid, charge_tail)
    if not row:
        await query.answer("Оплата не найдена", show_alert=True)
        return
    charge_id = row["charge_id"]
    try:
        await context.bot.refund_star_payment(user_id=uid, telegram_payment_charge_id=charge_id)
    except Exception as exc:
        logging.warning("refund_star_payment failed charge=%s: %s", charge_id, exc)
        await query.answer(f"Telegram отклонил возврат: {exc}"[:190], show_alert=True)
        return
    await asyncio.to_thread(mark_star_payment_refunded, charge_id, "manual")  # no-op for tips not in our DB
    # Money went back → claw back what the charge granted (Pro days, sponsor, sub, audio).
    revoked = await asyncio.to_thread(revoke_star_payment_fulfillment, charge_id)
    _undone = []
    if revoked.get("grants_removed"):
        _undone.append("Pro-дни")
    if revoked.get("sponsor_removed"):
        _undone.append("спонсор")
    if revoked.get("subscription_reverted"):
        _undone.append("Pro-подписка")
    if revoked.get("book_audio_revoked"):
        _undone.append("озвучка книги")
    _undone_txt = (" Отозвано: " + ", ".join(_undone) + ".") if _undone else ""
    try:
        await query.answer(f"✅ Возвращено {row['stars']}⭐", show_alert=True)
        await query.edit_message_reply_markup(reply_markup=None)
        await query.message.reply_text(
            f"✅ Возврат выполнен: {row['stars']}⭐ пользователю {uid}. "
            f"Звёзды вернулись на баланс бота — можно платить снова.{_undone_txt}"
        )
    except Exception:
        logging.warning("refund_star post-refund UI update failed", exc_info=True)


def _resolve_star_payment_by_tail(user_id: int, charge_tail: str) -> dict | None:
    """Match a recent charge by user + charge-id suffix (the button can't carry the full id)."""
    from backend.database import list_recent_star_payments
    tail = str(charge_tail or "")
    for r in list_recent_star_payments(50):
        if int(r["user_id"]) == int(user_id) and r["charge_id"].endswith(tail):
            return r
    return None


async def admin_scheduler_health_command(update: Update, context: CallbackContext):
    """Show, per scheduled job, when it last actually ran — reading the CORRECT tracking
    table per job (run-guards vs admin-runs) so conditional jobs aren't falsely "never".
    /scheduler_health           → full report
    /scheduler_health problems  → only what needs attention (the evening-digest view)"""
    sender = update.effective_user
    message = update.effective_message
    if not sender or not message:
        return
    if not _is_admin_user(sender.id):
        await message.reply_text("⛔️ Команда доступна только администратору.")
        return
    view = "problems" if (context.args and str(context.args[0]).strip().lower() in {"problems", "проблемы", "p"}) else "full"
    status = await message.reply_text("🩺 Проверяю, что и когда реально отрабатывало…")
    try:
        text = await asyncio.to_thread(_build_scheduler_health_report, view)
        await status.delete()
        for chunk in _split_telegram_text(text):
            await message.reply_text(chunk, parse_mode="HTML", disable_web_page_preview=True)
    except Exception as exc:
        logging.exception("admin scheduler health command failed user_id=%s", int(sender.id))
        await status.edit_text(f"❌ Не удалось собрать health: {exc}")


