async def admin_fix_srs_counters_command(update: Update, context: CallbackContext):
    """Пересчитать «повторений/забываний» по журналу ответов для ВСЕХ пользователей.

    Оба счётчика месяцами писались нулём (библиотека убрала поля, из которых мы их читали),
    поэтому в списке слов у всех стояло «повт. 0». Журнал цел, значит правда восстановима.

    Использование:
      /admin_fix_srs_counters          → показать, сколько карточек разошлось (ничего не менять)
      /admin_fix_srs_counters apply    → пересчитать и записать
    """
    sender = update.effective_user
    message = update.effective_message
    if not sender or not message:
        return
    if not _is_admin_user(sender.id):
        await message.reply_text("⛔️ Команда доступна только администратору.")
        return
    apply = bool(context.args) and str(context.args[0]).strip().lower() == "apply"
    try:
        from backend.database import backfill_srs_counters_from_review_log
        stats = await asyncio.to_thread(backfill_srs_counters_from_review_log, apply=apply)
    except Exception as exc:
        logging.warning("admin_fix_srs_counters failed", exc_info=True)
        await message.reply_text(f"❌ Не удалось пересчитать: {exc}")
        return
    if not apply:
        await message.reply_text(
            f"🔍 Карточек всего: {stats['total_cards']}\n"
            f"Расходится с журналом: {stats['stale']}\n\n"
            f"Записать: /admin_fix_srs_counters apply"
        )
        return
    await message.reply_text(
        f"✅ Пересчитано карточек: {stats['updated']} (из {stats['total_cards']})."
    )


async def admin_fix_dict_translations_command(update: Update, context: CallbackContext):
    """Backfill quick-dictionary entries (incl. tapped synonym chips) that were saved as
    bare German text without a Russian translation.

    Usage:
      /admin_fix_dict_translations                    → dry-run, caller's own entries
      /admin_fix_dict_translations apply              → write fixes, caller's own entries
      /admin_fix_dict_translations apply all          → write fixes, ALL users
      /admin_fix_dict_translations apply all 30d      → only entries from the last 30 days
      /admin_fix_dict_translations apply all 30d meta → ALSO re-enrich entries that have a
                                                        translation but an empty card
    """
    sender = update.effective_user
    message = update.effective_message
    if not sender or not message:
        return
    if not _is_admin_user(sender.id):
        await message.reply_text("⛔️ Команда доступна только администратору.")
        return
    args = [a.strip().lower() for a in (context.args or [])]
    apply = "apply" in args
    all_users = "all" in args
    with_meta = "meta" in args
    days = None
    for a in args:
        if re.fullmatch(r"\d+d", a):
            days = int(a[:-1])
            break
    target_user_id = None if all_users else int(sender.id)
    scope = "ВСЕ пользователи" if all_users else "только ваши записи"
    mode = "ПРИМЕНЯЮ изменения" if apply else "пробный прогон (ничего не пишу)"
    window = f"последние {days} дн." if days else "без ограничения по дате"
    await message.reply_text(
        f"🔧 Бэкфилл переводов словаря: {mode}, {scope}, {window}.\n"
        "Это может занять время (по одному запросу на слово)…"
    )
    try:
        report = await asyncio.to_thread(
            backfill_quick_dictionary_translations,
            dry_run=not apply,
            max_entries=2000 if all_users else 1000,
            user_id=target_user_id,
            days=days,
        )
    except Exception as exc:
        logging.exception("admin fix dict translations failed user_id=%s", int(sender.id))
        await message.reply_text(f"❌ Бэкфилл упал: {exc}")
        return
    samples = report.get("samples") or []
    sample_lines = "\n".join(f"  • #{s.get('id')} {s.get('german')}" for s in samples[:15])
    text = (
        f"📒 <b>Бэкфилл переводов словаря</b> ({'apply' if apply else 'dry-run'})\n\n"
        f"Просмотрено: <b>{report.get('scanned', 0)}</b>\n"
        f"Битых (без русского): <b>{report.get('broken', 0)}</b>\n"
        f"Исправлено: <b>{report.get('fixed', 0)}</b>\n"
        f"Пропущено (уже есть русский): {report.get('skipped_has_ru', 0)}\n"
        f"Пропущено (нет немецкого): {report.get('skipped_no_german', 0)}\n"
        f"Ошибок: {report.get('errors', 0)}"
    )
    if sample_lines:
        text += f"\n\n<b>Примеры:</b>\n{sample_lines}"
    diag = report.get("diagnostics") or {}
    if diag and not diag.get("error"):
        pairs = ", ".join(
            f"{p.get('source')}→{p.get('target')}:{p.get('count')}"
            for p in (diag.get("by_pair") or [])[:6]
        )
        text += (
            "\n\n<b>Диагностика:</b>\n"
            f"Всего записей: {diag.get('total', 0)}\n"
            f"de→ru всего: {diag.get('de_ru_total', 0)}, из них без русского: {diag.get('de_ru_missing_ru', 0)}\n"
            f"Пары: {pairs}"
        )
    elif diag.get("error"):
        text += f"\n\n<b>Диагностика недоступна:</b> {diag.get('error')}"
    if not apply and report.get("broken", 0):
        text += "\n\nЗапустите с <code>apply</code>, чтобы исправить."
    for part in _split_telegram_text(text):
        await message.reply_text(part, parse_mode="HTML", disable_web_page_preview=True)

    if not with_meta:
        return
    # Второй проход: записи с переводом, но с пустой карточкой. Один вызов GPT на слово,
    # ~2-3 слова в минуту, поэтому идём БАТЧАМИ и шлём прогресс — молчащая команда
    # неотличима от зависшей. Размер батча: /admin_fix_dict_translations … meta 300
    batch = 100
    for a in args:
        if a.isdigit() and 1 <= int(a) <= 2000:
            batch = int(a)
            break
    await message.reply_text(
        f"🧩 Второй проход: карточки без метаинформации. Беру до {batch} записей за раз, "
        "по одному запросу к GPT на слово — это минуты. Пришлю прогресс."
    )

    def _progress(done: int, total: int) -> None:
        try:
            asyncio.run_coroutine_threadsafe(
                message.reply_text(f"🧩 Дозаполнено {done} из {total}…"),
                loop,
            )
        except Exception:
            pass

    loop = asyncio.get_running_loop()
    try:
        meta_report = await asyncio.to_thread(
            backfill_dictionary_card_metainfo,
            dry_run=not apply,
            max_entries=batch,
            user_id=target_user_id,
            days=days,
            progress_cb=_progress if apply else None,
        )
    except Exception as exc:
        logging.exception("admin dict metainfo backfill failed user_id=%s", int(sender.id))
        await message.reply_text(f"❌ Второй проход упал: {exc}")
        return
    if meta_report.get("already_running"):
        await message.reply_text(
            "⏳ Проход уже идёт — второй запуск только удвоил бы траты на те же слова. "
            f"Осталось записей: {meta_report.get('remaining', 0)}."
        )
        return
    meta_samples = meta_report.get("samples") or []
    meta_lines = "\n".join(f"  • #{s.get('id')} {s.get('german')}" for s in meta_samples[:15])
    remaining = int(meta_report.get("remaining") or 0)
    meta_text = (
        f"🧩 <b>Карточки без метаинформации</b> ({'apply' if apply else 'dry-run'})\n\n"
        f"Просмотрено: <b>{meta_report.get('scanned', 0)}</b>\n"
        f"Пустых карточек: <b>{meta_report.get('empty_cards', 0)}</b>\n"
        f"Дозаполнено: <b>{meta_report.get('enriched', 0)}</b>\n"
        f"Ошибок: {meta_report.get('errors', 0)}\n"
        f"Осталось в базе: <b>{remaining}</b>"
    )
    if remaining and apply:
        meta_text += "\n\nЗапусти команду ещё раз, чтобы взять следующий батч."
    if meta_lines:
        meta_text += f"\n\n<b>Примеры:</b>\n{meta_lines}"
    for part in _split_telegram_text(meta_text):
        await message.reply_text(part, parse_mode="HTML", disable_web_page_preview=True)


async def admin_repair_dict_cards_command(update: Update, context: CallbackContext):
    """Бесплатный ремонт пустых карточек из уже сохранённого ответа модели (raw_text).

    Сюда попадают карточки, где модель ответила правильно, но её JSON не разобрался, и
    сохранилась заглушка: пустые значения, часть речи «other», нет артикля («Eltern»).
    Ответ лежит в базе целиком, поэтому карточка собирается заново БЕЗ запроса к GPT.

    /admin_repair_dict_cards               → пробный прогон по всем пользователям
    /admin_repair_dict_cards apply         → починить (до 200 записей за раз)
    /admin_repair_dict_cards apply 500     → размер батча
    /admin_repair_dict_cards apply me      → только мои записи
    """
    sender = update.effective_user
    message = update.effective_message
    if not sender or not message:
        return
    if not _is_admin_user(sender.id):
        await message.reply_text("⛔️ Команда доступна только администратору.")
        return
    args = [a.strip().lower() for a in (context.args or [])]
    apply = "apply" in args
    batch = next((int(a) for a in args if a.isdigit() and 1 <= int(a) <= 5000), 200)
    target_user_id = int(sender.id) if "me" in args else None

    await message.reply_text(
        f"🩹 Ремонт карточек из сохранённого ответа ({'apply' if apply else 'проба'}), "
        f"до {batch} записей. GPT не трогаем — это бесплатно."
    )
    try:
        report = await asyncio.to_thread(
            repair_dictionary_cards_from_raw_text,
            dry_run=not apply,
            max_entries=batch,
            user_id=target_user_id,
        )
    except Exception as exc:
        logging.exception("admin dict raw_text repair failed user_id=%s", int(sender.id))
        await message.reply_text(f"❌ Ремонт упал: {exc}")
        return

    from html import escape as _esc
    samples = report.get("samples") or []
    lines = "\n".join(
        f"  • #{s.get('id')} {_esc(str(s.get('word') or ''))}".rstrip()
        for s in samples[:15]
    )
    text = (
        f"🩹 <b>Ремонт карточек из ответа модели</b> ({'apply' if apply else 'проба'})\n\n"
        f"Просмотрено: <b>{report.get('scanned', 0)}</b>\n"
        f"Починено: <b>{report.get('repaired', 0)}</b>\n"
        f"Не разобрался даже с ремонтом: {report.get('unparsable', 0)}\n"
        f"Осталось тонкими (нужен GPT): {report.get('still_thin', 0)}\n"
        f"Ошибок: {report.get('errors', 0)}\n"
        f"Осталось в базе: <b>{report.get('remaining', 0)}</b>"
    )
    if lines:
        text += f"\n\n<b>Примеры:</b>\n{lines}"
    if report.get("remaining") and apply:
        text += "\n\nЗапусти ещё раз, чтобы взять следующий батч."
    for part in _split_telegram_text(text):
        await message.reply_text(part, parse_mode="HTML", disable_web_page_preview=True)


# ── Долгие ручные прогоны переживают перезапуск ──────────────────────────────────
#
# Пересбор разбора и добор пула идут ДЕСЯТКИ МИНУТ в обычном потоке внутри бота: один
# запрос к модели на слово, по одному подряд. Любой деплой и любая смена переменной на
# Railway поднимают новый контейнер — и поток умирает без следа. 02.08.2026 так и вышло:
# пересбор оборвался на 244-м слове из 252, итог никому не пришёл, а по остатку в базе
# это выглядело как «модель не смогла разобрать 8 слов».
#
# Поэтому состояние прогона живёт в БАЗЕ (одна строка отметок планировщика на ключ
# работы, метаданные в JSONB — новая таблица не нужна), а при старте бот проверяет, не
# остался ли прогон в состоянии «идёт». Если остался — значит его оборвали: в свежем
# процессе ничего идти не может. Тогда бот досылает владельцу, где оборвалось, и
# продолжает с остатка.
#
# Дозаписи защищены от петли: если прогон обрывается снова и снова (например, сервис в
# цикле перезапусков), после _ADMIN_RUN_MAX_RESUMES попыток он закрывается с сообщением,
# а не жжёт деньги вечно.
_ADMIN_RUN_MAX_RESUMES = 3


def _admin_run_send(chat_id: int, text: str) -> None:
    """Отправка СЫРЫМ HTTP: сообщение уходит из обычного потока, где нет петли событий."""
    token = os.getenv("TELEGRAM_Deutsch_BOT_TOKEN")
    if not token or not chat_id:
        return
    for part in _split_telegram_text(text):
        try:
            requests.post(
                f"https://api.telegram.org/bot{token}/sendMessage",
                json={"chat_id": int(chat_id), "text": part, "parse_mode": "HTML",
                      "disable_web_page_preview": True},
                timeout=20,
            )
        except Exception:
            logging.warning("admin run raw send failed", exc_info=True)


def _admin_run_save(job_key: str, status: str, state: dict) -> None:
    _record_sched_heartbeat(job_key, status, state)


def _admin_run_load(job_key: str) -> tuple[str, dict]:
    try:
        from backend.database import get_latest_scheduler_run_guard
        row = get_latest_scheduler_run_guard(job_key=job_key) or {}
    except Exception:
        logging.debug("admin run state load failed job_key=%s", job_key, exc_info=True)
        return "", {}
    meta = row.get("metadata")
    return str(row.get("status") or ""), meta if isinstance(meta, dict) else {}


def _format_resweep_report(report: dict, params: dict) -> str:
    from html import escape as _esc
    samples = report.get("samples") or []
    lines = "\n".join(
        f"  • {_esc(str(s.get('word')))} — {_esc(str(s.get('translation')))} "
        f"(сохранили: {_esc(str(s.get('saved')))})"
        for s in samples[:12]
    )
    picked = int(report.get("picked", 0))
    dry = bool(report.get("dry_run"))
    text = (
        f"🧩 <b>Пересбор куцых разборов</b> ({'пробный прогон' if dry else 'применяю'})\n\n"
        f"Взято в работу: <b>{picked}</b> (потолок {report.get('cap', 0)})\n"
        f"Пересобрано: <b>{report.get('enriched', 0)}</b>\n"
        f"Дошло до карточек людей: <b>{report.get('cards_filled', 0)}</b>\n"
        f"Пропущено: пусто от модели {int(report.get('skipped_empty') or 0)} · "
        f"лучше не стало {int(report.get('skipped_thin') or 0)}\n"
        f"Ошибок: {report.get('errors', 0)}\n"
        f"Осталось: <b>{report.get('remaining', 0)}</b>"
    )
    if dry and picked:
        # Цена замерена 02.08.2026 живыми вызовами: $0.00208 за слово с учётом кеша
        # инструкции. Показываем её ДО траты, а не после.
        text += f"\n\nЦена применения: примерно <b>${picked * 0.00208:.2f}</b>"
    if lines:
        text += f"\n\n<b>Очередь (сначала то, что скоро спросят):</b>\n{lines}"
    return text


def _run_resweep(params: dict, limit: int | None, progress_cb) -> dict:
    from backend.backend_server import resweep_thin_unit_cards
    return resweep_thin_unit_cards(limit=limit, dry_run=False, progress_cb=progress_cb)


def _format_pool_enrich_report(report: dict, params: dict) -> str:
    from html import escape as _esc
    src = str(params.get("src") or "de")
    tgt = str(params.get("tgt") or "ru")
    if report.get("already_running"):
        return "⏳ Добор уже идёт — второй запуск удвоил бы траты."
    samples = report.get("samples") or []
    lines = "\n".join(
        f"  • {_esc(str(s.get('word')))} — {_esc(str(s.get('translation')))} "
        f"(спрашивали: {_esc(str(s.get('demand')))})"
        for s in samples[:12]
    )
    text = (
        f"🌙 <b>Добор общего пула</b> (применяю, {src}→{tgt})\n\n"
        f"Взято в работу: <b>{report.get('picked', 0)}</b> (потолок {report.get('cap', 0)})\n"
        f"Обогащено: <b>{report.get('enriched', 0)}</b>\n"
        f"Пропущено: {report.get('skipped', 0)}"
        + (f" (пусто от GPT {int(report.get('skipped_empty') or 0)} · "
           f"неполная карточка {int(report.get('skipped_thin') or 0)})"
           if (report.get('skipped_empty') or report.get('skipped_thin')) else "")
        + "\n"
        f"Ошибок: {report.get('errors', 0)}\n"
        f"Осталось тонких: <b>{report.get('remaining', 0)}</b>"
    )
    if lines:
        text += f"\n\n<b>Очередь (по востребованности):</b>\n{lines}"
    return text


def _run_pool_enrich(params: dict, limit: int | None, progress_cb) -> dict:
    from backend.backend_server import run_pool_night_enrichment
    return run_pool_night_enrichment(
        limit=limit, dry_run=False,
        source_lang=str(params.get("src") or "de"), target_lang=str(params.get("tgt") or "ru"),
        progress_cb=progress_cb,
    )


# Ключ работы → как её запустить, как назвать и как отчитаться. Резюме после перезапуска
# берёт всё отсюда, поэтому новая долгая команда подключается одной строкой.
_DURABLE_ADMIN_RUNS: dict[str, dict] = {
    "admin_run_resweep_units": {
        "title": "Пересбор куцых разборов",
        "runner": _run_resweep,
        "formatter": _format_resweep_report,
    },
    "admin_run_pool_enrich": {
        "title": "Добор общего пула",
        "runner": _run_pool_enrich,
        "formatter": _format_pool_enrich_report,
    },
}


def _start_durable_admin_run(
    *, job_key: str, chat_id: int, limit: int | None, params: dict | None = None,
    done_before: int = 0, resumes: int = 0,
) -> None:
    """Запустить долгий прогон в отдельном потоке, помечая его состояние в базе.

    Отдельный поток — не украшение: вызовы к модели идут через asyncio.run() поверх того
    же async-клиента, которым живёт петля бота, и запуск их из петли однажды оставил
    команду висеть без итога. Обычный поток — тот же контекст, в котором работает
    ночной джоб, и он досчитывает надёжно."""
    spec = _DURABLE_ADMIN_RUNS.get(job_key)
    if not spec:
        return
    par = dict(params or {})
    state = {
        "chat_id": int(chat_id), "limit": limit, "params": par,
        "done": int(done_before), "resumes": int(resumes),
        "title": spec["title"],
    }
    _admin_run_save(job_key, "running", state)

    def _progress(idx: int, total: int, rep: dict) -> None:
        # Отмечаем ПОЗИЦИЮ в базе, а не только в сообщении: если контейнер погасят прямо
        # сейчас, продолжать надо будет отсюда, а не с начала.
        state["done"] = int(done_before) + idx + 1
        if idx == 0 or (idx % 5 == 0):
            _admin_run_save(job_key, "running", state)
            _admin_run_send(
                chat_id,
                f"⚙️ {spec['title']}: беру {state['done']}/{int(done_before) + total} "
                f"(готово {int(rep.get('enriched', 0))})",
            )

    def _worker() -> None:
        from html import escape as _esc
        try:
            report = spec["runner"](par, limit, _progress)
            state["report"] = {k: v for k, v in report.items() if k != "samples"}
            _admin_run_save(job_key, "completed", state)
            text = spec["formatter"](report, par)
            if done_before:
                text += f"\n\n<i>Прогон продолжался после перезапуска: до него сделано {done_before}.</i>"
            _admin_run_send(chat_id, text)
        except Exception as exc:
            logging.exception("durable admin run failed job_key=%s", job_key)
            state["error"] = str(exc)[:300]
            _admin_run_save(job_key, "failed", state)
            _admin_run_send(chat_id, f"❌ {spec['title']} упал: {_esc(str(exc))}")

    threading.Thread(target=_worker, name=f"durable-{job_key}", daemon=True).start()


def _resume_interrupted_admin_runs() -> None:
    """Досчитать прогоны, которые оборвал перезапуск.

    В свежем процессе ничего идти не может, поэтому отметка «идёт» означает ровно одно:
    контейнер погасили на середине. Молчать тут нельзя — владелец ждал итог и не получил
    его; сначала пишем, где оборвалось, потом продолжаем с остатка."""
    for job_key, spec in _DURABLE_ADMIN_RUNS.items():
        try:
            status, state = _admin_run_load(job_key)
            if status != "running" or not isinstance(state, dict):
                continue
            chat_id = int(state.get("chat_id") or 0)
            done = int(state.get("done") or 0)
            limit = state.get("limit")
            resumes = int(state.get("resumes") or 0) + 1
            if resumes > _ADMIN_RUN_MAX_RESUMES:
                _admin_run_save(job_key, "failed", {**state, "resumes": resumes})
                _admin_run_send(
                    chat_id,
                    f"⚠️ {spec['title']}: прогон обрывался {resumes - 1} раза подряд, "
                    f"больше не продолжаю сам. Успел сделать {done}. "
                    f"Запусти команду заново, когда сервис перестанет перезапускаться.",
                )
                continue
            remaining = None if limit is None else max(0, int(limit) - done)
            if remaining == 0:
                _admin_run_save(job_key, "completed", {**state, "resumes": resumes})
                _admin_run_send(chat_id, f"✅ {spec['title']}: потолок выбран, продолжать нечего.")
                continue
            _admin_run_send(
                chat_id,
                f"🔄 {spec['title']}: перезапуск оборвал прогон на {done}-м. Продолжаю с остатка"
                + (f" (осталось не больше {remaining})." if remaining is not None else "."),
            )
            _start_durable_admin_run(
                job_key=job_key, chat_id=chat_id, limit=remaining,
                params=state.get("params") or {}, done_before=done, resumes=resumes,
            )
        except Exception:
            logging.warning("resume of admin run failed job_key=%s", job_key, exc_info=True)


async def admin_resweep_units_command(update: Update, context: CallbackContext):
    """Пересобрать разбор у слов с КУЦЕЙ карточкой: примеры и формы есть, а значений,
    управления и сочетаний нет.

    Ночной добор такие слова не берёт СОЗНАТЕЛЬНО — он смотрит только на слова вовсе без
    разбора, чтобы сдвиг планки полноты не запустил массовый пересбор за деньги сам
    собой. Поэтому шаг явный, с потолком и сухим прогоном по умолчанию.

    /admin_resweep_units            → сколько слов ждёт и сколько это будет стоить
    /admin_resweep_units apply      → пересобрать (потолок из env, по умолчанию 300)
    /admin_resweep_units apply 50   → не больше 50 за раз
    """
    sender = update.effective_user
    message = update.effective_message
    if not sender or not message:
        return
    if not _is_admin_user(sender.id):
        await message.reply_text("⛔️ Команда доступна только администратору.")
        return
    args = [a.strip().lower() for a in (context.args or [])]
    apply = "apply" in args
    limit = next((int(a) for a in args if a.isdigit() and 1 <= int(a) <= 5000), None)
    chat_id = message.chat_id

    if not apply:
        await message.reply_text("🧩 Пересбор: пробный прогон, показываю очередь и цену…")
        try:
            from backend.backend_server import resweep_thin_unit_cards
            report = await asyncio.to_thread(resweep_thin_unit_cards, limit=limit, dry_run=True)
        except Exception as exc:
            logging.exception("resweep dry-run failed user_id=%s", int(sender.id))
            await message.reply_text(f"❌ Пересбор упал: {exc}")
            return
        for part in _split_telegram_text(_format_resweep_report(report, {})):
            await message.reply_text(part, parse_mode="HTML", disable_web_page_preview=True)
        return

    await message.reply_text(
        "🧩 Пересбор: ПРИМЕНЯЮ. Один запрос к модели на слово — это минуты; "
        "итог пришлю сюда, как закончу. Перезапуск сервиса прогон переживёт — "
        "досчитаю с остатка и всё равно отчитаюсь."
    )
    # limit может быть None — тогда потолок берёт сама работа. Дублировать её значение
    # здесь нельзя: два места с одним «по умолчанию» разъезжаются на первой же правке.
    _start_durable_admin_run(job_key="admin_run_resweep_units", chat_id=chat_id, limit=limit)


async def admin_spread_unit_cards_command(update: Update, context: CallbackContext):
    """Раздать уже собранный разбор слова по пустым личным карточкам. Бесплатно.

    Разбор собирается один раз на слово и лежит в слое единиц — общий для всех. А
    тренажёр читает личную карточку человека, и туда разбор сам не переезжал: на
    01.08.2026 разбор был готов у 3648 пустых карточек, и ни одна его не показывала.
    Здесь мы переносим готовое. GPT не трогаем — это обычный UPDATE.

    /admin_spread_unit_cards          → сколько карточек ждёт переноса
    /admin_spread_unit_cards apply    → перенести (до 2000 за раз)
    /admin_spread_unit_cards apply 500 → размер батча
    """
    sender = update.effective_user
    message = update.effective_message
    if not sender or not message:
        return
    if not _is_admin_user(sender.id):
        await message.reply_text("⛔️ Команда доступна только администратору.")
        return
    args = [a.strip().lower() for a in (context.args or [])]
    apply = "apply" in args
    batch = next((int(a) for a in args if a.isdigit() and 1 <= int(a) <= 20000), 2000)

    if not apply:
        from backend.lex_units import thin_entries_with_unit_card
        waiting = await asyncio.to_thread(thin_entries_with_unit_card, batch)
        await message.reply_text(
            f"💡 Ждут готового разбора: <b>{len(waiting)}</b> карточек "
            f"(смотрел до {batch}).\nЗапусти с <code>apply</code>, чтобы перенести — это бесплатно.",
            parse_mode="HTML",
        )
        return

    await message.reply_text(f"💡 Переношу готовый разбор в пустые карточки, до {batch} за раз…")
    try:
        from backend.backend_server import fill_thin_cards_from_units
        report = await asyncio.to_thread(fill_thin_cards_from_units, limit=batch)
    except Exception as exc:
        logging.exception("admin spread unit cards failed user_id=%s", int(sender.id))
        await message.reply_text(f"❌ Перенос упал: {exc}")
        return

    from html import escape as _esc
    samples = report.get("samples") or []
    lines = "\n".join(f"  • {_esc(str(s.get('word') or ''))}".rstrip() for s in samples[:15])
    text = (
        f"💡 <b>Перенос разбора в карточки</b>\n\n"
        f"Отобрано: <b>{report.get('picked', 0)}</b>\n"
        f"Наполнено: <b>{report.get('filled', 0)}</b>\n"
        f"Нечего добавить: {report.get('skipped', 0)}\n"
        f"Ошибок: {report.get('errors', 0)}"
    )
    if lines:
        text += f"\n\n<b>Примеры:</b>\n{lines}"
    if report.get("picked", 0) >= batch:
        text += "\n\nБатч выбран целиком — запусти ещё раз для следующего."
    for part in _split_telegram_text(text):
        await message.reply_text(part, parse_mode="HTML", disable_web_page_preview=True)


def _run_dictionary_raw_text_repair_safe() -> None:
    """Ночной бесплатный ремонт карточек (03:05 Вена — до платного добора пула в 03:10).

    Ни одного вызова GPT: берём ответ модели, который уже сохранён в записи, и собираем
    из него карточку. Молча — отдельный отчёт не нужен, итог видно в логах."""
    try:
        report = repair_dictionary_cards_from_raw_text(dry_run=False, max_entries=300)
        logging.info(
            "nightly dictionary raw_text repair: scanned=%s repaired=%s unparsable=%s thin=%s remaining=%s",
            report.get("scanned"), report.get("repaired"), report.get("unparsable"),
            report.get("still_thin"), report.get("remaining"),
        )
    except Exception:
        logging.warning("nightly dictionary raw_text repair failed", exc_info=True)


async def admin_backfill_frequency_command(update: Update, context: CallbackContext):
    """Compute/refresh frequency_rank for saved vocabulary so SRS introduces the
    most frequent (useful) words first. Free, no LLM — corpus rank → LLM band → NULL.

    Usage:
      /admin_backfill_frequency            → your entries, only rows still missing a rank
      /admin_backfill_frequency all        → ALL users, only rows missing a rank
      /admin_backfill_frequency all rescan → ALL users, recompute every row
    """
    sender = update.effective_user
    message = update.effective_message
    if not sender or not message:
        return
    if not _is_admin_user(sender.id):
        await message.reply_text("⛔️ Команда доступна только администратору.")
        return
    args = [a.strip().lower() for a in (context.args or [])]
    all_users = "all" in args
    rescan = "rescan" in args  # recompute every row, not just those missing a rank
    target_user_id = None if all_users else int(sender.id)
    scope = "ВСЕ пользователи" if all_users else "только ваши записи"
    mode = "пересчёт всех строк" if rescan else "только строки без ранга"
    await message.reply_text(
        f"🔢 Частотный ранг слов: {mode}, {scope}. Погнали…"
    )
    try:
        report = await asyncio.to_thread(
            backfill_frequency_ranks,
            batch_size=2000,
            only_missing=not rescan,
            user_id=target_user_id,
        )
    except Exception as exc:
        logging.exception("admin backfill frequency failed user_id=%s", int(sender.id))
        await message.reply_text(f"❌ Backfill упал: {exc}")
        return
    text = (
        "📊 <b>Частотный ранг: готово</b>\n\n"
        f"Обработано: <b>{report.get('processed', 0)}</b>\n"
        f"Обновлено: <b>{report.get('updated', 0)}</b>\n"
        f"С рангом (корпус/LLM): <b>{report.get('with_rank', 0)}</b>\n"
        f"Батчей: {report.get('batches', 0)}"
    )
    await message.reply_text(text, parse_mode="HTML")


async def clear_dictionary_queue_command(update: Update, context: CallbackContext):
    """Flush the caller's own pending fast-translate queue (memory + all Redis keys)."""
    sender = update.effective_user
    message = update.effective_message
    if not sender or not message:
        return
    user_id = int(sender.id)
    # If a "Быстрый перевод" batch is running, this is also a STOP request. The batch already
    # snapshotted + purged the queue at launch, so it runs from memory — flag it to abort after
    # the current chunk instead of misleadingly reporting "0 removed" while it keeps sending.
    if user_id in pending_dictionary_batch_fast_inflight:
        pending_dictionary_batch_fast_cancel.add(user_id)
        await message.reply_text(
            "🛑 Останавливаю текущий «Быстрый перевод»… (завершит начатое и прекратит).\n"
            "Очередь уже пуста — следующий запуск начнётся с чистого листа."
        )
        return
    # Pull any Redis-only residue into memory first so the reported count is accurate.
    try:
        await asyncio.to_thread(_list_pending_dictionary_lookup_request_keys_for_user, user_id)
    except Exception:
        logging.debug("clearqueue: restore-before-purge failed user_id=%s", user_id, exc_info=True)
    dropped = await asyncio.to_thread(_purge_all_pending_dictionary_for_user, user_id)
    await message.reply_text(
        f"🧹 Очередь быстрого перевода очищена. Убрано записей: {dropped}.\n"
        "Следующий «Быстрый перевод» начнётся с чистого листа."
    )


async def handle_admin_economics_callback(update: Update, context: CallbackContext):
    query = update.callback_query
    admin = update.effective_user
    if not query or not admin:
        return
    if not _is_admin_user(admin.id):
        await query.answer("Команда доступна только администратору.", show_alert=True)
        return
    data = str(query.data or "").strip()
    if data.startswith("admecon:noop:"):
        await query.answer("Выберите изменение лимита ниже.", show_alert=False)
        return
    if data == "admecon:refresh":
        await query.answer("Обновляю…", show_alert=False)
        try:
            payload = await asyncio.to_thread(build_admin_economics_report_payload)
            text = await asyncio.to_thread(format_admin_economics_report, payload)
            keyboard_payload = await asyncio.to_thread(build_admin_economics_limits_keyboard)
            reply_markup = _inline_markup_from_payload(keyboard_payload)
            if query.message:
                parts = _split_telegram_text(text)
                try:
                    await query.message.edit_text(
                        parts[0],
                        reply_markup=reply_markup if len(parts) == 1 else None,
                        disable_web_page_preview=True,
                    )
                    for index, part in enumerate(parts[1:], start=1):
                        await query.message.reply_text(
                            part,
                            reply_markup=reply_markup if index == len(parts) - 1 else None,
                            disable_web_page_preview=True,
                        )
                except Exception:
                    for index, part in enumerate(parts):
                        await query.message.reply_text(
                            part,
                            reply_markup=reply_markup if index == len(parts) - 1 else None,
                            disable_web_page_preview=True,
                        )
        except Exception as exc:
            logging.exception("admin economics refresh failed user_id=%s", int(admin.id))
            await query.answer(f"Ошибка: {exc}", show_alert=True)
        return

    preview_match = re.match(r"^admecon:preview:([a-z0-9_]+):(-?\d+)$", data)
    if preview_match:
        feature_code = str(preview_match.group(1) or "").strip().lower()
        delta = int(preview_match.group(2) or 0)
        await query.answer("Готовлю preview…", show_alert=False)
        try:
            preview = await asyncio.to_thread(
                create_admin_limit_change_preview,
                admin_user_id=int(admin.id),
                feature_code=feature_code,
                delta=delta,
            )
            text = await asyncio.to_thread(format_admin_limit_preview, preview)
            keyboard_payload = build_admin_limit_preview_keyboard(str(preview.get("token") or ""))
            reply_markup = _inline_markup_from_payload(keyboard_payload)
            if query.message:
                await query.message.reply_text(text, reply_markup=reply_markup)
        except Exception as exc:
            logging.exception("admin economics preview failed user_id=%s feature=%s", int(admin.id), feature_code)
            await query.answer(f"Ошибка preview: {exc}", show_alert=True)
        return

    apply_match = re.match(r"^admecon:apply:([A-Za-z0-9_-]+)$", data)
    if apply_match:
        token = str(apply_match.group(1) or "").strip()
        await query.answer("Применяю…", show_alert=False)
        try:
            result = await asyncio.to_thread(
                apply_admin_limit_change,
                token=token,
                admin_user_id=int(admin.id),
                telegram_message_id=int(query.message.message_id) if query.message else None,
                reason="telegram_admin_economics",
            )
            text = (
                "✅ Limit updated\n\n"
                f"Limit: {result.get('feature_code')}\n"
                f"Old: {result.get('old_value')}\n"
                f"New: {result.get('new_value')}\n"
                f"Audit ID: {result.get('audit_id')}"
            )
            if query.message:
                try:
                    await query.message.edit_text(text)
                except Exception:
                    await query.message.reply_text(text)
        except Exception as exc:
            logging.exception("admin economics apply failed user_id=%s", int(admin.id))
            await query.answer(f"Ошибка apply: {exc}", show_alert=True)
        return

    cancel_match = re.match(r"^admecon:cancel:([A-Za-z0-9_-]+)$", data)
    if cancel_match:
        token = str(cancel_match.group(1) or "").strip()
        await asyncio.to_thread(cancel_admin_limit_change, token, admin_user_id=int(admin.id))
        await query.answer("Отменено.", show_alert=False)
        if query.message:
            try:
                await query.message.edit_text("❌ Limit change cancelled.")
            except Exception:
                await query.message.reply_text("❌ Limit change cancelled.")
        return

    await query.answer("Некорректная кнопка.", show_alert=True)


# ── Cost-control Phase 1: app-wide weekly spend-ceiling tick + admin buttons ──
# Heavy lifting lives in backend/spend_ceiling.py (imported lazily → no import cycle).
# SHADOW-FIRST: the tick only DMs admins with soft/hard alerts; it pauses the "heavy"
# tier ONLY when APP_SPEND_CEILING_ENFORCE is enabled. Nothing here blocks users by default.
def _app_spend_ceiling_enforce_enabled() -> bool:
    return (os.getenv("APP_SPEND_CEILING_ENFORCE", "") or "").strip().lower() in ("1", "true", "yes", "on")


async def _app_spend_ceiling_tick_job(context: CallbackContext) -> None:
    try:
        from backend import spend_ceiling as _sc
        decision = await asyncio.to_thread(_sc.evaluate_ceiling)
    except Exception:
        logging.debug("spend-ceiling tick: evaluate failed", exc_info=True)
        return
    if not isinstance(decision, dict) or decision.get("error"):
        return
    _record_sched_heartbeat("app_spend_ceiling_tick", metadata={"pct": decision.get("pct"), "spent_eur": decision.get("spent_eur")})
    try:
        admin_ids = [int(a) for a in (get_admin_telegram_ids() or []) if int(a) > 0]
    except Exception:
        admin_ids = []
    if not admin_ids:
        return

    # 1) Alerts — deduped inside evaluate_ceiling via notified_thresholds (fire once/week).
    text = None
    if decision.get("hard_newly"):
        text = _sc.format_hard_alert(decision)
    elif decision.get("new_soft"):
        text = _sc.format_soft_alert(decision)
    if text:
        try:
            kb = _sc.build_appcap_keyboard()
        except Exception:
            kb = None
        for aid in admin_ids:
            try:
                await context.bot.send_message(
                    chat_id=aid, text=text, parse_mode="HTML",
                    reply_markup=kb, suppress_private_keyboard_attach=True,
                )
            except Exception:
                logging.debug("spend-ceiling alert DM failed aid=%s", aid, exc_info=True)

    # 2) Auto-stop of the heavy tier — ONLY when explicitly enabled (shadow-first).
    if not _app_spend_ceiling_enforce_enabled() or not decision.get("hard"):
        return
    should_block = bool(decision.get("should_block_now"))
    if not should_block:
        gd = decision.get("grace_deadline")
        if gd:
            try:
                should_block = datetime.now(timezone.utc) >= datetime.fromisoformat(str(gd))
            except Exception:
                should_block = False
    if should_block and "heavy" not in (decision.get("blocked_tiers") or []):
        try:
            await asyncio.to_thread(_sc.set_tier_blocked, [_sc.TIER_HEAVY])
        except Exception:
            logging.debug("spend-ceiling auto-stop failed", exc_info=True)
            return
        for aid in admin_ids:
            try:
                await context.bot.send_message(
                    chat_id=aid,
                    text="⛔ Авто-стоп: тяжёлые функции остановлены (превышен недельный потолок затрат). "
                         "Дешёвое ядро (перевод, словарь) работает. Добавь бюджет кнопкой, чтобы возобновить.",
                    parse_mode="HTML", suppress_private_keyboard_attach=True,
                )
            except Exception:
                pass


def _reader_r2_orphan_sweep(dry_run: bool = True) -> dict:
    """One-time reclaim: delete R2 reader objects (source PDF / page renders / per-page audio)
    whose owning book no longer exists in bt_3_reader_library. dry_run=True only counts.
    SAFE: the live (user,doc) set fetch RAISES on DB error (caller aborts) so a failed fetch
    can never be mistaken for 'no live books' and wipe everything. Archived books stay live."""
    from backend.database import get_all_reader_library_owner_doc_ids
    from backend.r2_storage import r2_list_keys, r2_delete_keys
    live = get_all_reader_library_owner_doc_ids()  # raises on DB error -> abort
    prefixes = ("reader_source/", "reader_pages/", "reader-audio-pages/")
    scanned = 0
    orphan_keys: list[str] = []
    orphan_bytes = 0
    per_prefix: dict[str, dict] = {}
    for pfx in prefixes:
        p_obj = 0
        p_bytes = 0
        for key, size in r2_list_keys(pfx):
            scanned += 1
            parts = [x for x in key.split("/") if x]
            if len(parts) < 3:
                continue
            try:
                owner = (int(parts[1]), int(parts[2]))
            except Exception:
                continue
            if owner not in live:
                orphan_keys.append(key)
                orphan_bytes += size
                p_obj += 1
                p_bytes += size
        per_prefix[pfx] = {"objects": p_obj, "bytes": p_bytes}
    deleted = 0
    if not dry_run and orphan_keys:
        deleted = r2_delete_keys(orphan_keys)
    return {
        "dry_run": bool(dry_run),
        "scanned": scanned,
        "live_docs": len(live),
        "orphan_objects": len(orphan_keys),
        "orphan_bytes": orphan_bytes,
        "deleted": deleted,
        "per_prefix": per_prefix,
    }


async def reader_r2_orphans_command(update: Update, context: CallbackContext) -> None:
    """Admin: reclaim orphaned reader R2 storage. '/reader_r2_orphans' = dry-run (count only);
    '/reader_r2_orphans delete' = actually delete."""
    user = update.effective_user
    if not user or not _is_admin_user(int(user.id)):
        return
    args = context.args or []
    do_delete = bool(args) and str(args[0]).strip().lower() in ("delete", "del", "run", "yes", "go")
    await update.message.reply_text(
        "🧹 Удаляю осиротевшие объекты R2 ридера…" if do_delete
        else "🔎 Считаю осиротевшие объекты R2 ридера (dry-run)…"
    )
    try:
        res = await asyncio.to_thread(_reader_r2_orphan_sweep, not do_delete)
    except Exception as exc:
        await update.message.reply_text(f"❌ Ошибка sweep (ничего не удалено): {exc}")
        return
    mb = res["orphan_bytes"] / 1024 / 1024
    head = "🗑 Удалено" if not res["dry_run"] else "🔎 Найдено (dry-run)"
    lines = [
        f"{head}: {res['orphan_objects']} объектов, ~{mb:.1f} МБ",
        f"Живых книг: {res['live_docs']} · просканировано объектов: {res['scanned']}",
    ]
    for pfx, st in res["per_prefix"].items():
        lines.append(f"• {pfx} — {st['objects']} сирот, ~{st['bytes'] / 1024 / 1024:.1f} МБ")
    if res["dry_run"] and res["orphan_objects"]:
        lines.append("\nУдалить: /reader_r2_orphans delete")
    await update.message.reply_text("\n".join(lines))


