async def _weekly_r2_cleanup_job(context: CallbackContext) -> None:
    """WEEKLY auto-clean of orphaned R2 storage — GLOBAL (all users / the whole pool bank),
    so nothing has to be run by hand: reader objects (PDF / page renders / audio) of DELETED
    books + retired game-pool images (rebus / article_quiz / crossword). Measures R2 before &
    after and DMs admins a short summary (было → стало, сколько МБ, по категориям). Primary
    bot process only; best-effort.

    Idempotent per ISO week: claims a DB run-guard keyed to the year+week, so a second
    invocation in the same week (e.g. a Railway redeploy landing on the Monday slot, or a
    second scheduler-enabled process) is skipped instead of re-sending the report."""
    try:
        _vien_day = datetime.now(ZoneInfo("Europe/Vienna")).date()
        _iso_y, _iso_w, _ = _vien_day.isocalendar()
        _run_period = f"{_iso_y}-W{_iso_w:02d}"
        from backend.database import claim_scheduler_run_guard
        if not claim_scheduler_run_guard(
            job_key="weekly_r2_cleanup", run_period=_run_period, target_scope="global",
        ):
            logging.info("weekly R2 cleanup skipped: already ran this ISO week (%s)", _run_period)
            return
    except Exception:
        # Guard is best-effort — if the guard table is unreachable, fall through and run
        # (the fixed weekly slot already prevents the per-deploy spam on its own).
        logging.debug("weekly R2 cleanup: run-guard claim failed, running unguarded", exc_info=True)

    def _gb(b):
        return (b or 0) / 1024 / 1024 / 1024

    async def _measure():
        try:
            from backend.r2_storage import r2_bucket_usage_summary
            return await asyncio.to_thread(r2_bucket_usage_summary, prefix_depth=1, max_prefixes=60)
        except Exception:
            return {}

    before = await _measure()
    reader_res, pool_res = {}, {}
    try:
        reader_res = await asyncio.to_thread(_reader_r2_orphan_sweep, False)
    except Exception:
        logging.warning("weekly R2 cleanup: reader sweep failed", exc_info=True)
    try:
        from backend.database import reclaim_retired_pool_r2_orphans
        pool_res = await asyncio.to_thread(reclaim_retired_pool_r2_orphans, dry_run=False)
    except Exception:
        logging.warning("weekly R2 cleanup: pool reclaim failed", exc_info=True)
    after = await _measure()

    b_bytes, b_obj = int(before.get("total_bytes") or 0), int(before.get("total_objects") or 0)
    a_bytes, a_obj = int(after.get("total_bytes") or 0), int(after.get("total_objects") or 0)
    freed_mb = max(0, b_bytes - a_bytes) / 1024 / 1024
    per_pool = pool_res.get("per_pool") or {}
    reader_del = int(reader_res.get("deleted") or reader_res.get("orphan_objects") or 0)
    pool_total = int(pool_res.get("total") or 0)

    lines = ["🧹 <b>Недельная авто-чистка R2</b>"]
    if before and after:
        lines.append(f"Было: {_gb(b_bytes):.2f} ГБ ({b_obj} об.) → Стало: {_gb(a_bytes):.2f} ГБ ({a_obj} об.)")
    lines.append(f"Освобождено: ~{freed_mb:.1f} МБ · удалено объектов: {reader_del + pool_total}")
    lines.append("")
    lines.append(f"📖 Книги (удалённые): {reader_del} об.")
    lines.append(
        f"🧩 Интерактивы (ретайрнутые): rebus {int(per_pool.get('rebus', 0))} · "
        f"article_quiz {int(per_pool.get('article_quiz', 0))} · crossword {int(per_pool.get('crossword', 0))}"
    )
    lines.append(
        f"🔤 Артикли (снятые слова): картинки {int(per_pool.get('artikel_img', 0))} · "
        f"озвучка {int(per_pool.get('artikel_audio', 0))}"
    )
    text = "\n".join(lines)
    logging.info("weekly R2 cleanup done: freed_mb=%.1f reader=%s pools=%s", freed_mb, reader_del, per_pool)
    try:
        admin_ids = [int(a) for a in (get_admin_telegram_ids() or []) if int(a) > 0]
    except Exception:
        admin_ids = []
    for aid in admin_ids:
        try:
            await context.bot.send_message(
                chat_id=aid, text=text, parse_mode="HTML", suppress_private_keyboard_attach=True,
            )
        except Exception:
            logging.debug("weekly R2 cleanup DM failed aid=%s", aid, exc_info=True)
    _record_sched_heartbeat("weekly_r2_cleanup", metadata={"freed_mb": round(freed_mb, 1), "reader": reader_del, "pools": per_pool})


async def pool_r2_orphans_command(update: Update, context: CallbackContext) -> None:
    """Admin: reclaim R2 images of RETIRED game-pool items (rebus/article_quiz/crossword) plus
    the картинки/озвучка of words retired from the article bank, all left orphaned by the
    rotation/cleanup. '/pool_r2_orphans' = dry-run; add 'delete' to write. Crossword and the
    article bank are age-guarded so the revive path isn't broken."""
    user = update.effective_user
    if not user or not _is_admin_user(int(user.id)):
        return
    args = context.args or []
    do_delete = bool(args) and str(args[0]).strip().lower() in ("delete", "del", "run", "yes", "go")
    await update.message.reply_text(
        "🧹 Удаляю осиротевшие файлы игровых пулов…" if do_delete
        else "🔎 Считаю осиротевшие файлы игровых пулов (dry-run)…"
    )
    try:
        from backend.database import reclaim_retired_pool_r2_orphans
        res = await asyncio.to_thread(reclaim_retired_pool_r2_orphans, dry_run=not do_delete)
    except Exception as exc:
        await update.message.reply_text(f"❌ Ошибка (ничего не изменено): {exc}")
        return
    head = "🗑 Удалено" if not res["dry_run"] else "🔎 Найдено (dry-run)"
    lines = [f"{head}: {res['total']} осиротевших файлов снятых заданий и слов."]
    for pool, n in (res.get("per_pool") or {}).items():
        lines.append(f"• {pool} — {n}")
    if res["dry_run"] and res["total"]:
        lines.append("\nУдалить: /pool_r2_orphans delete")
    await update.message.reply_text("\n".join(lines))


async def r2_usage_command(update: Update, context: CallbackContext) -> None:
    """Admin: real R2 storage size per top-level prefix (read-only). Use it to see whether any
    remaining prefix (tts_legacy, support_attachments, pool art, …) is worth cleaning."""
    user = update.effective_user
    if not user or not _is_admin_user(int(user.id)):
        return
    await update.message.reply_text("📦 Считаю размер R2 по префиксам…")
    try:
        from backend.r2_storage import r2_bucket_usage_summary
        s = await asyncio.to_thread(r2_bucket_usage_summary, prefix_depth=1, max_prefixes=60)
    except Exception as exc:
        await update.message.reply_text(f"❌ Ошибка замера R2: {exc}")
        return

    def _fmt(num_bytes: int) -> str:
        if num_bytes >= 1024 ** 3:
            return f"{num_bytes / 1024 ** 3:.2f} ГБ"
        return f"{num_bytes / 1024 / 1024:.1f} МБ"

    total_b = int(s.get("total_bytes") or 0)
    lines = [f"📦 <b>R2 всего: {_fmt(total_b)}</b> · {int(s.get('total_objects') or 0)} объектов", ""]
    for p in s.get("prefixes", []):
        lines.append(f"• {p.get('prefix')} — {_fmt(int(p.get('bytes') or 0))} · {int(p.get('objects') or 0)} об.")
    await update.message.reply_text("\n".join(lines), parse_mode="HTML")


async def handle_appcap_callback(update: Update, context: CallbackContext) -> None:
    query = update.callback_query
    admin = update.effective_user
    if not query or not admin:
        return
    if not _is_admin_user(admin.id):
        await query.answer("Команда доступна только администратору.", show_alert=True)
        return
    parts = str(query.data or "").split(":")   # appcap:add:5 | appcap:stop | appcap:why
