# ── Onboarding tour: one-time announce (A) + gentle nudges (B) ────────────────
ONBOARDING_TOUR_ANNOUNCE_KEY = "onboarding_tour_v1"
ONBOARDING_NUDGE_PER_DAY = max(1, int((os.getenv("ONBOARDING_NUDGE_PER_DAY") or "2").strip() or "2"))
ONBOARDING_NUDGE_MAX_TOTAL = max(1, int((os.getenv("ONBOARDING_NUDGE_MAX_TOTAL") or "6").strip() or "6"))
ONBOARDING_NUDGE_BATCH = max(1, int((os.getenv("ONBOARDING_NUDGE_BATCH") or "300").strip() or "300"))


async def _send_tour_invite(context: CallbackContext, chat_id: int, *, announce: bool) -> tuple[bool, str | None]:
    """Send the branded tour-invite card + «🚀 Пройти тур» / «Позже».
    announce=True → the one-time «bot updated» card; False → a gentle nudge.
    Returns (ok, error_reason) — reason is the exception name on failure (for reports)."""
    if announce:
        title = "Бот обновился"
        subtitle = "Загляни на быстрый тур — узнай все возможности за пару минут."
        lead = "✨ <b>Мы обновили бота!</b>"
    else:
        title = "Не забыл про тур?"
        subtitle = "Пара минут — и узнаешь, что умеет бот и что уже доступно тебе."
        lead = "👋 <b>Загляни на быстрый тур</b>"
    caption = (
        f"{lead}\n\n{subtitle}\n\n"
        "Нажми «🚀 Пройти тур» — покажу все возможности. Ненужное всегда можно отключить в настройках."
    )
    kb = InlineKeyboardMarkup([
        [InlineKeyboardButton("🚀 Пройти тур", url=get_webapp_deeplink("onboarding"))],
        [InlineKeyboardButton("Позже", callback_data="tour:later")],
    ])
    poster = None
    try:
        from backend.interactive_card import render_tour_invite_card
        poster = await asyncio.to_thread(render_tour_invite_card, title=title, subtitle=subtitle)
    except Exception:
        poster = None
    for attempt in (1, 2):
        try:
            if poster:
                await context.bot.send_photo(
                    chat_id=int(chat_id), photo=io.BytesIO(poster), caption=caption,
                    parse_mode="HTML", reply_markup=kb, suppress_private_keyboard_attach=True)
            else:
                await context.bot.send_message(
                    chat_id=int(chat_id), text=caption, parse_mode="HTML",
                    reply_markup=kb, suppress_private_keyboard_attach=True)
            return True, None
        except RetryAfter as exc:
            if attempt == 2:
                return False, "RetryAfter"
            await asyncio.sleep(max(1, int(getattr(exc, "retry_after", 1))))
        except Exception as exc:
            return False, type(exc).__name__
    return False, "unknown"


async def _tour_later_callback(update: Update, context: CallbackContext) -> None:
    """«Позже» on a tour invite → stop nudging this user (tour stays reachable)."""
    q = update.callback_query
    if not q:
        return
    try:
        await q.answer("Хорошо, не буду напоминать 🙂")
    except Exception:
        pass
    user = update.effective_user
    if user:
        try:
            await asyncio.to_thread(set_onboarding_nudge_dismissed, int(user.id))
        except Exception:
            pass
    ack = ("Хорошо, не буду напоминать 🙂\n"
           "Открыть тур можно в любой момент — кнопка «🎬 Как пользоваться» в меню снизу.")
    try:
        await q.edit_message_caption(caption=ack, reply_markup=None)
    except Exception:
        try:
            await q.edit_message_text(text=ack, reply_markup=None)
        except Exception:
            try:
                await q.edit_message_reply_markup(reply_markup=None)
            except Exception:
                pass


async def _onboarding_announce_command(update: Update, context: CallbackContext) -> None:
    """/onboarding_announce — one-time «bot updated, take the tour» broadcast (A).
    No args → preview to yourself. `send` → broadcast to every allowed user who hasn't
    completed onboarding and wasn't told yet (re-run-safe)."""
    user = update.effective_user
    message = update.effective_message
    if not user or not message:
        return
    if not _can_use_image_quiz_test_commands(getattr(user, "id", None)):
        await message.reply_text("Allowed users only.")
        return
    args = context.args or []
    mode = (args[0].strip().lower() if args else "")
    if mode != "send":
        await _send_tour_invite(context, int(user.id), announce=True)
        await message.reply_text(
            "👆 Так выглядит анонс тура.\n"
            "Разослать ВСЕМ, кто ещё не прошёл онбординг: /onboarding_announce send")
        return
    ids = await asyncio.to_thread(list_allowed_telegram_user_ids)
    admin_ids = set()
    try:
        admin_ids = {int(x) for x in get_admin_telegram_ids() if int(x) > 0}
    except Exception:
        pass
    await message.reply_text(f"📣 Рассылаю анонс тура… кандидатов: {len(ids)}")
    sent = 0
    skip_admin = skip_synth = skip_seen = skip_done = 0
    err_counts: dict[str, int] = {}
    for idx, uid in enumerate(ids, start=1):
        try:
            uid = int(uid)
            if uid in admin_ids:
                skip_admin += 1
                continue
            if _is_synthetic_telegram_user_id(uid):
                skip_synth += 1
                continue
            if await asyncio.to_thread(was_announcement_sent, uid, ONBOARDING_TOUR_ANNOUNCE_KEY):
                skip_seen += 1
                continue
            st = await asyncio.to_thread(get_onboarding_state, uid)
            if st and st.get("completed"):
                skip_done += 1
                continue
            ok, err = await _send_tour_invite(context, uid, announce=True)
            if ok:
                await asyncio.to_thread(mark_announcement_sent, uid, ONBOARDING_TOUR_ANNOUNCE_KEY)
                sent += 1
            else:
                key = err or "unknown"
                err_counts[key] = err_counts.get(key, 0) + 1
        except Exception as exc:
            key = type(exc).__name__
            err_counts[key] = err_counts.get(key, 0) + 1
            logging.warning("onboarding announce loop failed uid=%s", uid, exc_info=True)
        if idx % 20 == 0:
            await asyncio.sleep(1.0)
    total_skipped = skip_admin + skip_synth + skip_seen + skip_done
    total_failed = sum(err_counts.values())
    err_detail = ", ".join(f"{k}×{v}" for k, v in sorted(err_counts.items(), key=lambda x: -x[1])) if err_counts else "—"
    await message.reply_text(
        "✅ <b>Анонс тура завершён</b>\n"
        f"Кандидатов: <b>{len(ids)}</b>\n"
        f"📨 Отправлено: <b>{sent}</b>\n"
        f"⏭ Пропущено: <b>{total_skipped}</b>\n"
        f"   • тест/синтетические: {skip_synth}\n"
        f"   • админы: {skip_admin}\n"
        f"   • уже получали анонс: {skip_seen}\n"
        f"   • уже прошли онбординг: {skip_done}\n"
        f"⚠️ Ошибок доставки: <b>{total_failed}</b> ({err_detail})\n"
        "<i>Ошибки — это обычно те, кто заблокировал бота или удалил аккаунт (Forbidden/BadRequest). "
        "Норма для любой рассылки. Синтетическим/тест-юзерам анонс НЕ уходит.</i>",
        parse_mode="HTML")


async def _onboarding_nudge_job(context: CallbackContext) -> None:
    """Scheduled gentle nudge (B): invite un-onboarded users to the tour. Respects the
    per-day + lifetime caps and quiet hours; completed/dismissed users are excluded."""
    if not _onboarding_enabled():
        return
    if _is_quiet_hours_now():
        return
    try:
        allowed = await asyncio.to_thread(list_allowed_telegram_user_ids)
    except Exception:
        allowed = []
    admin_ids = set()
    try:
        admin_ids = {int(x) for x in get_admin_telegram_ids() if int(x) > 0}
    except Exception:
        pass
    cand = [int(u) for u in allowed
            if int(u) > 0 and int(u) not in admin_ids and not _is_synthetic_telegram_user_id(int(u))]
    if not cand:
        return
    targets = await asyncio.to_thread(
        list_onboarding_nudge_candidates, cand,
        max_per_day=ONBOARDING_NUDGE_PER_DAY, max_total=ONBOARDING_NUDGE_MAX_TOTAL,
        limit=ONBOARDING_NUDGE_BATCH)
    if not targets:
        return
    logging.info("onboarding nudge job: %s target(s)", len(targets))
    for idx, uid in enumerate(targets, start=1):
        try:
            ok, _err = await _send_tour_invite(context, int(uid), announce=False)
            if ok:
                await asyncio.to_thread(record_onboarding_nudge, int(uid))
        except Exception:
            logging.warning("onboarding nudge failed uid=%s", uid, exc_info=True)
        if idx % 20 == 0:
            await asyncio.sleep(1.0)


async def start(update: Update, context: CallbackContext):
    """Запуск бота и отправка главного меню."""
    user = update.effective_user
    # First-touch referral capture must run BEFORE access is granted: _maybe_capture_referral
    # only attributes users who are NOT yet allowed, and the self-serve grant below flips
    # exactly that flag. Swap the order and every referral silently stops counting.
    if user:
        try:
            await _maybe_capture_referral(context, update, int(user.id))
        except Exception:
            logging.warning("referral capture failed", exc_info=True)
    if user and not await asyncio.to_thread(is_telegram_user_allowed, int(user.id)):
        # Self-serve access: an invite link is the invitation. Only someone an admin
        # explicitly denied stays out (auto_grant_telegram_user returns False for them).
        source = _auto_access_source_label(context)
        granted = await asyncio.to_thread(
            auto_grant_telegram_user,
            int(user.id),
            _display_user_name(user),
            source,
        )
        if granted:
            await _notify_admins_new_user(context, user, source=source)
        else:
            await _send_access_closed_reply(update, context)
            return

    context.user_data.setdefault("service_message_ids", [])  # Инициализируем список
    if update.effective_chat and update.effective_chat.type == "private":
        # /start = явный жест пользователя «верни мне меню». Принудительно пере-доставляем
        # reply-клавиатуру ДАЖE если версия уже помечена доставленной: DM-клавиатуру можно
        # потерять на стороне Telegram (удалён якорь / состояние клиента), а обычная
        # доставка «раз на версию» её больше никогда не пере-шлёт → «кнопки пропали».
        if user:
            try:
                await _ensure_reply_keyboard_delivered(context.bot, int(user.id), force=True)
            except Exception:
                pass
        # /start is an explicit "начни здесь" action → always route to the onboarding
        # wizard (it holds the real setup: язык, словарь, установка Shortcut, иконка
        # словаря, темп заданий), not the plain returning-user menu.
        #
        # We deliberately DO NOT check the server-side "completed" flag: it's keyed by
        # user_id and survives deleting + re-installing the bot, so a returning user who
        # reinstalls still reads as completed=True and the old gate bounced them to the
        # bare menu instead of the setup they actually need again. New users, reinstalled
        # users, everyone gets onboarding on /start. The onboarding card still delivers
        # the DM menu keyboard (piggybacked by TrackingExtBot), so nobody loses buttons.
        if _onboarding_enabled() and user:
            await _send_onboarding_prompt(update, context)
            return
        await send_main_menu(update, context)

async def log_message(update: Update, context: CallbackContext):
    """логируются (сохраняются) все сообщения пользователей в базе данных"""
    if not update.message: #Если update.message отсутствует, значит, пользователь отправил что-то другое (например, фото, видео, стикер).
        return #В таком случае мы не логируем это и просто выходим из функции
    
    user = update.message.from_user # Данные о пользователе содержит ID и имя пользователя.
    message_text = update.message.text.strip() if update.message else "" #сам текст сообщения.

    if not message_text:
        return
    if not user:
        return
    safe_user_id = int(user.id)
    if _is_synthetic_telegram_user_id(safe_user_id):
        return
    if not _should_persist_message_activity(safe_user_id):
        return

    username = user.username or f"{user.first_name or ''} {user.last_name or ''}".strip()
    try:
        await asyncio.to_thread(_persist_message_activity_touch, safe_user_id, username)
    except Exception:
        logging.warning("⚠️ Ошибка при записи bt_3_messages activity for user_id=%s", safe_user_id, exc_info=True)

# утреннее приветствие членом группы
