def _parse_admin_rebus_words(raw_text: str) -> list[str]:
    text = re.sub(r"^/admin_rebus_add(?:@\w+)?", "", str(raw_text or "").strip(), flags=re.IGNORECASE).strip()
    if not text:
        return []
    candidates: list[str] = []
    for part in re.split(r"[\n,;]+", text):
        item = re.sub(r"^\s*[-*•\d.)]+\s*", "", part).strip()
        if not item:
            continue
        item = re.split(r"\s[-–—:]\s", item, maxsplit=1)[0].strip()
        item = re.sub(r"^(der|die|das)\s+", "", item, flags=re.IGNORECASE).strip()
        if item and re.search(r"[A-Za-zÄÖÜäöüß]", item):
            candidates.append(item)
    return candidates


def _format_rebus_manual_import_report(result: dict) -> str:
    duplicates_existing = list(result.get("duplicates_existing") or [])
    duplicates_input = list(result.get("duplicates_input") or [])
    errors = list(result.get("errors") or [])
    prepared = list(result.get("prepared") or [])
    lines = [
        "🧩 Rebus import report",
        "",
        f"Requested: {int(result.get('requested') or 0)}",
        f"Sent to GPT: {int(result.get('sent_to_gpt') or 0)}",
        f"Added to DB: {int(result.get('added') or 0)}",
        f"Images ready: {int(result.get('prepared_ready') or 0)}",
        f"Image failures: {int(result.get('prepared_failed') or 0)}",
    ]
    if duplicates_existing:
        lines.extend(["", "Already existed:"] + [f"• {w}" for w in duplicates_existing[:20]])
    if duplicates_input:
        lines.extend(["", "Duplicate in your message:"] + [f"• {w}" for w in duplicates_input[:20]])
    if prepared:
        lines.extend(["", "Prepared:"])
        for item in prepared[:20]:
            tail = f" — {item.get('reason')}" if item.get("reason") else ""
            lines.append(f"• {item.get('compound')} ({item.get('status')}){tail}")
    if errors:
        lines.extend(["", "Errors / skipped:"] + [f"• {err}" for err in errors[:20]])
    return "\n".join(lines)[:3900]


def _format_rebus_manual_import_progress(payload: dict) -> str:
    stage = str(payload.get("stage") or "").strip().lower()
    if stage == "validated_input":
        return (
            "Принял список.\n"
            f"Уникальных слов: {int(payload.get('requested') or 0)}\n"
            f"К импорту: {int(payload.get('targets') or 0)}\n"
            f"Дубликаты в базе: {int(payload.get('duplicates_existing') or 0)}\n"
            f"Дубликаты в сообщении: {int(payload.get('duplicates_input') or 0)}\n\n"
            "Запрашиваю разметку у GPT..."
        )
    if stage == "gpt_request":
        return (
            f"GPT-разметка для {int(payload.get('requested') or 0)} слов запрошена.\n"
            "Жду ответ и валидирую результат..."
        )
    if stage == "preparing_images":
        compound = str(payload.get("compound") or "").strip()
        processed = int(payload.get("processed") or 0)
        total = int(payload.get("total") or 0)
        ready = int(payload.get("ready") or 0)
        failed = int(payload.get("failed") or 0)
        return (
            f"Генерирую картинки: {processed}/{total}\n"
            f"Текущий ребус: {compound or '—'}\n"
            f"Готово: {ready} | Ошибок: {failed}"
        )
    if stage == "image_done":
        compound = str(payload.get("compound") or "").strip()
        processed = int(payload.get("processed") or 0)
        total = int(payload.get("total") or 0)
        ready = int(payload.get("ready") or 0)
        failed = int(payload.get("failed") or 0)
        return (
            f"Картинки готовы: {processed}/{total}\n"
            f"Последний ребус: {compound or '—'}\n"
            f"Готово: {ready} | Ошибок: {failed}"
        )
    return (
        f"Импорт завершён.\n"
        f"Добавлено: {int(payload.get('added') or 0)}\n"
        f"Готово картинок: {int(payload.get('ready') or 0)}\n"
        f"Ошибок: {int(payload.get('failed') or 0)}"
    )


async def admin_rebus_add_command(update: Update, context: CallbackContext) -> None:
    """Admin command: import explicit admin-approved rebus words.

    Usage:
    /admin_rebus_add
    Handschuh
    Apfelbaum
    Sonnenbrille
    """
    user = update.effective_user
    message = update.effective_message
    if not user or not message:
        return
    if not _can_use_image_quiz_test_commands(getattr(user, "id", None)):
        await message.reply_text("Allowed users only.")
        return
    words = _parse_admin_rebus_words(message.text or "")
    if not words:
        await message.reply_text(
            "Пришли список немецких составных слов после команды, каждое с новой строки.\n\n"
            "Пример:\n"
            "/admin_rebus_add\n"
            "Handschuh\n"
            "Apfelbaum\n"
            "Sonnenbrille"
        )
        return
    if len(words) > 30:
        await message.reply_text("Слишком много за раз. Максимум 30 слов в одной команде.")
        return

    from backend.database import get_existing_rebus_compound_words
    existing_words = await asyncio.to_thread(get_existing_rebus_compound_words)
    existing_keys = {" ".join(str(w or "").strip().lower().split()) for w in existing_words}
    cleaned_words = [" ".join(str(w or "").strip().split()) for w in words if str(w or "").strip()]
    unique_words = []
    seen_keys = set()
    for word in cleaned_words:
        key = " ".join(word.lower().split())
        if key in seen_keys:
            continue
        seen_keys.add(key)
        unique_words.append(word)
    targets = [w for w in unique_words if " ".join(w.lower().split()) not in existing_keys]
    if not targets:
        duplicate_count = len(unique_words)
        await message.reply_text(
            "🧩 Rebus import report\n\n"
            f"Requested: {duplicate_count}\n"
            "Sent to GPT: 0\n"
            "Added to DB: 0\n"
            "Images ready: 0\n"
            "Image failures: 0\n\n"
            "All requested words already exist in the bank.\n"
            "Nothing to import."
        )
        return

    status_msg = await message.reply_text(
        f"Принял {len(words)} слов. Проверяю дубликаты, генерирую разметку и картинки…"
    )
    try:
        from backend.rebus_generator import generate_manual_rebus_entries
        loop = asyncio.get_running_loop()
        last_sent = {"text": ""}

        def _progress_cb(payload: dict) -> None:
            stage = str(payload.get("stage") or "").strip().lower()
            processed = int(payload.get("processed") or 0)
            total = int(payload.get("total") or 0)
            if stage not in {"validated_input", "gpt_request", "preparing_images", "image_done", "done"}:
                return
            if stage == "image_done" and processed not in {1, total} and processed % 3 != 0:
                return
            text = _format_rebus_manual_import_progress(payload)
            if text == last_sent["text"]:
                return
            last_sent["text"] = text
            asyncio.run_coroutine_threadsafe(status_msg.edit_text(text), loop)

        result = await asyncio.to_thread(
            generate_manual_rebus_entries,
            words,
            prepare_images=True,
            progress_cb=_progress_cb,
        )
    except Exception as exc:
        await status_msg.edit_text(f"Rebus import failed: {exc}")
        return
    await status_msg.edit_text(_format_rebus_manual_import_report(result))


async def admin_rebus_recheck_command(update: Update, context: CallbackContext) -> None:
    """Re-verify existing rebus component images against the vision gate; bad ones
    (wrong object / word↔meaning desync) are failed + their compounds reset to
    recompose with freshly gated images.

    /admin_rebus_recheck [limit]            — re-check ready images (cap 300)
    /admin_rebus_recheck pregate [limit]    — ONLY the pre-gate images (dalle_prompt
                                              NULL — generated before the image↔meaning
                                              gate existed, never validated). Cap 500.

    Both feed each image's expected Russian meaning (from the rebus parts) to the
    gate, so a stale image that no longer matches its part's meaning is caught —
    not just blatant wrong-object renders."""
    user = update.effective_user
    message = update.effective_message
    if not user or not message:
        return
    if not _can_use_image_quiz_test_commands(getattr(user, "id", None)):
        await message.reply_text("Allowed users only.")
        return
    args = [str(a).strip() for a in (context.args or [])]
    pregate = bool(args) and args[0].lower() in ("pregate", "pre", "stale")
    num_args = [a for a in args if a.isdigit()]
    cap = 500 if pregate else 300
    default = cap if pregate else 120
    try:
        limit = max(1, min(cap, int(num_args[0]))) if num_args else default
    except (ValueError, IndexError):
        limit = default
    status_msg = await message.reply_text(
        f"Перепроверяю до {limit} {'до-гейтовых ' if pregate else ''}картинок vision-гейтом…"
    )

    def _recheck(lim: int, pregate_only: bool) -> dict:
        from backend.database import (
            list_ready_rebus_component_images, upsert_rebus_component_image,
            reset_rebus_compounds_for_part, get_rebus_part_meanings,
        )
        from backend.openai_manager import run_image_depicts
        from backend.r2_storage import r2_get_bytes
        rows = list_ready_rebus_component_images(lim, pregate_only=pregate_only)
        meanings = get_rebus_part_meanings()
        checked = 0
        bad: list[str] = []
        reset = 0
        for row in rows:
            word = str(row.get("word") or "")
            key = str(row.get("image_object_key") or "")
            if not word or not key:
                continue
            try:
                img = r2_get_bytes(key)
            except Exception:
                continue
            if not img:
                continue
            checked += 1
            mime = "image/webp" if key.endswith(".webp") else "image/png"
            verdict = run_image_depicts(bytes(img), word, meaning=meanings.get(word, ""), mime=mime)
            if not verdict.get("ok"):
                bad.append(f"{word} ({verdict.get('reason') or '?'})")
                upsert_rebus_component_image(word, generation_status="failed",
                                             failure_reason=f"recheck vision: {verdict.get('reason') or ''}"[:500])
                reset += reset_rebus_compounds_for_part(word)
        return {"checked": checked, "bad": bad, "compounds_reset": reset}

    try:
        result = await asyncio.to_thread(_recheck, limit, pregate)
    except Exception as exc:
        await status_msg.edit_text(f"Error: {exc}")
        return
    bad = result.get("bad") or []
    text = (
        f"✅ Перепроверено: {result.get('checked')}\n"
        f"🔴 Забраковано: {len(bad)}\n"
        f"♻️ Слов на перекомпоновку: {result.get('compounds_reset')}\n"
    )
    if bad:
        text += "\nПлохие:\n" + "\n".join(f"• {b}" for b in bad[:25])
    text += "\n\nЗапусти /admin_rebus_pool — перегенерит забракованные уже с vision-гейтом."
    await status_msg.edit_text(text[:4000])


