async def admin_rebus_reset_command(update: Update, context: CallbackContext) -> None:
    """Re-sync the code bank, then force compounds containing the given part word(s)
    to recompose (drops the cached card) and refill the pool. Use after fixing a
    mislabelled part so the stale image is rebuilt. /admin_rebus_reset Ei [Wort2 …]

    /admin_rebus_reset stale — no word list: finds EVERY cached image whose prompt was
    changed in the code bank and redraws exactly those (a fixed prompt otherwise never
    reaches the picture, because the image is cached under its word forever)."""
    user = update.effective_user
    message = update.effective_message
    if not user or not message:
        return
    if not _can_use_image_quiz_test_commands(getattr(user, "id", None)):
        await message.reply_text("Allowed users only.")
        return
    args = [w.strip() for w in (context.args or []) if w.strip()]
    stale_mode = bool(args) and args[0].lower() in ("stale", "prompt", "prompts")
    words = [] if stale_mode else (args or ["Ei"])
    # Перерисовка идёт в BACKGROUND_JOBS, а не здесь: каждая картинка — поход к
    # gpt-image-1 на десятки секунд, а PTB собран без concurrent_updates, поэтому
    # прогон в хендлере молча вешает бота на ВСЕХ пользователей (03.08.2026 — на
    # двадцать минут). Отчёт придёт сюда же, когда воркер закончит.
    if stale_mode:
        # Тратить деньги — только по явному «go». Без него команда лишь показывает,
        # что именно перерисует и почём: 03.08.2026 молчаливый прогон перерисовал
        # 81 нормальную картинку, и остановить его было нечем.
        apply = any(a.lower() in ("go", "apply", "да", "давай") for a in args[1:])

        def _enqueue() -> dict:
            from backend.job_queue import enqueue_rebus_stale_redraw_job
            return enqueue_rebus_stale_redraw_job(
                chat_id=int(message.chat_id), cap=_REBUS_RESET_REDRAW_CAP, apply=apply,
            )

        try:
            outcome = await asyncio.to_thread(_enqueue)
        except Exception:
            logging.exception("admin_rebus_reset: enqueue failed")
            outcome = {"queued": False, "reason": "broker_error"}
        if outcome.get("queued"):
            await message.reply_text(
                ("📥 Перерисовываю — не больше "
                 f"{_REBUS_RESET_REDRAW_CAP} карточек за прогон.\n"
                 if apply else
                 "🔎 Смотрю, какие картинки разошлись с описаниями. Ничего не трогаю.\n")
                + "Считает отдельный воркер — бот в это время отвечает как обычно.\n"
                  "Отчёт пришлю сюда, когда закончит."
            )
        else:
            await message.reply_text(
                "Очередь задач недоступна — перерисовку НЕ запускаю. Картинки не тронуты.\n"
                "Прямо в боте больше не гоняю: это вешало бота на всё время прогона."
            )
        return
    status_msg = await message.reply_text(f"Ресинхр банка + сброс для: {', '.join(words)}…")

    def _reset(part_words: list[str]) -> dict:
        from backend.database import (
            sync_rebus_bank_from_code, reset_rebus_compounds_for_part,
        )
        from backend.rebus_generator import prepare_rebus_pool
        sync = sync_rebus_bank_from_code()
        reset = 0
        for w in part_words:
            reset += reset_rebus_compounds_for_part(w)
        pool = prepare_rebus_pool(target_ready=REBUS_POOL_TARGET, max_attempts=40)
        return {"sync": sync, "reset": reset, "pool": pool}

    try:
        result = await asyncio.to_thread(_reset, words)
    except Exception as exc:
        await status_msg.edit_text(f"Error: {exc}")
        return
    sync = result.get("sync") or {}
    pool = result.get("pool") or {}
    text = (
        f"✅ Sync: synced={sync.get('synced')} "
        f"skipped_inconsistent={sync.get('skipped_inconsistent')}\n"
        f"♻️ Сброшено на перекомпоновку: {result.get('reset')}\n"
        f"🧩 Pool: generated={pool.get('generated')} failed={pool.get('failed')}"
        + (f"\n🧩 Ждут твоей приёмки: {pool.get('awaiting_review')} — /admin_rebus_review"
           if pool.get("awaiting_review") else "")
    )
    await status_msg.edit_text(text[:4000])


async def admin_overtaken_images_command(update: Update, context: CallbackContext) -> None:
    """Generate the rotating Fox-mascot "you were overtaken" background images
    (podium / race) via gpt-image-1 and store them in R2. Run once; the overtaken
    plaque then picks one at random. /admin_overtaken_images"""
    user = update.effective_user
    message = update.effective_message
    if not user or not message:
        return
    if not _can_use_image_quiz_test_commands(getattr(user, "id", None)):
        await message.reply_text("Allowed users only.")
        return
    status_msg = await message.reply_text("Генерирую лис-картинки «тебя обошли»…")

    def _gen() -> dict:
        from backend.image_generation_provider import generate_image_bytes
        from backend.r2_storage import r2_put_bytes
        from backend.overtaken_card import OVERTAKEN_IMAGE_PROMPTS, overtaken_bg_keys
        keys = overtaken_bg_keys()
        made = 0
        errs: list[str] = []
        for i, prompt in enumerate(OVERTAKEN_IMAGE_PROMPTS):
            if i >= len(keys):
                break
            try:
                res = generate_image_bytes(prompt=prompt, template_id=0, user_id=0, action_type="overtaken_image")
                data = bytes(res.get("data") or b"")
                if not data:
                    raise RuntimeError("empty image payload")
                r2_put_bytes(keys[i], data, content_type="image/png",
                             cache_control="public, max-age=86400")
                made += 1
            except Exception as exc:
                errs.append(f"{i + 1}: {str(exc)[:120]}")
        return {"made": made, "total": len(OVERTAKEN_IMAGE_PROMPTS), "errs": errs}

    try:
        result = await asyncio.to_thread(_gen)
    except Exception as exc:
        await status_msg.edit_text(f"Error: {exc}")
        return
    text = f"✅ Сгенерировано: {result.get('made')}/{result.get('total')} (R2: overtaken/fox_*.png)"
    if result.get("errs"):
        text += "\n🔴 " + "\n".join(result["errs"][:5])
    text += "\n\nКэш фонов обновится в течение ~10 мин (или после рестарта)."
    await status_msg.edit_text(text[:4000])


