async def admin_artikel_settheme_command(update: Update, context: CallbackContext) -> None:
    """Pick the theme for a day. /artikel_settheme [tomorrow|today|YYYY-MM-DD] <theme_key>
    (one arg → defaults to tomorrow)."""
    user = update.effective_user
    message = update.effective_message
    if not user or not message:
        return
    if not _can_use_image_quiz_test_commands(getattr(user, "id", None)):
        await message.reply_text("Allowed users only.")
        return
    args = [a.strip() for a in (context.args or []) if a.strip()]
    if not args:
        await message.reply_text("Использование: /artikel_settheme [tomorrow|today|YYYY-MM-DD] <theme_key>")
        return
    today = _get_quiz_schedule_now().date()
    if len(args) == 1:
        when, theme_key = "tomorrow", args[0]
    else:
        when, theme_key = args[0].lower(), args[1]
    if when in ("tomorrow", "завтра"):
        play_date = today + timedelta(days=1)
    elif when in ("today", "сегодня"):
        play_date = today
    else:
        try:
            play_date = datetime.strptime(when, "%Y-%m-%d").date()
        except ValueError:
            await message.reply_text("Дата: tomorrow | today | YYYY-MM-DD")
            return
    theme = await asyncio.to_thread(get_article_sprint_theme, theme_key)
    if not theme:
        await message.reply_text(f"Нет темы <code>{html.escape(theme_key)}</code>. Список: /artikel_themes", parse_mode="HTML")
        return
    await asyncio.to_thread(set_article_sprint_theme_for_date, play_date, theme_key, set_by=int(user.id))
    await message.reply_text(
        f"✅ {play_date.isoformat()} → <b>{html.escape(theme['label_de'])}</b> (<code>{theme_key}</code>)",
        parse_mode="HTML",
    )


def _artikel_enqueue_failure_text(outcome: dict, what: str) -> str:
    """Человеческий ответ, когда задача не встала в очередь. Сырое имя причины наружу
    не выносим — админу нужно понять, что делать, а не читать внутренний код."""
    reason = str((outcome or {}).get("reason") or "").strip()
    if reason == "already_running":
        return f"⏳ {what} уже идёт — дождись отчёта. Второй прогон не запускаю: это была бы двойная работа GPT."
    if reason == "background_jobs_unavailable":
        return (
            f"Очередь задач недоступна (нет Redis), {what.lower()} НЕ запущено.\n"
            "Прямо в боте больше не гоняю — это вешало бота на всё время прогона."
        )
    return f"Не смог поставить {what.lower()} в очередь, ничего не тронуто. Причина в логах."


async def admin_artikel_fill_command(update: Update, context: CallbackContext) -> None:
    """Наполнить тему словами. /artikel_fill <theme_key> [count]
    (count ограничивает, сколько НОВЫХ слов добавить за прогон; без него — до target).

    Работу делает BACKGROUND_JOBS, бот только ставит задачу в очередь и отвечает
    сразу. Раньше наполнение крутилось прямо в хендлере, и это стоило двух бед:
    PTB собран без concurrent_updates, поэтому на все минуты прогона бот переставал
    отвечать вообще всем; а деплой в это время убивал прогон молча — контейнер
    поднимается с drop_pending_updates=True, и от команды не оставалось следа.
    Результат прогона придёт отдельным сообщением, когда воркер закончит."""
    user = update.effective_user
    message = update.effective_message
    if not user or not message:
        return
    if not _can_use_image_quiz_test_commands(getattr(user, "id", None)):
        await message.reply_text("Allowed users only.")
        return
    args = [a.strip() for a in (context.args or []) if a.strip()]
    if not args:
        await message.reply_text("Использование: /artikel_fill <theme_key> [count]")
        return
    theme_key = args[0]
    try:
        count = max(1, min(300, int(args[1]))) if len(args) > 1 else None
    except ValueError:
        count = None
    theme = await asyncio.to_thread(get_article_sprint_theme, theme_key)
    if not theme:
        await message.reply_text(f"Нет темы <code>{html.escape(theme_key)}</code>. Список: /artikel_themes", parse_mode="HTML")
        return

    def _enqueue() -> dict:
        from backend.job_queue import enqueue_artikel_fill_job
        return enqueue_artikel_fill_job(
            theme_key=theme_key,
            max_to_add=count,
            chat_id=int(message.chat_id),
        )

    try:
        outcome = await asyncio.to_thread(_enqueue)
    except Exception:
        logging.exception("artikel_fill: enqueue failed theme=%s", theme_key)
        outcome = {"queued": False, "reason": "broker_error"}

    if outcome.get("queued"):
        await message.reply_text(
            f"📥 «{html.escape(theme['label_de'])}» встала в очередь на наполнение"
            + (f" (+{count})" if count else " (до target)") + ".\n"
            "Считает отдельный воркер — бот в это время работает как обычно, а "
            "деплой прогон не убьёт: он продолжится с того места, где прервался.\n"
            "Отчёт пришлю сюда, когда закончит."
        )
        return

    reason = str(outcome.get("reason") or "").strip()
    if reason == "already_running":
        await message.reply_text(
            f"⏳ «{html.escape(theme['label_de'])}» уже наполняется — дождись отчёта.\n"
            "Два прогона на одну тему не запускаю: они дублировали бы работу GPT."
        )
        return
    if reason == "background_jobs_unavailable":
        await message.reply_text(
            "Очередь задач недоступна (нет Redis), наполнение НЕ запущено.\n"
            "Прямо в боте его больше не гоняю — это вешало бота на всё время прогона."
        )
        return
    await message.reply_text(
        "Не смог поставить наполнение в очередь, слова не тронуты. Причина в логах "
        f"(<code>{html.escape(reason or 'unknown')}</code>).",
        parse_mode="HTML",
    )


def _parse_addword_line(line: str) -> dict | None:
    """Parse one pasted line into {word, article, meaning_ru}. Accepts:
    «der Hund», «Hund», «die Katze = кошка», «Haus - дом» (sep = / : / - / — with spaces)."""
    s = str(line or "").strip()
    if not s:
        return None
    meaning = ""
    m = re.split(r"\s+[=:—–-]\s+", s, maxsplit=1)
    if len(m) == 2:
        s, meaning = m[0].strip(), m[1].strip()
    toks = s.split()
    article = ""
    if toks and toks[0].lower() in ("der", "die", "das"):
        article = toks[0].lower()
        toks = toks[1:]
    word = " ".join(toks).strip()
    if not word:
        return None
    return {"word": word, "article": article, "meaning_ru": meaning}


async def admin_artikel_theme_add_command(update: Update, context: CallbackContext) -> None:
    """Создать новую тему тренажёра артиклей.

    /artikel_theme_add <ключ> | <название по-русски> | [название по-немецки] |
                       [подтемы через запятую] | [сколько слов]

    Подтемы нужны генератору: он просит слова по каждой подтеме отдельно, иначе
    получает сотню синонимов одного смысла. Цель по умолчанию 150 — намеренно меньше
    прежних 280: погоня за большим числом и наплодила производные одного корня."""
    user = update.effective_user
    message = update.effective_message
    if not user or not message:
        return
    if not _can_use_image_quiz_test_commands(getattr(user, "id", None)):
        await message.reply_text("Allowed users only.")
        return
    raw = str(message.text or "")
    body = raw.split(None, 1)[1].strip() if len(raw.split(None, 1)) > 1 else ""
    if not body:
        await message.reply_text(
            "Создать тему:\n"
            "<code>/artikel_theme_add auto_fahren | Автомобиль и вождение | "
            "Auto &amp; Fahren | двигатель, салон, дорога, ремонт | 150</code>\n\n"
            "Обязательны только ключ и русское название. Ключ — латиницей.",
            parse_mode="HTML")
        return
    parts = [p.strip() for p in body.split("|")]
    theme_key = parts[0] if parts else ""
    label_ru = parts[1] if len(parts) > 1 else ""
    label_de = parts[2] if len(parts) > 2 else ""
    subtopics = [x.strip() for x in (parts[3].split(",") if len(parts) > 3 else []) if x.strip()]
    try:
        target = int(parts[4]) if len(parts) > 4 and parts[4] else 150
    except ValueError:
        target = 150
    if not label_ru:
        await message.reply_text("Нужно русское название темы после ключа: <code>ключ | Название</code>",
                                 parse_mode="HTML")
        return
    try:
        result = await asyncio.to_thread(
            create_article_sprint_theme,
            theme_key=theme_key, label_ru=label_ru, label_de=label_de,
            subtopics=subtopics, target_count=target,
        )
    except Exception as exc:
        logging.exception("artikel_theme_add failed")
        await message.reply_text("Не получилось создать тему: %s" % str(exc)[:200])
        return
    await message.reply_text(
        "✅ Тема готова: <code>%s</code> — %s\n"
        "Цель: %d слов · подтем: %d · всего тем: %d\n\n"
        "Дальше: <code>/artikel_fill %s</code> — наполнить словами, "
        "или <code>/artikel_addwords %s</code> — добавить свои." % (
            result["theme_key"], result["label_ru"], result["target_count"],
            len(result["subtopics"]), result["themes_total"],
            result["theme_key"], result["theme_key"]),
        parse_mode="HTML")


