def _battle_kind_cfg(kind: str) -> dict:
    """Config for a sprint-battle type. Adjektiv DB helpers are imported lazily
    (they aren't in the module-level import block)."""
    if kind == "article":
        return {
            "list_to_close": list_article_sprint_battles_to_close,
            "set_id": lambda b: f"asb_{int(b['id'])}",
            "ranked": list_article_sprint_results_ranked,
            "members": list_article_sprint_battle_members,
            "close": close_article_sprint_battle,
            "header": "ЛУЧШИЙ АРТИКЛЕВЕД",
            "title": lambda bid: f"Artikel #{bid}",
            "caption_kind": "Батл",
        }
    if kind == "wofrage":
        from backend.database import (
            list_wofrage_sprint_battles_to_close, list_wofrage_sprint_results_ranked,
            list_wofrage_sprint_battle_members, close_wofrage_sprint_battle,
        )
        return {
            "list_to_close": list_wofrage_sprint_battles_to_close,
            "set_id": lambda b: str(b["set_id"]),
            "ranked": list_wofrage_sprint_results_ranked,
            "members": list_wofrage_sprint_battle_members,
            "close": close_wofrage_sprint_battle,
            "header": "WO-FRAGE-MEISTER",
            "title": lambda bid: f"Wo-Frage #{bid}",
            "caption_kind": "Wo-Frage-батл",
        }
    from backend.database import (
        list_adjektiv_sprint_battles_to_close, list_adjektiv_sprint_results_ranked,
        list_adjektiv_sprint_battle_members, close_adjektiv_sprint_battle,
    )
    return {
        "list_to_close": list_adjektiv_sprint_battles_to_close,
        "set_id": lambda b: str(b["set_id"]),
        "ranked": list_adjektiv_sprint_results_ranked,
        "members": list_adjektiv_sprint_battle_members,
        "close": close_adjektiv_sprint_battle,
        "header": "ADJEKTIV-MEISTER",
        "title": lambda bid: f"Adjektiv #{bid}",
        "caption_kind": "Adjektiv-батл",
    }


async def _render_battle_podium(context: CallbackContext, ranked: list, *, header: str, bid: int) -> bytes | None:
    """Render the rich top-3 podium poster for one battle (or None if no players)."""
    if not ranked:
        return None
    leaders = [{
        "user_id": int(r["user_id"]), "name": str(r.get("name") or "Игрок"),
        "points": int(r.get("count") or 0), "correct": int(r.get("count") or 0),
        "answered": int(r.get("count") or 0), "golds": (1 if i == 0 else 0),
        "ctime_sum": 0, "ctime_n": 0,
    } for i, r in enumerate(ranked)]
    lb = {"leaders": leaders, "total_players": len(leaders), "total_tasks": 0,
          "fastest": None, "accurate": None, "active": None}
    avatars: dict[int, bytes] = {}
    for ldr in leaders[:3]:
        av = await _fetch_user_avatar_png(context, int(ldr["user_id"]))
        if av:
            avatars[int(ldr["user_id"])] = av
    try:
        from backend.champion_poster import render_champion_poster
        from backend.battle_card import REMINDER_KEY
        from backend.r2_storage import r2_get_bytes
        hero = await asyncio.to_thread(r2_get_bytes, REMINDER_KEY)
        return await asyncio.to_thread(
            render_champion_poster, lb, week_no=0, days=1, avatars=avatars,
            header=header, subtitle=f"⚔️ Батл #{bid}", hero_png=hero)
    except Exception:
        logging.warning("battle podium render failed bid=%s", bid, exc_info=True)
        return None


async def _collect_battle_results(context: CallbackContext, kind: str) -> list:
    """Fetch every to-close battle of `kind`, render its podium, and return one
    dict per battle (ranked/members/poster). Does NOT send or close anything."""
    cfg = _battle_kind_cfg(kind)
    try:
        battles = await asyncio.to_thread(cfg["list_to_close"])
    except Exception:
        logging.warning("%s battle close: list failed", kind, exc_info=True)
        return []
    out = []
    for b in battles:
        bid = int(b["id"])
        set_id = cfg["set_id"](b)
        try:
            ranked = await asyncio.to_thread(cfg["ranked"], set_id)
            members = await asyncio.to_thread(cfg["members"], bid)
        except Exception:
            logging.warning("%s battle close: data failed bid=%s", kind, bid, exc_info=True)
            continue
        poster = await _render_battle_podium(context, ranked, header=cfg["header"], bid=bid)
        out.append({
            "kind": kind, "bid": bid, "set_id": set_id, "ranked": ranked, "members": members,
            "poster": poster, "title": cfg["title"](bid), "caption_kind": cfg["caption_kind"],
            "close": cfg["close"],
        })
    return out


async def _send_single_battle_result(context: CallbackContext, uid: int, e: dict) -> None:
    """Deliver one battle result to a user (unchanged look: rich podium + caption)."""
    p, total, ck, bid = e["place"], e["total"], e["caption_kind"], e["bid"]
    win_line = (f"🏆 Чемпион: {html.escape(e['win_name'])} ({e['win_count']} верных)"
                if e["win_name"] and e["win_name"] != "—" else "Никто не сыграл.")
    if p:
        medal = {1: "🥇", 2: "🥈", 3: "🥉"}.get(p, "🎖️")
        caption = (f"⚔️ {ck} #{bid} завершён!\n"
                   f"{medal} Твоё место: <b>{p} из {total}</b> ({e['count']} верных)")
    else:
        caption = f"⚔️ {ck} #{bid} завершён — ты не успел сыграть 😔\n{win_line}"
    if e["poster"]:
        sent = await context.bot.send_photo(chat_id=uid, photo=io.BytesIO(e["poster"]),
                                            caption=caption, parse_mode="HTML")
        await _preserve_system_message(sent, "battle_podium")
    else:
        await context.bot.send_message(chat_id=uid, text=caption + ("\n" + win_line if p else ""),
                                       parse_mode="HTML")


async def _send_battle_digest(context: CallbackContext, uid: int, entries: list) -> None:
    """Deliver ALL of a user's battle results as one combined «Итоги батлов» card."""
    entries = sorted(entries, key=lambda e: (e["place"] is None, e["place"] or 10**9, e["bid"]))
    played = sum(1 for e in entries if e["place"])
    wins = sum(1 for e in entries if e["place"] == 1)
    img = None
    try:
        from backend.battle_digest_poster import render_battle_digest
        from backend.battle_card import REMINDER_KEY
        from backend.r2_storage import r2_get_bytes
        hero = await asyncio.to_thread(r2_get_bytes, REMINDER_KEY)
        img = await asyncio.to_thread(
            render_battle_digest, entries, hero_png=hero, subtitle=f"{len(entries)} батлов")
    except Exception:
        logging.warning("battle digest render failed uid=%s", uid, exc_info=True)
        img = None
    caption = f"⚔️ Итоги батлов: сыграно {played} из {len(entries)}"
    if wins:
        caption += f", побед {wins} 🏆"
    if img:
        sent = await context.bot.send_photo(chat_id=uid, photo=io.BytesIO(img),
                                            caption=caption, parse_mode="HTML")
        await _preserve_system_message(sent, "battle_podium")
    else:
        lines = [caption]
        for e in entries:
            if e["place"]:
                medal = {1: "🥇", 2: "🥈", 3: "🥉"}.get(e["place"], "🎖️")
                lines.append(f"{medal} {e['title']}: {e['place']} из {e['total']} ({e['count']} верных)")
            else:
                lines.append(f"▫️ {e['title']}: не сыграл")
        await context.bot.send_message(chat_id=uid, text="\n".join(lines), parse_mode="HTML")


async def _flush_battle_results(context: CallbackContext, results: list) -> None:
    """Group all battle results per user, then send ONE combined digest card when a
    user has 2+ battles (else the single rich podium). Finally unpin + mark closed."""
    per_user: dict[int, list] = {}
    for r in results:
        ranked, members = r["ranked"], r["members"]
        place_of = {int(x["user_id"]): i + 1 for i, x in enumerate(ranked)}
        winner = ranked[0] if ranked else None
        win_name = str((winner or {}).get("name") or "—")
        win_count = int((winner or {}).get("count") or 0)
        total = len(ranked)
        for m in members:
            uid = int(m["user_id"])
            you = next((x for x in ranked if int(x["user_id"]) == uid), {})
            per_user.setdefault(uid, []).append({
                "kind": r["kind"], "bid": r["bid"], "title": r["title"],
                "caption_kind": r["caption_kind"], "poster": r["poster"],
                "place": place_of.get(uid), "total": total, "count": int(you.get("count") or 0),
                "is_win": place_of.get(uid) == 1, "win_name": win_name, "win_count": win_count,
            })

    for uid, entries in per_user.items():
        try:
            if len(entries) == 1:
                await _send_single_battle_result(context, uid, entries[0])
            else:
                await _send_battle_digest(context, uid, entries)
        except Exception:
            pass

    for r in results:
        await _unpin_battle_pins_for_set(context, r["set_id"])
        try:
            await asyncio.to_thread(r["close"], r["bid"])
        except Exception:
            logging.warning("%s battle close: mark failed bid=%s", r["kind"], r["bid"], exc_info=True)


async def _close_all_sprint_battles_job(context: CallbackContext) -> None:
    """Close all expired Artikel + Adjektiv battles and deliver results — merged into
    a single «Итоги батлов» card per user so a heavy battle day isn't a photo spam."""
    results = await _collect_battle_results(context, "article")
    results += await _collect_battle_results(context, "adjektiv")
    results += await _collect_battle_results(context, "wofrage")
    await _flush_battle_results(context, results)
    if results:
        logging.info("sprint battles closed: %s (article+adjektiv+wofrage, merged per user)", len(results))


async def _close_article_sprint_battles_job(context: CallbackContext) -> None:
    """Close only Artikel battles (kept for manual/standalone use)."""
    results = await _collect_battle_results(context, "article")
    await _flush_battle_results(context, results)
    if results:
        logging.info("artikel battles closed: %s", len(results))


# ─────────────────────────────────────────────────────────────
#  ARTICLE QUIZ (der/die/das) — send, callback, scheduler
# ─────────────────────────────────────────────────────────────

_ARTICLE_BUTTONS = [
    ("🔵 der", "der"),
    ("🔴 die", "die"),
    ("⚪ das", "das"),
]


def _build_article_quiz_caption(entry: dict) -> str:
    word = str(entry.get("word") or "")
    meaning = str(entry.get("meaning_ru") or "")
    lines = [
        "🎯 *Welcher Artikel?*",
        "",
        f"*{word}*",
        f"_({meaning})_" if meaning else "",
        "",
        "Wähle den richtigen Artikel! 👇",
    ]
    return "\n".join(l for l in lines if l is not None)


def _build_article_quiz_keyboard(dispatch_id: int) -> InlineKeyboardMarkup:
    row = [
        InlineKeyboardButton(label, callback_data=f"aq:{dispatch_id}:{article}")
        for label, article in _ARTICLE_BUTTONS
    ]
    return InlineKeyboardMarkup([row])


async def send_article_quiz_to_chat(
    context: CallbackContext,
    *,
    entry: dict,
    image_url: str,
    slot_date,
    slot_hour: int,
    chat_id: int,
    target_user_id: int,
) -> bool:
    """Send one article quiz card to a chat. Returns True on success."""
    word_id = str(entry.get("word_id") or "")

    try:
        dispatch_id = await asyncio.to_thread(
            record_article_quiz_dispatch,
            slot_date=slot_date,
            slot_hour=int(slot_hour),
            word_id=word_id,
            target_user_id=int(target_user_id),
            chat_id=int(chat_id),
            telegram_message_id=None,
            status="sent",
        )
    except Exception:
        logging.warning(
            "aq_send: dispatch insert failed word_id=%s chat_id=%s slot=%s/%s",
            word_id, chat_id, slot_date, slot_hour, exc_info=True,
        )
        return False

    if dispatch_id is None:
        logging.info(
            "aq_send: duplicate suppressed word_id=%s chat_id=%s slot=%s/%s",
            word_id, chat_id, slot_date, slot_hour,
        )
        return False

    caption = _build_article_quiz_caption(entry)
    caption = _append_free_pro_teaser(caption, chat_id)
    keyboard = _build_article_quiz_keyboard(dispatch_id)

    logging.info(
        "aq_send_begin dispatch_id=%s word_id=%s chat_id=%s slot=%s/%s",
        dispatch_id, word_id, chat_id, slot_date, slot_hour,
    )

    try:
        photo_message = await context.bot.send_photo(
            chat_id=int(chat_id),
            photo=image_url,
            caption=caption,
            reply_markup=keyboard,
            parse_mode="Markdown",
        )
    except Exception as exc:
        logging.warning("aq_send_failed dispatch_id=%s chat_id=%s: %s", dispatch_id, chat_id, exc)
        return False

    try:
        await asyncio.to_thread(
            update_article_quiz_dispatch_telegram_id,
            dispatch_id,
            telegram_message_id=int(photo_message.message_id),
        )
    except Exception:
        logging.warning("aq_send: update telegram_id failed dispatch_id=%s", dispatch_id, exc_info=True)

    # Ведомость дня: артикль-квиз тоже занимает один из дневных слотов, поэтому факт
    # выдачи записываем — иначе «Следующее задание» посчитает слот свободным и выдаст
    # лишнее. Отвечают на квиз кнопками прямо в чате, Mini-App-экрана у него нет, так
    # что ссылки нет: строка только считается, в списке «что открыть» не показывается.
    if int(chat_id) == int(target_user_id):  # DM feed only
        try:
            await asyncio.to_thread(
                record_interactive_inbox,
                user_id=int(target_user_id), kind="aq", dispatch_id=int(dispatch_id),
                chat_id=int(chat_id), telegram_message_id=int(photo_message.message_id),
                deeplink="", title="🧩 Артикль-квиз",
                keyboard_json=_inbox_kb_json(keyboard),
            )
        except Exception:
            logging.warning("aq_send: inbox record failed dispatch_id=%s", dispatch_id, exc_info=True)

    logging.info("aq_send_ok dispatch_id=%s word_id=%s chat_id=%s", dispatch_id, word_id, chat_id)
    return True


async def _send_scheduled_article_quiz(context: CallbackContext) -> None:
    if _is_quiet_hours_now():
        logging.info("quiet_hours: skip article_quiz")
        return
    if not _article_quiz_enabled():
        logging.info("aq_slot_triggered enabled=False — skipping")
        return

    slot_now = _get_quiz_schedule_now()
    slot_date = slot_now.date()
    slot_hour = int(slot_now.hour) * 100 + int(slot_now.minute)  # unique: e.g. 915, 1315, 1715

    logging.info("aq_slot_triggered slot=%s/%s", slot_date, slot_hour)

    # Slot → card kind: the 3 original slots send DALL·E photos (13:15 stays the
    # hard B2 photo slot); the 2 added slots (10:15, 18:15) send the new grammar
    # text cards. pick_next falls back to any kind if the requested one is empty.
    slot_key = (slot_now.hour, slot_now.minute)
    _AQ_GRAMMAR_SLOTS = {(10, 15), (18, 15)}
    if slot_key in _AQ_GRAMMAR_SLOTS:
        card_kind = "grammar"
        difficulty_hint = None
    else:
        card_kind = "photo"
        difficulty_hint = "B2" if slot_key == (13, 15) else None

    try:
        entry = await asyncio.to_thread(
            pick_next_article_quiz,
            cooldown_days=ARTICLE_QUIZ_COOLDOWN_DAYS,
            difficulty_filter=difficulty_hint,
            card_kind=card_kind,
        )
    except Exception:
        logging.warning("aq_slot: pick_next_article_quiz failed", exc_info=True)
        entry = None

    if not entry:
        logging.warning("aq_slot: pool exhausted slot=%s/%s", slot_date, slot_hour)
        return

    word_id = str(entry.get("word_id") or "")
    object_key = str(entry.get("image_object_key") or "")
    if not object_key:
        logging.warning("aq_slot: no image key word_id=%s", word_id)
        return

    try:
        image_url = r2_public_url(object_key)
    except Exception:
        logging.warning("aq_slot: r2_public_url failed key=%s", object_key, exc_info=True)
        return

    delivery_targets = await _collect_quiz_delivery_user_targets(context)
    if not delivery_targets:
        logging.info("aq_slot: no delivery targets word_id=%s", word_id)
        return

    sent = 0
    for target in delivery_targets:
        target_chat_id = int(target.get("chat_id") or 0)
        if target_chat_id == 0:
            continue
        ok = await send_article_quiz_to_chat(
            context,
            entry=entry,
            image_url=image_url,
            slot_date=slot_date,
            slot_hour=slot_hour,
            chat_id=target_chat_id,
            target_user_id=target_chat_id,
        )
        if ok:
            sent += 1

    if sent > 0:
        try:
            await asyncio.to_thread(mark_article_quiz_sent, word_id)
        except Exception:
            logging.warning("aq_slot: mark_article_quiz_sent failed word_id=%s", word_id, exc_info=True)

    logging.info("aq_slot_done slot=%s/%s word_id=%s sent=%s", slot_date, slot_hour, word_id, sent)

    # Trigger pool top-up if running low
    try:
        available = await asyncio.to_thread(
            count_available_article_quiz_entries, cooldown_days=ARTICLE_QUIZ_COOLDOWN_DAYS
        )
        if available < ARTICLE_QUIZ_POOL_TOPUP_TRIGGER:
            logging.info("aq_pool_low available=%s — triggering top-up", available)
            from backend.article_quiz_generator import prepare_article_quiz_pool
            await asyncio.to_thread(prepare_article_quiz_pool, target_ready=ARTICLE_QUIZ_POOL_TARGET)
    except Exception:
        logging.warning("aq_slot: pool top-up check failed", exc_info=True)


async def handle_article_quiz_callback(update: Update, context: CallbackContext) -> None:
    query = update.callback_query
    user = update.effective_user
    if not query or not user:
        return
    raw_data = str(query.data or "").strip()
    match = re.match(r"^aq:(\d+):(der|die|das)$", raw_data)
    if not match:
        await query.answer("Quiz nicht verfügbar.")
        return

    dispatch_id = int(match.group(1))
    selected_article = match.group(2).lower()

    try:
        dispatch = await asyncio.to_thread(get_article_quiz_dispatch_by_id, dispatch_id)
    except Exception:
        logging.warning("aq_callback: dispatch lookup failed id=%s", dispatch_id, exc_info=True)
        dispatch = None
    if not dispatch:
        await query.answer("Quiz nicht verfügbar.")
        return

    word_id = str(dispatch.get("word_id") or "")
    try:
        entry = await asyncio.to_thread(get_article_quiz_entry, word_id)
    except Exception:
        logging.warning("aq_callback: entry lookup failed word_id=%s", word_id, exc_info=True)
        entry = None
    if not entry:
        await query.answer("Quiz nicht verfügbar.")
        return

    correct_article = str(entry.get("article") or "").lower()
    word = str(entry.get("word") or "")
    meaning = str(entry.get("meaning_ru") or "")
    is_correct = selected_article == correct_article

    try:
        await asyncio.to_thread(
            record_article_quiz_answer,
            dispatch_id=dispatch_id,
            user_id=int(user.id),
            selected_article=selected_article,
            is_correct=bool(is_correct),
        )
    except Exception:
        logging.warning(
            "aq_callback: record_answer failed dispatch_id=%s user_id=%s",
            dispatch_id, int(user.id), exc_info=True,
        )

    # Ответил — закрываем строку в ведомости дня, чтобы квиз не висел
    # в «не сделано за сегодня».
    try:
        await asyncio.to_thread(
            mark_interactive_inbox_answered,
            user_id=int(user.id), kind="aq", dispatch_id=int(dispatch_id),
        )
    except Exception:
        logging.warning("aq_callback: inbox close failed dispatch_id=%s", dispatch_id, exc_info=True)

    if is_correct:
        icon = "✅"
        verdict = f"Richtig! {correct_article} {word}"
    else:
        icon = "❌"
        verdict = f"Falsch. Es ist {correct_article} {word}"

    # In-place popup: verdict + a pre-generated grammar hint (ending → gender +
    # exceptions). Hint is read from the bank (no LLM call here — kept off the
    # critical path). Telegram alert text is capped at 200 chars.
    gender_hint = str(entry.get("gender_hint") or "").strip()
    header = f"{icon} {verdict}"
    if gender_hint:
        alert_text = f"{header}\n\n{gender_hint}"
    else:
        detail = f" ({meaning})" if meaning else ""
        alert_text = f"{header}{detail}"

    try:
        await query.answer(alert_text[:200], show_alert=True)
    except Exception:
        logging.warning("aq_callback: answer alert failed dispatch_id=%s", dispatch_id, exc_info=True)

    try:
        await asyncio.to_thread(
            mark_article_quiz_answer_feedback_sent,
            dispatch_id=dispatch_id,
            user_id=int(user.id),
        )
    except Exception:
        logging.warning("aq_callback: mark_feedback_sent failed dispatch_id=%s", dispatch_id, exc_info=True)


async def prepare_article_quiz_pool_job(context: CallbackContext) -> None:
    """Startup + periodic: sync bank and generate missing images."""
    try:
        from backend.article_quiz_generator import (
            prepare_article_quiz_pool,
            backfill_article_gender_hints,
        )
        result = await asyncio.to_thread(
            prepare_article_quiz_pool,
            target_ready=ARTICLE_QUIZ_POOL_TARGET,
            max_attempts=40,
        )
        logging.info("article_quiz_pool_job done: %s", result)
        # Off critical path: fill the der/die/das grammar hints used in the
        # answer popup, so tapping never triggers an LLM call.
        hint_result = await backfill_article_gender_hints(limit=50)
        logging.info("article_quiz_hint_backfill done: %s", hint_result)
    except Exception:
        logging.warning("article_quiz_pool_job failed", exc_info=True)


async def admin_article_quiz_send_command(update: Update, context: CallbackContext) -> None:
    """Send an article quiz to this chat immediately (admin test)."""
    user = update.effective_user
    chat = update.effective_chat
    message = update.effective_message
    if not user or not chat or not message:
        return
    if not _can_use_image_quiz_test_commands(getattr(user, "id", None)):
        await message.reply_text("Allowed users only.")
        return

    status_msg = await message.reply_text("Preparing article quiz...")

    try:
        entry = await asyncio.to_thread(pick_next_article_quiz, cooldown_days=0)
    except Exception as exc:
        await status_msg.edit_text(f"pick_next_article_quiz failed: {exc}")
        return

    if not entry:
        await status_msg.edit_text("No ready article quiz found. Run /admin_aq_pool first.")
        return

    object_key = str(entry.get("image_object_key") or "")
    if not object_key:
        await status_msg.edit_text(f"No image yet for {entry.get('word')}. Run /admin_aq_pool.")
        return

    try:
        image_url = r2_public_url(object_key)
    except Exception as exc:
        await status_msg.edit_text(f"r2_public_url failed: {exc}")
        return

    slot_now = _get_quiz_schedule_now()
    ok = await send_article_quiz_to_chat(
        context,
        entry=entry,
        image_url=image_url,
        slot_date=slot_now.date(),
        slot_hour=int(slot_now.hour) * 10000 + int(slot_now.second),  # unique test slot
        chat_id=int(chat.id),
        target_user_id=int(user.id),
    )
    if ok:
        await status_msg.delete()
    else:
        await status_msg.edit_text("Article quiz send failed — check logs.")


async def admin_article_quiz_pool_command(update: Update, context: CallbackContext) -> None:
    """Trigger article quiz pool preparation. /admin_aq_pool [target]"""
    user = update.effective_user
    message = update.effective_message
    if not user or not message:
        return
    if not _can_use_image_quiz_test_commands(getattr(user, "id", None)):
        await message.reply_text("Allowed users only.")
        return
    # Optional numeric argument overrides the pool target
    args = (context.args or [])
    try:
        target = max(10, int(args[0])) if args else ARTICLE_QUIZ_POOL_TARGET
    except (ValueError, IndexError):
        target = ARTICLE_QUIZ_POOL_TARGET
    status_msg = await message.reply_text(f"Preparing article quiz pool (target={target})...")
    try:
        from backend.article_quiz_generator import prepare_article_quiz_pool
        result = await asyncio.to_thread(
            prepare_article_quiz_pool,
            target_ready=target,
            max_attempts=max(40, target),
        )
        await status_msg.edit_text(f"Article quiz pool done:\n{result}")
    except Exception as exc:
        await status_msg.edit_text(f"Error: {exc}")


def _slug_article_word(word: str, article: str) -> str:
    base = "".join(c if (c.isalnum() or c in "-_") else "_" for c in word.lower())
    return f"adm_{base}_{article}"


async def admin_add_artikel_command(update: Update, context: CallbackContext) -> None:
    """Add a word to the article-quiz queue as a rendered grammar card.

    Usage:  /addartikel <der|die|das> <Wort> [| значение [| пояснение]]
    Examples:
      /addartikel der Gedanke | мысль | -e на конце, но род мужской
      /addartikel das Verständnis
    """
    user = update.effective_user
    message = update.effective_message
    if not user or not message:
        return
    if not _can_use_image_quiz_test_commands(getattr(user, "id", None)):
        await message.reply_text("Allowed users only.")
        return

    raw = (message.text or "")
    # strip the "/addartikel" (and optional @botname) token
    raw = re.sub(r"^/\S+\s*", "", raw, count=1).strip()
    if not raw:
        await message.reply_text(
            "Использование:\n"
            "`/addartikel der Gedanke | мысль | -e на конце, но мужской`\n\n"
            "Минимум: `/addartikel der Gedanke`\n"
            "Формат: `<der|die|das> <Слово> | значение | пояснение`",
            parse_mode="Markdown",
        )
        return

    parts = [p.strip() for p in raw.split("|")]
    head = parts[0].split()
    if len(head) < 2 or head[0].lower() not in ("der", "die", "das"):
        await message.reply_text(
            "Не понял. Начни с артикля и слова:\n"
            "`/addartikel der Gedanke | мысль | -e, но мужской`",
            parse_mode="Markdown",
        )
        return

    article = head[0].lower()
    word = " ".join(head[1:]).strip()
    meaning = parts[1] if len(parts) > 1 else ""
    hint = parts[2] if len(parts) > 2 else ""

    entry = {
        "id": _slug_article_word(word, article),
        "word": word,
        "article": article,
        "meaning_ru": meaning,
        "gender_hint": hint,
        "difficulty": "B2",
        "category": "Grammatik",
    }

    status_msg = await message.reply_text(f"⏳ Добавляю {article} {word}…")
    try:
        written = await asyncio.to_thread(upsert_article_quiz_text_entry, entry)
    except Exception as exc:
        await status_msg.edit_text(f"Ошибка записи: {exc}")
        return
    if not written:
        await status_msg.edit_text(
            f"⚠️ «{word}» уже есть в банке как картиночное слово — пропустил, "
            "чтобы не дублировать."
        )
        return

    # Render its card now so it's immediately available in the rotation.
    card_ok = True
    try:
        from backend.article_quiz_card import generate_article_quiz_card
        await asyncio.to_thread(generate_article_quiz_card, entry["id"])
    except Exception:
        card_ok = False
        logging.warning("addartikel: card render failed id=%s", entry["id"], exc_info=True)

    tail = "" if hint else "\n_(пояснение пустое — допишется автоматически ночью)_"
    card_note = "" if card_ok else "\n⚠️ карточка не отрисовалась — проверь логи / попробуй /admin_aq_pool"
    await status_msg.edit_text(
        f"✅ Добавлено в очередь: *{article} {word}*"
        + (f"\n_{meaning}_" if meaning else "")
        + tail + card_note,
        parse_mode="Markdown",
    )


# ══════════════════════════════════════════════════════════════════════════════
# CROSSWORD
# ══════════════════════════════════════════════════════════════════════════════

def _crosswords_enabled() -> bool:
    return (os.getenv("CROSSWORDS_ENABLED") or "true").strip().lower() not in ("0", "false", "no")


def _crosswords_dry_run() -> bool:
    return (os.getenv("CROSSWORDS_DRY_RUN") or "false").strip().lower() in ("1", "true", "yes")


def _is_crossword_slot(slot_dt) -> bool:
    return (slot_dt.hour, slot_dt.minute) in CROSSWORD_SLOT_TIMES


def _build_crossword_caption(words_json: list, topic: str, difficulty: str) -> str:
    # Fairness: the clues are intentionally NOT included in the group message.
    # Everyone sees the questions only after tapping ✏️ Antworten (inside the
    # Mini App, where the timer starts) — so nobody can pre-solve from the chat
    # and then just type answers in. Same starting conditions for all players.
    hidden = [w for w in words_json if w.get("hidden")]
    n = len(hidden)

    lines = [f"🧩 *Kreuzworträtsel* — {topic} ({difficulty})", ""]
    lines.append(f"Es fehlen {n} Wörter im Gitter." if n else "Fülle das Gitter aus.")
    lines.append("Tippe auf ✏️ *Antworten* — dort siehst du die Fragen und füllst die leeren Felder aus. 👇")
    return "\n".join(lines)


def _build_crossword_keyboard(dispatch_id: int, words_json: list) -> InlineKeyboardMarkup:
    """Single ✏️ button → Mini App overlay (answer all words in place, no DM).

    The cw:start callback + free-text handler stay wired (via the shared
    answer_eval) as an under-the-hood fallback.
    """
    btn = InlineKeyboardButton(
        text="🧩 Antworten",
        url=get_webapp_deeplink(f"ans_cw_{dispatch_id}"),
    )
    return InlineKeyboardMarkup([[btn]])


async def send_crossword_to_chat(
    context: CallbackContext,
    *,
    crossword_entry: dict,
    image_url: str,
    slot_date,
    slot_hour: int,
    chat_id: int,
    target_user_id: int,
    held: bool = False,
) -> bool:
    """Send one crossword card to a chat. Returns True on success."""
    crossword_id = str(crossword_entry.get("crossword_id") or "")
    words_json   = list(crossword_entry.get("words_json") or [])
    topic        = str(crossword_entry.get("topic") or "")
    difficulty   = str(crossword_entry.get("difficulty") or "")

    try:
        dispatch_id = await asyncio.to_thread(
            record_crossword_dispatch,
            slot_date=slot_date,
            slot_hour=int(slot_hour),
            crossword_id=crossword_id,
            target_user_id=int(target_user_id),
            chat_id=int(chat_id),
        )
    except Exception:
        logging.warning(
            "cw_send: dispatch insert failed crossword_id=%s chat_id=%s slot=%s/%s",
            crossword_id, chat_id, slot_date, slot_hour, exc_info=True,
        )
        return False

    if not dispatch_id:
        logging.info(
            "cw_send: duplicate suppressed crossword_id=%s chat_id=%s slot=%s/%s",
            crossword_id, chat_id, slot_date, slot_hour,
        )
        return False

    if held and int(chat_id) == int(target_user_id):  # Этап 3f: record, don't send
        await asyncio.to_thread(
            record_interactive_inbox, user_id=int(target_user_id), kind="cw",
            dispatch_id=int(dispatch_id), chat_id=int(chat_id),
            deeplink=f"ans_cw_{dispatch_id}", title="🔤 Kreuzwort", pushed=False)
        logging.info("held kind=cw dispatch_id=%s user=%s", dispatch_id, target_user_id)
        return True

    caption  = _build_crossword_caption(words_json, topic, difficulty)
    caption  = _append_free_pro_teaser(caption, chat_id)
    keyboard = _build_crossword_keyboard(dispatch_id, words_json)

    logging.info(
        "cw_send_begin dispatch_id=%s crossword_id=%s chat_id=%s slot=%s/%s",
        dispatch_id, crossword_id, chat_id, slot_date, slot_hour,
    )

    if _crosswords_dry_run():
        logging.info("cw_dry_run_skipped dispatch_id=%s chat_id=%s", dispatch_id, chat_id)
        return True

    try:
        msg = await context.bot.send_photo(
            chat_id=int(chat_id),
            photo=image_url,
            caption=caption,
            reply_markup=keyboard,
            parse_mode="Markdown",
        )
    except Exception as exc:
        logging.warning("cw_send_failed dispatch_id=%s chat_id=%s: %s", dispatch_id, chat_id, exc)
        return False

    try:
        await asyncio.to_thread(
            update_crossword_dispatch_telegram_id,
            dispatch_id,
            telegram_message_id=int(msg.message_id),
        )
    except Exception:
        logging.warning(
            "cw_send: update telegram_id failed dispatch_id=%s", dispatch_id, exc_info=True,
        )

    if int(chat_id) == int(target_user_id):  # DM feed only
        try:
            await asyncio.to_thread(
                record_interactive_inbox,
                user_id=int(target_user_id), kind="cw", dispatch_id=int(dispatch_id),
                chat_id=int(chat_id), telegram_message_id=int(msg.message_id),
                deeplink=f"ans_cw_{dispatch_id}", title="🔤 Kreuzwort",
                keyboard_json=_inbox_kb_json(keyboard),
            )
        except Exception:
            logging.debug("cw_send: inbox record failed dispatch_id=%s", dispatch_id, exc_info=True)

    logging.info("cw_send_ok dispatch_id=%s crossword_id=%s chat_id=%s", dispatch_id, crossword_id, chat_id)
    return True


async def _send_scheduled_crossword(context: CallbackContext) -> None:
    if _is_quiet_hours_now():
        logging.info("quiet_hours: skip crossword")
        return
    if not _crosswords_enabled():
        logging.info("cw_slot_triggered enabled=False — skipping")
        return

    slot_now  = _get_quiz_schedule_now()
    slot_date = slot_now.date()
    slot_hour = slot_now.hour

    if not _is_crossword_slot(slot_now):
        return

    try:
        # Prefer a card past its cooldown; if the whole ready-pool is still in
        # cooldown, fall back to cooldown=0 (least-recently-seen first) so we NEVER
        # go dark — an occasional early repeat beats a silent blackout. Mirrors the
        # per-user delivery path.
        entry = (await asyncio.to_thread(pick_next_crossword, cooldown_days=CROSSWORD_COOLDOWN_DAYS)
                 or await asyncio.to_thread(pick_next_crossword, cooldown_days=0))
    except Exception:
        logging.warning("cw_slot: pick_next_crossword failed", exc_info=True)
        return

    if not entry:
        logging.info("cw_slot: no ready crossword available slot=%s/%s", slot_date, slot_hour)
        return

    crossword_id = str(entry.get("crossword_id") or "")
    object_key   = str(entry.get("image_object_key") or "")
    if not object_key:
        logging.warning("cw_slot: no image key crossword_id=%s", crossword_id)
        return

    try:
        image_url = r2_public_url(object_key)
    except Exception:
        logging.warning("cw_slot: r2_public_url failed key=%s", object_key, exc_info=True)
        return

    delivery_targets = await _collect_quiz_delivery_user_targets(context)
    if not delivery_targets:
        logging.info("cw_slot: no delivery targets crossword_id=%s", crossword_id)
        return

    sent = 0
    for target in delivery_targets:
        target_chat_id = int(target.get("chat_id") or 0)
        if target_chat_id == 0:
            continue
        ok = await send_crossword_to_chat(
            context,
            crossword_entry=entry,
            image_url=image_url,
            slot_date=slot_date,
            slot_hour=slot_hour,
            chat_id=target_chat_id,
            target_user_id=target_chat_id,
            held=bool(target.get("held")),
        )
        if ok:
            sent += 1

    if sent > 0:
        try:
            await asyncio.to_thread(mark_crossword_sent, crossword_id)
        except Exception:
            logging.warning("cw_slot: mark_crossword_sent failed crossword_id=%s", crossword_id, exc_info=True)
    else:
        # Zero recipients (e.g. a broken image → send_photo fails for everyone).
        # Advance rotation + auto-retire after repeated failures so one bad entry
        # can't monopolize the queue forever (it has the oldest last_sent_at).
        logging.warning(
            "cw_slot: zero recipients — advancing rotation crossword_id=%s slot=%s/%s",
            crossword_id, slot_date, slot_hour,
        )
        try:
            # retire_after=8 (not 3): a transient R2/image blip can zero-send several
            # slots in a row for a perfectly good puzzle — a wider margin stops those
            # blips from silently draining the pool into the retired graveyard.
            await asyncio.to_thread(mark_crossword_send_failed, crossword_id, retire_after=8)
        except Exception:
            logging.warning("cw_slot: mark_crossword_send_failed failed crossword_id=%s", crossword_id, exc_info=True)
        await _alert_admin_interactive(
            context,
            f"⚠️ <b>Kreuzwort: отправка не удалась</b> (0 доставлено, возможно битая картинка) "
            f"crossword_id={crossword_id}, слот {slot_date} {slot_hour}:00.",
            throttle_key="cw_send_fail",
        )

    logging.info(
        "cw_slot_done slot=%s/%s crossword_id=%s sent=%d",
        slot_date, slot_hour, crossword_id, sent,
    )


async def handle_crossword_callback(update: Update, context: CallbackContext) -> None:
    """Handle ✏️ Antworten tap — prompt user to type all hidden words in one message."""
    query = update.callback_query
    if not query:
        return
    user = query.from_user
    if not user:
        return

    # callback_data format: cw:start:{dispatch_id}
    parts = (query.data or "").split(":", 2)
    if len(parts) != 3 or parts[1] != "start":
        await query.answer()
        return

    try:
        dispatch_id = int(parts[2])
    except ValueError:
        await query.answer()
        return

    try:
        dispatch = await asyncio.to_thread(get_crossword_dispatch_by_id, dispatch_id)
    except Exception:
        logging.warning("cw_callback: dispatch lookup failed id=%s", dispatch_id, exc_info=True)
        await query.answer("Fehler. Bitte versuche es erneut.")
        return

    if not dispatch:
        await query.answer("Rätsel nicht gefunden.")
        return

    words_json = list(dispatch.get("words_json") or [])
    hidden = sorted([w for w in words_json if w.get("hidden")], key=lambda x: x["number"])
    if not hidden:
        await query.answer()
        return

    from backend.crossword_renderer import build_word_pattern

    # Build compact instruction showing all hidden words with their patterns
    word_lines = []
    hidden_info = []
    for w in hidden:
        num = w["number"]
        arrow = "↔" if w.get("direction") == "across" else "↕"
        correct = str(w.get("word") or "")
        pattern = build_word_pattern(correct)
        clue_de = str(w.get("clue_de") or "")
        word_lines.append(f"*{num}{arrow}* `{pattern}` — _{clue_de}_")
        hidden_info.append({
            "number": num,
            "word": correct,
            "direction": w.get("direction", "across"),
            "clue_de": clue_de,
            "clue_ru": str(w.get("clue_ru") or ""),
        })

    if len(hidden) == 1:
        w = hidden_info[0]
        arrow = "↔" if w["direction"] == "across" else "↕"
        instruction = f"Schreibe Wort {w['number']}{arrow}:"
    else:
        nums = " · ".join(
            f"{w['number']}{'↔' if w['direction'] == 'across' else '↕'}"
            for w in hidden_info
        )
        instruction = f"Schreibe die Wörter *durch Leerzeichen getrennt* ({nums}):"

    prompt = "\n".join(word_lines) + f"\n\n{instruction}"

    state_key = f"cw_answer:{int(user.id)}:{dispatch_id}"
    _store_pending_input_state(
        state_key=state_key,
        user_id=int(user.id),
        state_type=PENDING_INPUT_STATE_CROSSWORD,
        payload={
            "dispatch_id": dispatch_id,
            "hidden_words": hidden_info,
            "state_key": state_key,
            "started_at": __import__("time").time(),
        },
        ttl_seconds=CROSSWORD_ANSWER_TTL_SECONDS,
    )

    await query.answer()
    dm_sent = False
    try:
        await context.bot.send_message(
            chat_id=int(user.id),
            text=prompt,
            parse_mode="Markdown",
        )
        dm_sent = True
    except Exception:
        logging.warning("cw_callback: DM prompt failed user_id=%s", int(user.id))

    if not dm_sent:
        try:
            await query.message.reply_text(
                "Antworte in der Privatnachricht mit dem Bot — "
                "damit du andere Spieler nicht spoilerst! 🤫"
            )
        except Exception:
            logging.warning("cw_callback: fallback group reply failed dispatch_id=%s", dispatch_id, exc_info=True)


async def prepare_crossword_pool_job(context: CallbackContext) -> None:
    """Startup + periodic: generate crosswords and render images."""
    try:
        from backend.crossword_generator import prepare_crossword_pool
        result = await asyncio.to_thread(
            prepare_crossword_pool,
            target_ready=CROSSWORD_POOL_TARGET,
            max_attempts=20,
        )
        logging.info("crossword_pool_job done: %s", result)
    except Exception:
        logging.warning("crossword_pool_job failed", exc_info=True)

    try:
        from backend.crossword_renderer import prepare_crossword_images_batch
        img_result = await asyncio.to_thread(prepare_crossword_images_batch, limit=10)
        logging.info("crossword_render_job done: %s", img_result)
    except Exception:
        logging.warning("crossword_render_job failed", exc_info=True)


async def admin_crossword_send_command(update: Update, context: CallbackContext) -> None:
    """Send a crossword to this chat immediately (admin test). /admin_cw_send"""
    user    = update.effective_user
    chat    = update.effective_chat
    message = update.effective_message
    if not user or not chat or not message:
        return
    if not _can_use_image_quiz_test_commands(getattr(user, "id", None)):
        await message.reply_text("Allowed users only.")
        return

    status_msg = await message.reply_text("Preparing crossword...")

    # Self-healing: a broken entry (bad image) is advanced+retired and the next
    # one is tried, so one /admin_cw_send always yields a working crossword.
    last_error = "no ready crossword"
    for _attempt in range(6):
        try:
            entry = await asyncio.to_thread(pick_next_crossword, cooldown_days=0)
        except Exception as exc:
            await status_msg.edit_text(f"pick_next_crossword failed: {exc}")
            return
        if not entry:
            await status_msg.edit_text("No ready crossword. Run /admin_cw_pool first.")
            return

        crossword_id = str(entry.get("crossword_id") or "")
        object_key = str(entry.get("image_object_key") or "")
        if not object_key:
            last_error = f"no image for {crossword_id[:8]}"
            await asyncio.to_thread(mark_crossword_send_failed, crossword_id)
            continue
        try:
            image_url = r2_public_url(object_key)
        except Exception as exc:
            last_error = f"r2_public_url failed: {exc}"
            await asyncio.to_thread(mark_crossword_send_failed, crossword_id)
            continue

        slot_now = _get_quiz_schedule_now()
        ok = await send_crossword_to_chat(
            context,
            crossword_entry=entry,
            image_url=image_url,
            slot_date=slot_now.date(),
            slot_hour=int(slot_now.hour) * 10000 + int(slot_now.second) + _attempt,
            chat_id=int(chat.id),
            target_user_id=int(user.id),
        )
        if ok:
            # Отмечаем отправленным — иначе очередь не двигается и команда раз за
            # разом присылает ОДИН И ТОТ ЖЕ кроссворд: `pick_next_crossword` берёт
            # самый давно не отправлявшийся, а без этой отметки он навсегда остаётся
            # первым. Плановая рассылка и /admin_cw_resend это делают, а тестовая
            # отправка — нет.
            try:
                await asyncio.to_thread(mark_crossword_sent, crossword_id)
            except Exception:
                logging.warning("admin_cw_send: mark_crossword_sent failed crossword_id=%s",
                                crossword_id, exc_info=True)
            await status_msg.delete()
            return
        # send_photo failed (e.g. broken image) → advance/retire and try next.
        last_error = f"send failed for {crossword_id[:8]}"
        await asyncio.to_thread(mark_crossword_send_failed, crossword_id)

    await status_msg.edit_text(f"Crossword send failed after retries ({last_error}).")


async def admin_crossword_resend_command(update: Update, context: CallbackContext) -> None:
    """Delete the last crossword in EVERY chat (groups + DMs) and send one fresh
    crossword to all delivery targets — an out-of-schedule "everyone re-check the
    fixed grid" action. The visual fix is in the Mini-App (✏️ Antworten).
    /admin_cw_resend"""
    user = update.effective_user
    message = update.effective_message
    if not user or not message:
        return
    if not _can_use_image_quiz_test_commands(getattr(user, "id", None)):
        await message.reply_text("Allowed users only.")
        return
    status = await message.reply_text("⏳ Удаляю последний кроссворд во всех чатах и шлю новый…")

    # 1) Delete the most recent crossword message in each chat.
    from backend.database import list_last_crossword_messages
    rows = await asyncio.to_thread(list_last_crossword_messages)
    deleted = 0
    for r in rows:
        try:
            await context.bot.delete_message(chat_id=int(r["chat_id"]), message_id=int(r["message_id"]))
            deleted += 1
        except Exception:
            pass  # >48h old, no rights, or already gone

    # 2) Pick a ready crossword (self-healing) and broadcast to all targets.
    last_error = "no ready crossword"
    entry = None
    image_url = None
    for _ in range(6):
        entry = await asyncio.to_thread(pick_next_crossword, cooldown_days=0)
        if not entry:
            break
        cid = str(entry.get("crossword_id") or "")
        key = str(entry.get("image_object_key") or "")
        if not key:
            last_error = f"no image for {cid[:8]}"
            await asyncio.to_thread(mark_crossword_send_failed, cid)
            continue
        try:
            image_url = r2_public_url(key)
            break
        except Exception as exc:
            last_error = f"r2_public_url failed: {exc}"
            await asyncio.to_thread(mark_crossword_send_failed, cid)
            entry = None
            continue
    if not entry or not image_url:
        await status.edit_text(f"🗑 Удалено старых: {deleted}. Нет готового кроссворда ({last_error}) — запусти /admin_cw_pool.")
        return

    targets = await _collect_quiz_delivery_user_targets(context)
    slot_now = _get_quiz_schedule_now()
    uniq_slot = int(slot_now.hour) * 10000 + int(slot_now.minute) * 100 + int(slot_now.second)
    sent = 0
    for t in targets or []:
        cid = int(t.get("chat_id") or 0)
        if cid == 0:
            continue
        ok = await send_crossword_to_chat(
            context, crossword_entry=entry, image_url=image_url,
            slot_date=slot_now.date(), slot_hour=uniq_slot, chat_id=cid, target_user_id=cid)
        if ok:
            sent += 1
    if sent > 0:
        try:
            await asyncio.to_thread(mark_crossword_sent, str(entry.get("crossword_id") or ""))
        except Exception:
            pass
    await status.edit_text(
        f"✅ Удалено старых: {deleted}. Отправлено новых: {sent}.\n"
        f"Открой «🧩 Antworten» — проверь сетку (буквы/цифры).")


# ─────────────────────────────────────────────────────────────
#  ANAGRAM (assemble-the-word) — Mini-App card, send, scheduler
# ─────────────────────────────────────────────────────────────

def _anagram_enabled() -> bool:
    return (os.getenv("ANAGRAM_ENABLED") or "true").strip().lower() not in ("0", "false", "no")


def _is_anagram_slot(slot_dt) -> bool:
    return (int(slot_dt.hour), int(slot_dt.minute)) in ANAGRAM_SLOT_TIMES


def _build_anagram_card_payload(entry: dict) -> dict | None:
    """Dictionary entry → {word, hint_ru, scrambled}, or None if unsuitable.

    Reuses the same validation/scramble as the (now-retired) anagram poll
    generator so the game stays linguistically sound.
    """
    word_ru = (entry.get("word_ru") or "").strip()
    if not _is_valid_anagram_ru_hint(word_ru):
        return None
    correct_word = _extract_german_word(entry, require_single_token=True)
    if not correct_word or not _is_valid_anagram_target(correct_word):
        return None
    correct_word = _to_letters_only_word(correct_word)
    if not _is_valid_anagram_target(correct_word):
        return None
    scrambled = _scramble_word_preserve_ends(correct_word)
    if not scrambled:
        return None
    if _letters_signature(scrambled) != _letters_signature(correct_word):
        return None
    return {"word": correct_word, "hint_ru": word_ru, "scrambled": scrambled}


async def _generate_anagram_card_payload() -> dict | None:
    # One word = one card. Without this the bank drifts into repeats (Einwanderer
    # landed there three times), and the learner solves the same word again.
    try:
        from backend.database import list_anagram_words
        known_words = await asyncio.to_thread(list_anagram_words)
    except Exception:
        logging.warning("ag_gen: list_anagram_words failed", exc_info=True)
        known_words = set()

    for _ in range(40):  # 8+ letter words are rarer, so try more dictionary entries
        try:
            entry = await asyncio.to_thread(get_random_dictionary_entry, cooldown_days=0)
        except Exception:
            logging.warning("ag_gen: get_random_dictionary_entry failed", exc_info=True)
            return None
        if not entry:
            continue
        payload = _build_anagram_card_payload(entry)
        if payload and str(payload["word"]).lower() not in known_words:
            return payload
    return None


def _build_anagram_caption(hint_ru: str) -> str:
    safe_hint = html.escape(str(hint_ru or "").strip())
    return (
        "🔤 <b>Anagramm</b> — собери слово!\n\n"
        f"🔡 Подсказка: <b>{safe_hint}</b>\n"
        "Первая и последняя буквы на месте, середина перемешана. Жми кнопку 👇"
    )


def _build_anagram_keyboard(dispatch_id: int) -> InlineKeyboardMarkup:
    btn = InlineKeyboardButton(
        text="🧩 Spielen",
        url=get_webapp_deeplink(f"ans_ag_{dispatch_id}"),
    )
    return InlineKeyboardMarkup([[btn]])


async def send_anagram_to_chat(
    context: CallbackContext,
    *,
    card_id: str,
    payload: dict,
    slot_date,
    slot_hour: int,
    chat_id: int,
    target_user_id: int,
    held: bool = False,
) -> bool:
    """Send one anagram card to a chat. Returns True on success."""
    try:
        created = await asyncio.to_thread(
            create_anagram_card,
            card_id=card_id, word=payload["word"], hint_ru=payload["hint_ru"],
            scrambled=payload["scrambled"],
        )
    except Exception:
        logging.warning("ag_send: create_card failed card_id=%s", card_id, exc_info=True)
        return False
    if not created:
        # Another card already owns this word (pooled cards keep their own card_id
        # and pass). Nothing to send: the word would be a repeat.
        logging.info("ag_send: duplicate word suppressed card_id=%s word=%s", card_id, payload["word"])
        return False

    try:
        dispatch_id = await asyncio.to_thread(
            record_anagram_dispatch,
            slot_date=slot_date, slot_hour=int(slot_hour), card_id=card_id,
            target_user_id=int(target_user_id), chat_id=int(chat_id),
        )
    except Exception:
        logging.warning("ag_send: dispatch insert failed card_id=%s chat_id=%s", card_id, chat_id, exc_info=True)
        return False
    if not dispatch_id:
        logging.info(
            "ag_send: duplicate suppressed card_id=%s chat_id=%s slot=%s/%s",
            card_id, chat_id, slot_date, slot_hour,
        )
        return False

    if held and int(chat_id) == int(target_user_id):  # Этап 3f: record, don't send
        await asyncio.to_thread(
            record_interactive_inbox, user_id=int(target_user_id), kind="ag",
            dispatch_id=int(dispatch_id), chat_id=int(chat_id),
            deeplink=f"ans_ag_{dispatch_id}", title="🔤 Anagramm", pushed=False)
        logging.info("held kind=ag dispatch_id=%s user=%s", dispatch_id, target_user_id)
        return True

    caption  = _build_anagram_caption(payload["hint_ru"])
    caption  = _append_free_pro_teaser(caption, chat_id)
    keyboard = _build_anagram_keyboard(dispatch_id)
    poster = None
    try:
        from backend.interactive_card import render_anagram_card
        poster = await asyncio.to_thread(render_anagram_card)
    except Exception:
        logging.warning("ag_send: card render failed card_id=%s", card_id, exc_info=True)
    try:
        if poster:
            msg = await context.bot.send_photo(
                chat_id=int(chat_id), photo=io.BytesIO(poster),
                caption=caption, reply_markup=keyboard, parse_mode="HTML",
            )
        else:
            msg = await context.bot.send_message(
                chat_id=int(chat_id), text=caption, reply_markup=keyboard, parse_mode="HTML",
            )
    except Exception as exc:
        logging.warning("ag_send_failed dispatch_id=%s chat_id=%s: %s", dispatch_id, chat_id, exc)
        return False

    try:
        await asyncio.to_thread(
            update_anagram_dispatch_telegram_id, dispatch_id, telegram_message_id=int(msg.message_id)
        )
    except Exception:
        logging.warning("ag_send: update telegram_id failed dispatch_id=%s", dispatch_id, exc_info=True)

    if int(chat_id) == int(target_user_id):  # DM feed only
        try:
            await asyncio.to_thread(
                record_interactive_inbox,
                user_id=int(target_user_id), kind="ag", dispatch_id=int(dispatch_id),
                chat_id=int(chat_id), telegram_message_id=int(msg.message_id),
                deeplink=f"ans_ag_{dispatch_id}", title="🔤 Anagramm",
                keyboard_json=_inbox_kb_json(keyboard),
            )
        except Exception:
            logging.debug("ag_send: inbox record failed dispatch_id=%s", dispatch_id, exc_info=True)

    logging.info("ag_send_ok dispatch_id=%s card_id=%s chat_id=%s", dispatch_id, card_id, chat_id)
    return True


async def _ensure_anagram_card() -> dict | None:
    """Generate one anagram card into the pool and return it (card_id + payload)."""
    payload = await _generate_anagram_card_payload()
    if not payload:
        return None
    card_id = str(__import__("uuid").uuid4())
    try:
        created = await asyncio.to_thread(
            create_anagram_card, card_id=card_id, word=payload["word"],
            hint_ru=payload["hint_ru"], scrambled=payload["scrambled"],
        )
    except Exception:
        logging.warning("ag_pool: create_card failed", exc_info=True)
        return None
    if not created:  # word already in the bank — the caller just tries another one
        logging.info("ag_pool: duplicate word skipped word=%s", payload["word"])
        return None
    return {"card_id": card_id, "word": payload["word"], "hint_ru": payload["hint_ru"],
            "scrambled": payload["scrambled"], "explanation": ""}


async def prepare_anagram_pool_job(context: CallbackContext) -> None:
    """Startup + nightly: fill the anagram pool to target (off critical path), so a
    slot is never missed when generation hiccups (like the other games' pools)."""
    try:
        have = await asyncio.to_thread(count_available_anagram_cards, cooldown_days=ANAGRAM_COOLDOWN_DAYS)
    except Exception:
        have = 0
    made = 0
    attempts = 0
    while have + made < ANAGRAM_POOL_TARGET and attempts < ANAGRAM_POOL_TARGET * 3:
        attempts += 1
        entry = await _ensure_anagram_card()
        if entry:
            made += 1
    logging.info("anagram_pool_job done: have=%s made=%s target=%s", have, made, ANAGRAM_POOL_TARGET)


async def _send_scheduled_anagram(context: CallbackContext) -> None:
    if _is_quiet_hours_now():
        logging.info("quiet_hours: skip anagram")
        return
    if not _anagram_enabled():
        logging.info("ag_slot_triggered enabled=False — skipping")
        return
    slot_now  = _get_quiz_schedule_now()
    slot_date = slot_now.date()
    slot_hour = int(slot_now.hour)
    if not _is_anagram_slot(slot_now):
        return

    # Pick a ready card from the pool; generate on demand only if the pool is empty.
    try:
        entry = await asyncio.to_thread(pick_next_anagram, cooldown_days=ANAGRAM_COOLDOWN_DAYS)
    except Exception:
        logging.warning("ag_slot: pick_next_anagram failed", exc_info=True)
        entry = None
    if not entry:
        entry = await _ensure_anagram_card()
    if not entry:
        logging.info("ag_slot: no anagram card available slot=%s/%s", slot_date, slot_hour)
        await _alert_admin_interactive(
            context,
            f"⚠️ <b>Anagramm не отправлена</b> — нет карточки в пуле и генерация не удалась "
            f"(слот {slot_date} {slot_hour}:00). Проверь логи.",
            throttle_key="ag_empty",
        )
        return

    payload = {"word": entry["word"], "hint_ru": entry["hint_ru"], "scrambled": entry["scrambled"]}
    card_id = str(entry["card_id"])
    delivery_targets = await _collect_quiz_delivery_user_targets(context)
    if not delivery_targets:
        logging.info("ag_slot: no delivery targets slot=%s/%s", slot_date, slot_hour)
        return

    sent = 0
    for target in delivery_targets:
        target_chat_id = int(target.get("chat_id") or 0)
        if target_chat_id == 0:
            continue
        ok = await send_anagram_to_chat(
            context, card_id=card_id, payload=payload,
            slot_date=slot_date, slot_hour=slot_hour,
            chat_id=target_chat_id, target_user_id=target_chat_id,
            held=bool(target.get("held")),
        )
        if ok:
            sent += 1
    if sent > 0:
        await asyncio.to_thread(mark_anagram_sent, card_id)
    else:
        await asyncio.to_thread(mark_anagram_send_failed, card_id)
        await _alert_admin_interactive(
            context,
            f"⚠️ <b>Anagramm: отправка не удалась</b> (0 доставлено, слот {slot_date} {slot_hour}:00).",
            throttle_key="ag_send_fail",
        )
    logging.info("ag_slot_done slot=%s/%s card_id=%s sent=%d", slot_date, slot_hour, card_id, sent)


_CHALLENGE_KIND_LABELS = {
    "rb": "Rätsel 🧩", "cw": "Kreuzwort 🔤", "ag": "Anagramm 🔀",
    "qf": "Freie Antwort ✍️", "ls": "Hörverständnis 🎧",
}
_AU_FORMAT_LABELS = {
    "cloze": "Lückentext ✏️", "wortbildung": "Wortbildung 🔧",
    "wortgruppe": "Wortgruppe 🧱",
    "transform": "Satztransformation 🔄", "error": "Fehler finden 🔍",
    "hoerluecke": "Hörlücke 🎧", "pin": "Finde im Bild 🖼",
    "synonym": "Synonym 🔁", "antonym": "Antonym ↔️",
}


def _au_specific_suffix(fmt: str, payload: dict) -> str:
    """A short, task-identifying snippet so two tasks of the SAME format are
    distinguishable on the plaque (e.g. 'Synonym 🔁: bestätigen')."""
    def _snip(s, n=40):
        s = re.sub(r"\s+", " ", str(s or "").strip())
        return (s[: n - 1].rstrip() + "…") if len(s) > n else s
    if fmt in ("synonym", "antonym"):
        return _snip(payload.get("wort"), 30)
    if fmt in ("cloze", "wortbildung", "wortgruppe"):
        return _snip(payload.get("satz"))
    if fmt == "transform":
        return _snip(payload.get("original"))
    if fmt == "pin":
        return _snip(payload.get("question_de"))
    return ""


async def _challenge_label(challenge_key: str) -> str:
    kind, _, did = str(challenge_key or "").partition(":")
    if kind == "au":
        # challenge_key is content-keyed ("au:<aufgabe_id>"), not a dispatch id.
        try:
            from backend.database import get_aufgabe_by_id
            entry = await asyncio.to_thread(get_aufgabe_by_id, did)
            fmt = str((entry or {}).get("format") or "")
            base = _AU_FORMAT_LABELS.get(fmt, "Aufgabe ✏️")
            suffix = _au_specific_suffix(fmt, (entry or {}).get("payload") or {})
            return f"{base}: {suffix}" if suffix else base
        except Exception:
            return "Aufgabe ✏️"
    if kind == "as":
        return "Artikel Sprint ⚡"
    return _CHALLENGE_KIND_LABELS.get(kind, "Aufgabe")


def _fmt_secs(ms) -> str:
    try:
        return f"{(int(ms) / 1000):.1f}с"
    except (TypeError, ValueError):
        return "—"


async def _fetch_avatar_bytes(context: CallbackContext, user_id: int) -> bytes | None:
    """Download a Telegram user's current profile photo (largest size). Returns
    None if they have none or it's not accessible — the card then shows no avatar."""
    if not user_id:
        return None
    try:
        photos = await context.bot.get_user_profile_photos(int(user_id), limit=1)
        if getattr(photos, "total_count", 0) and photos.photos:
            sizes = photos.photos[0]
            tg_file = await context.bot.get_file(sizes[-1].file_id)
            buf = io.BytesIO()
            await tg_file.download_to_memory(buf)
            return buf.getvalue()
    except Exception:
        logging.debug("overtaken: avatar fetch failed uid=%s", user_id, exc_info=True)
    return None


async def _send_challenge_notifications_job(context: CallbackContext) -> None:
    """Poll the ranking outbox and DM live pings (e.g. 'you were overtaken')."""
    try:
        pending = await asyncio.to_thread(get_pending_challenge_notifications, 20)
    except Exception:
        return
    for n in pending:
        try:
            kind = n.get("kind")
            p = n.get("payload") or {}
            label = await _challenge_label(n.get("challenge_key") or "")
            if kind == "overtaken":
                # A single beautiful plaque per (user, challenge): sent once, then
                # its button is edited in place as the user sinks further. For BATTLES
                # the button is a deeplink back into that battle (see who overtook you
                # + the results); otherwise a plain "ты на N-м месте" chip.
                place = int(p.get("place") or 2)
                # Prefer the human task label from the payload (e.g. "Artikel Battle").
                label = str(p.get("task_kind") or label)
                open_kind = str(p.get("open_kind") or "").strip()
                battle_id = int(p.get("battle_id") or 0)
                if open_kind and battle_id:
                    btn = InlineKeyboardMarkup([[InlineKeyboardButton(
                        f"🏆 Открыть батл (ты {place}-й) — кто обошёл",
                        url=get_webapp_deeplink(f"ans_{open_kind}_{battle_id}"))]])
                else:
                    btn = InlineKeyboardMarkup([[InlineKeyboardButton(
                        f"📉 Сейчас ты на {place}-м месте", callback_data="overtaken_noop")]])
                mid = n.get("telegram_message_id")
                if mid:
                    try:
                        await context.bot.edit_message_reply_markup(
                            chat_id=int(n["user_id"]), message_id=int(mid), reply_markup=btn)
                    except Exception:
                        logging.warning("overtaken: edit markup failed id=%s", n.get("id"), exc_info=True)
                else:
                    from backend.overtaken_card import render_overtaken_card, pick_overtaken_background
                    overtaker = str(p.get("above_name") or p.get("leader_name") or "").strip()
                    above_uid = int(p.get("above_user_id") or p.get("leader_user_id") or 0)
                    avatar = await _fetch_avatar_bytes(context, above_uid) if above_uid else None
                    bg = await asyncio.to_thread(pick_overtaken_background)
                    png = await asyncio.to_thread(
                        render_overtaken_card, label,
                        overtaker_name=overtaker, avatar_bytes=avatar, background_bytes=bg,
                    )
                    cap = (
                        f"😔 Тебя обошёл <b>{html.escape(overtaker)}</b> в «{html.escape(label)}»"
                        if overtaker else f"😔 Тебя обошли в «{html.escape(label)}»"
                    )
                    msg = await context.bot.send_photo(
                        chat_id=int(n["user_id"]), photo=io.BytesIO(png),
                        caption=cap, parse_mode="HTML", reply_markup=btn)
                    await asyncio.to_thread(
                        set_challenge_notification_message_id, int(n["id"]), int(msg.message_id))
                await asyncio.to_thread(mark_challenge_notification_sent, int(n["id"]))
                continue
            elif kind == "inbox_done":
                # Mark the task message ✅ in place (DM feed): prepend a "✅ Выполнено"
                # row and KEEP the card's original buttons (so e.g. Adjektiv Sprint
                # still shows both "Играть" and "Учить окончания").
                chat_id = int(p.get("chat_id") or 0)
                message_id = int(p.get("message_id") or 0)
                deeplink = str(p.get("deeplink") or "").strip()
                rows = [[InlineKeyboardButton("✅ Выполнено", callback_data="inbox_done_noop")]]
                original_rows = _inbox_kb_from_json(p.get("keyboard_json"))
                if original_rows:
                    rows += original_rows
                elif deeplink:
                    rows.append([InlineKeyboardButton("↻ Открыть снова", url=get_webapp_deeplink(deeplink))])
                if chat_id and message_id:
                    try:
                        await context.bot.edit_message_reply_markup(
                            chat_id=chat_id, message_id=message_id,
                            reply_markup=InlineKeyboardMarkup(rows))
                    except BadRequest as exc:
                        # "not modified" → the ✅ is already there (success). Any other
                        # BadRequest (message deleted / can't be edited) is permanent →
                        # give up so we don't retry forever.
                        msg = str(exc).lower()
                        if "not modified" not in msg:
                            logging.info("inbox_done: permanent edit failure id=%s: %s", n.get("id"), exc)
                    except (Forbidden,) as exc:
                        logging.info("inbox_done: blocked, giving up id=%s: %s", n.get("id"), exc)
                    except Exception:
                        # Transient (network / rate-limit / TimedOut): leave the row
                        # PENDING so the next poll retries — otherwise a single hiccup
                        # would permanently lose the ✅ marker.
                        logging.warning("inbox_done: transient edit failure, will retry id=%s",
                                        n.get("id"), exc_info=True)
                        continue
                await asyncio.to_thread(mark_challenge_notification_sent, int(n["id"]))
                continue
            elif kind == "admin_alert":
                text = (
                    f"❌ <b>Ошибка проверки ответа в Mini-App</b>\n"
                    f"«{label}» (id {p.get('dispatch_id')})\n"
                    f"<code>{html.escape(str(p.get('error') or ''))[:200]}</code>"
                )
            else:
                await asyncio.to_thread(mark_challenge_notification_sent, int(n["id"]))
                continue
            await context.bot.send_message(chat_id=int(n["user_id"]), text=text, parse_mode="HTML")
            await asyncio.to_thread(mark_challenge_notification_sent, int(n["id"]))
        except Exception:
            logging.warning("challenge notif send failed id=%s", n.get("id"), exc_info=True)


# Every fresh-interactive category (cat_key, label) shown in the daily «Итоги дня»
# digest, in display order. The numbers come from get_daily_interactive_activity(), which
# counts each type from its own answer table (all channels — Mini-App AND Telegram group),
# so ALL kinds are represented, not only the ones answered in the Mini-App. SRS/FSRS review
# and the self-paced number practice (np) are excluded by design (drill, not a fresh task).
# Sprint/Battle sets (sp/ast/ad) count as ONE task each with a fractional {0,0.5,1} score.
_DIGEST_CATEGORIES = [
    ("art",  "🇩🇪 Артикли (квиз)"),
    ("poll", "📊 Викторина"),
    ("iq",   "🖼️ Картинка-квиз"),
    ("vr",   "🔍 Визуальная загадка"),
    ("rb",   "🧩 Ребус"),
    ("cw",   "🔤 Кроссворд"),
    ("ag",   "🔀 Анаграмма"),
    ("au",   "✏️ Aufgabe"),
    ("ls",   "🎧 Аудирование"),
    ("nd",   "🔢 Числа-диктант"),
    ("qf",   "✍️ Свой вариант"),
    ("sp",   "🏃 Спринт син/ант"),
    ("ast",  "📐 Артикль-спринт"),
    ("ad",   "📝 Адъектив-спринт"),
    # Wo-Frage sprint. A category missing from this list is not shown as a raw code — the
    # digest loop iterates over THIS order, so its answers silently vanish from the
    # breakdown while still counting in the day's totals, and the rows stop adding up.
    ("wf",   "❓ Wo-Frage-спринт"),
]


def _fmt_score(x) -> str:
    """Whole numbers as ints ("5"); halves kept ("5.5"). Sprint/Battle sets score a
    fractional {0,0.5,1}, so digest totals / per-row "Верно" can be non-integer."""
    x = float(x or 0)
    return str(int(x)) if x.is_integer() else f"{x:g}"


async def _send_daily_challenge_digest_job(context: CallbackContext) -> None:
    """Evening DM per participant: a clean per-category breakdown (answered/sent ·
    correct) + the day's totals — no cryptic per-task labels or seconds."""
    from backend.database import get_daily_interactive_activity
    # Per user → per category [answered, correct], counted across EVERY interactive type
    # from its own answer table (all channels), not just the Mini-App-fed challenge_results.
    # We DON'T report "sent": answers come from group broadcasts, on-demand pulls and a
    # rolling window, so they legitimately exceed "personally sent today" → the old
    # "answered/sent %" produced impossible >100% numbers. The honest metric is activity.
    try:
        agg = await asyncio.to_thread(get_daily_interactive_activity, 24)
    except Exception:
        logging.warning("daily digest: fetch failed", exc_info=True)
        return
    if not agg:
        return

    today = _get_quiz_schedule_now().date()
    from backend.daily_summary_card import render_daily_summary
    labels = {c: lbl for c, lbl in _DIGEST_CATEGORIES}
    order = [c for c, _ in _DIGEST_CATEGORIES]
    date_str = today.strftime("%d.%m.%Y")
    sent_count = 0
    for uid, cats in agg.items():
        answered = sum(v[0] for v in cats.values())
        correct = sum(v[1] for v in cats.values())
        acc = round(correct / answered * 100) if answered else 0
        card_rows = []
        for cat in order:
            v = cats.get(cat)
            if not v or v[0] == 0:
                continue
            a, c = v[0], v[1]
            card_rows.append({"label": labels[cat], "correct": c, "answered": a,
                              "acc": round(c / a * 100) if a else 0})
        try:
            _sblk = await _streak_status_block(int(uid))
        except Exception:
            _sblk = ""

        png = None
        try:
            png = await asyncio.to_thread(
                render_daily_summary, date_str=date_str, answered=answered,
                correct=correct, accuracy_pct=acc, streak_text=_sblk, rows=card_rows)
        except Exception:
            logging.warning("daily digest render failed uid=%s", uid, exc_info=True)
        # Cryptic /group, /invite commands → two tappable buttons under the card.
        kb = InlineKeyboardMarkup([
            [InlineKeyboardButton("👥 Играть командой с друзьями", callback_data="digest:group")],
            # switch_inline_query → Telegram открывает выбор чата и отправляет другу
            # брендовую карточку с рабочей кнопкой (см. _handle_share_inline_query),
            # а не голую ссылку в собственную личку.
            [InlineKeyboardButton(f"🎁 Позвать друга (+{REFERRAL_REWARD_DAYS} дней полного доступа обоим)",
                                  switch_inline_query="")],
        ])
        cap_streak = await _streak_caption_block(int(uid))
        caption = (f"🏁 <b>Итоги дня</b> · {date_str}\n"
                   f"✅ Ответил: <b>{answered}</b> · 🎯 Верно: <b>{_fmt_score(correct)}</b> ({acc}%)")
        if cap_streak:
            caption += "\n\n" + cap_streak
        try:
            if png:
                await context.bot.send_photo(chat_id=int(uid), photo=io.BytesIO(png),
                                              caption=caption, parse_mode="HTML", reply_markup=kb)
            else:
                # PIL unavailable → honest plain-text fallback (no "sent" denominator).
                lines = [f"🏁 <b>Итоги дня</b> · {date_str}", "",
                         f"✅ Ты ответил: <b>{answered}</b> · 🎯 Верно: <b>{_fmt_score(correct)}</b> ({acc}%)"]
                if cap_streak:
                    lines += ["", cap_streak]
                lines += ["", "<b>По категориям</b> — верно/ответил · точность:"]
                for r in card_rows:
                    lines.append(f"{r['label']} — {_fmt_score(r['correct'])}/{r['answered']} · {r['acc']}%")
                await context.bot.send_message(chat_id=int(uid), text="\n".join(lines),
                                               parse_mode="HTML", reply_markup=kb)
            sent_count += 1
        except Exception:
            logging.warning("daily digest send failed uid=%s", uid, exc_info=True)
    logging.info("daily_challenge_digest sent=%d participants", sent_count)


async def _admin_test_digest_command(update: Update, context: CallbackContext) -> None:
    """/admin_digest — send the «Итоги дня» card + buttons to the caller ONLY (preview).
    Uses your real last-24h activity if any; otherwise sample data so you can still see
    the layout, streak block and the two buttons. Does NOT touch other users."""
    user = update.effective_user; message = update.effective_message
    if not user or not message:
        return
    if not _can_use_image_quiz_test_commands(getattr(user, "id", None)):
        await message.reply_text("Allowed users only."); return
    uid = int(user.id)
    from backend.daily_summary_card import render_daily_summary
    from backend.database import get_daily_interactive_activity

    labels = {c: lbl for c, lbl in _DIGEST_CATEGORIES}
    order = [c for c, _ in _DIGEST_CATEGORIES]
    try:
        activity = await asyncio.to_thread(get_daily_interactive_activity, 24)
    except Exception:
        activity = {}
    cats: dict[str, list] = dict(activity.get(uid, {}))

    sample = not cats
    if sample:  # no activity → show a representative sample card
        cats = {"rb": [1, 0], "ag": [4, 2], "au": [2, 1], "ls": [1, 1]}

    answered = sum(v[0] for v in cats.values())
    correct = sum(v[1] for v in cats.values())
    acc = round(correct / answered * 100) if answered else 0
    card_rows = [{"label": labels[cat], "correct": cats[cat][1], "answered": cats[cat][0],
                  "acc": round(cats[cat][1] / cats[cat][0] * 100) if cats[cat][0] else 0}
                 for cat in order if cats.get(cat) and cats[cat][0] > 0]

    date_str = _get_quiz_schedule_now().date().strftime("%d.%m.%Y")
    _sblk = await _streak_status_block(uid)
    png = None
    try:
        png = await asyncio.to_thread(
            render_daily_summary, date_str=date_str, answered=answered, correct=correct,
            accuracy_pct=acc, streak_text=_sblk, rows=card_rows)
    except Exception:
        logging.warning("admin test digest render failed", exc_info=True)

    kb = InlineKeyboardMarkup([
        [InlineKeyboardButton("👥 Играть командой с друзьями", callback_data="digest:group")],
        # switch_inline_query → выбор чата в Telegram + отправка карточки-приглашения другу.
        [InlineKeyboardButton(f"🎁 Позвать друга (+{REFERRAL_REWARD_DAYS} дней полного доступа обоим)",
                              switch_inline_query="")],
    ])
    cap_streak = await _streak_caption_block(uid)
    prefix = "🧪 <i>Превью (пример данных)</i>\n" if sample else "🧪 <i>Превью (твои данные за 24 ч)</i>\n"
    caption = (f"{prefix}🏁 <b>Итоги дня</b> · {date_str}\n"
               f"✅ Ответил: <b>{answered}</b> · 🎯 Верно: <b>{_fmt_score(correct)}</b> ({acc}%)")
    if cap_streak:
        caption += "\n\n" + cap_streak
    if png:
        await message.reply_photo(photo=io.BytesIO(png), caption=caption,
                                  parse_mode="HTML", reply_markup=kb)
    else:
        await message.reply_text(caption + "\n\n(PIL недоступен — карточка не отрисована)",
                                 parse_mode="HTML", reply_markup=kb)


def _html_escape(s) -> str:
    return html.escape(str(s or ""), quote=False)


def _split_html_message(text: str, limit: int = 3800) -> list[str]:
    """Split a long HTML message on line boundaries so each chunk stays under
    Telegram's 4096-char cap without cutting a tag."""
    if len(text) <= limit:
        return [text]
    chunks, cur = [], ""
    for line in text.split("\n"):
        if len(cur) + len(line) + 1 > limit and cur:
            chunks.append(cur)
            cur = ""
        cur = f"{cur}\n{line}" if cur else line
    if cur:
        chunks.append(cur)
    return chunks


def _fmt_distractor_preview(word_item: dict, result: dict) -> str:
    """Human-readable preview of the trainer-distractor pipeline output for one word,
    so we can eyeball quality before wiring up the UI."""
    relation = str(word_item.get("relation") or "synonym")
    rel_ru = "антонимы" if relation == "antonym" else "синонимы"
    emoji = "🔴" if relation == "antonym" else "🟢"
    wort = str(word_item.get("wort") or "")
    hint = str(word_item.get("hint_ru") or "")
    counts = result.get("counts") or {}
    kept = result.get("kept") or []
    rejected = result.get("rejected") or []
    tex = result.get("target_example") or {}

    lines = [
        f"{emoji} <b>Дистракторы · {rel_ru}</b>",
        f"Слово: <b>{_html_escape(wort)}</b>" + (f" · <i>{_html_escape(hint)}</i>" if hint else ""),
    ]
    if tex.get("de"):
        lines.append(f"Пример: {_html_escape(tex['de'])}" + (f"\n<i>{_html_escape(tex.get('ru') or '')}</i>" if tex.get("ru") else ""))
    lines.append(
        f"\n📊 Сгенерировано <b>{counts.get('generated', 0)}</b> · "
        f"прошло прокурора <b>{counts.get('after_prosecutor', 0)}</b> · "
        f"осталось <b>{counts.get('kept', 0)}</b>"
    )
    ready = "✅ готово к ротации" if result.get("trainer_ready") else "⚠️ мало чистых — не в ротацию"
    lines.append(ready)
    diag = result.get("diag") or {}
    if diag:
        lines.append(f"<i>judge: строк {diag.get('judge_rows', 0)} · попыток {diag.get('judge_attempts', '?')} · "
                     f"классы {', '.join(diag.get('judge_classes') or []) or '—'}</i>")
        if diag.get("judge_error"):
            lines.append(f"<i>judge error: {_html_escape(diag['judge_error'])}</i>")
        if diag.get("judge_raw"):
            lines.append(f"<i>judge raw: {_html_escape(diag['judge_raw'])}</i>")

    if kept:
        lines.append(f"\n✅ <b>Чистые дистракторы ({len(kept)})</b>")
        for d in kept:
            # d['word'] is already the storage form (article included for nouns).
            g = f" — {_html_escape(d['ru_gloss'])}" if d.get("ru_gloss") else ""
            trap = f" · <i>{_html_escape(d['trap_type'])}</i>" if d.get("trap_type") else ""
            lines.append(f"• <b>{_html_escape(d['word'])}</b>{g}{trap}")
            if d.get("why_not"):
                lines.append(f"   ↳ {_html_escape(d['why_not'])}")
            if d.get("example_de"):
                lines.append(f"   „{_html_escape(d['example_de'])}“")

    correct_ex = result.get("correct_examples") or []
    if correct_ex:
        lines.append(f"\n🟩 <b>Примеры правильных ({len(correct_ex)})</b> — подстановка в предложение:")
        for e in correct_ex[:6]:
            lines.append(f"• <b>{_html_escape(e.get('word') or '')}</b>: „{_html_escape(e.get('sentence_de') or '')}“")
            if e.get("sentence_ru"):
                lines.append(f"   <i>{_html_escape(e['sentence_ru'])}</i>")

    if rejected:
        lines.append(f"\n🗑 <b>Отклонено ({len(rejected)})</b>")
        for r in rejected[:20]:
            stage = _html_escape(str(r.get("stage") or ""))
            lines.append(f"• <s>{_html_escape(str(r.get('word') or ''))}</s> [{stage}]: {_html_escape(str(r.get('reason') or ''))}")
        if len(rejected) > 20:
            lines.append(f"…и ещё {len(rejected) - 20}")
    return "\n".join(lines)


async def _admin_build_trainers_command(update: Update, context: CallbackContext) -> None:
    """/admin_build_trainers [N] — run the nightly trainer-build now for up to N words
    (default cap) that don't have trainer data yet. Persists results to the bank."""
    user = update.effective_user; message = update.effective_message
    if not user or not message:
        return
    if not _can_use_image_quiz_test_commands(getattr(user, "id", None)):
        await message.reply_text("Allowed users only."); return
    try:
        limit = int(context.args[0]) if getattr(context, "args", None) else None
    except (TypeError, ValueError):
        limit = None
    await asyncio.to_thread(ensure_sprint_schema)
    pending = await asyncio.to_thread(list_sprint_words_needing_trainer, limit=limit or 6)
    if not pending:
        await message.reply_text("✅ Все слова банка уже с тренажёром — строить нечего."); return
    await message.reply_text(
        f"⏳ Строю тренажёр для {len(pending)} слов(а): "
        f"{', '.join(_html_escape(p['wort']) for p in pending)}…\nПо ~1-2 мин на слово.",
        parse_mode="HTML")
    statuses = await build_sprint_trainer_job(context, limit=limit)
    body = "\n".join(f"• {_html_escape(s)}" for s in statuses) or "—"
    await message.reply_text(f"🏁 Готово:\n{body}", parse_mode="HTML")


async def _admin_trainer_preview_command(update: Update, context: CallbackContext) -> None:
    """/admin_trainer_preview <слово> — open the recognition TRAINER overlay on a saved
    bank word (must be trainer_ready). Creates a dispatch and sends a deep-link button."""
    user = update.effective_user; message = update.effective_message
    if not user or not message:
        return
    if not _can_use_image_quiz_test_commands(getattr(user, "id", None)):
        await message.reply_text("Allowed users only."); return
    args = context.args or []
    if not args:
        await message.reply_text("Использование: <code>/admin_trainer_preview &lt;слово&gt;</code>", parse_mode="HTML"); return
    word = " ".join(str(a) for a in args).strip()
    await asyncio.to_thread(ensure_sprint_schema)
    await asyncio.to_thread(ensure_trainer_schema)
    item = await asyncio.to_thread(get_sprint_item_by_word, word)
    if not item:
        await message.reply_text(f"Нет слова «{_html_escape(word)}» в банке."); return
    if not item.get("trainer_ready"):
        await message.reply_text(
            f"«{_html_escape(str(item.get('wort')))}» ещё без тренажёра. Сначала: "
            f"<code>/admin_sprint_distractors {_html_escape(word)} save</code> или /admin_build_trainers.",
            parse_mode="HTML"); return
    now = _get_quiz_schedule_now()
    slot_hour = int(now.hour) * 10000 + int(now.minute) * 100 + int(now.second)  # unique-ish for preview
    dispatch_id = await asyncio.to_thread(
        create_trainer_dispatch, sprint_id=str(item.get("sprint_id")), slot_date=now.date(),
        slot_hour=slot_hour, target_user_id=int(user.id), chat_id=int(message.chat_id))
    if dispatch_id is None:
        await message.reply_text("Не удалось создать превью (дубль слота). Попробуй ещё раз."); return
    relation = str(item.get("relation") or "synonym")
    rel_ru = "антонимов" if relation == "antonym" else "синонимов"
    emoji = "🔴" if relation == "antonym" else "🟢"
    kb = InlineKeyboardMarkup([[InlineKeyboardButton(
        "🎯 Открыть тренажёр", url=get_webapp_deeplink(f"ans_tr_{dispatch_id}"))]])
    caption = (
        f"{emoji} <b>Тренировка {rel_ru}</b>\nСлово: <b>{_html_escape(str(item.get('wort')))}</b> — "
        f"выбирай верный вариант из карточек."
    )
    poster = None
    try:
        from backend.interactive_card import render_trainer_relation_card
        poster = await asyncio.to_thread(render_trainer_relation_card, relation)
    except Exception:
        logging.warning("trainer preview: card render failed", exc_info=True)
    if poster:
        await message.reply_photo(photo=io.BytesIO(poster), caption=caption,
                                  parse_mode="HTML", reply_markup=kb)
    else:
        await message.reply_text(caption, parse_mode="HTML", reply_markup=kb)


async def _admin_sprint_distractors_command(update: Update, context: CallbackContext) -> None:
    """/admin_sprint_distractors <слово> [synonym|antonym] [save] — run the nightly
    trainer distractor pipeline on ONE bank word and DM the result. Add `save` to also
    persist the verified distractors + examples into the bank (trainer_json)."""
    user = update.effective_user; message = update.effective_message
    if not user or not message:
        return
    if not _can_use_image_quiz_test_commands(getattr(user, "id", None)):
        await message.reply_text("Allowed users only."); return
    args = context.args or []
    if not args:
        await message.reply_text(
            "Использование: <code>/admin_sprint_distractors &lt;слово&gt; [synonym|antonym] [save]</code>\n"
            "Пример: <code>/admin_sprint_distractors oberflächlich antonym save</code>",
            parse_mode="HTML"); return
    # Trailing flags in any order: `save` (persist) and/or the relation.
    tokens = [str(a).strip() for a in args]
    save = False
    if tokens and tokens[-1].lower() == "save":
        save = True; tokens = tokens[:-1]
    relation = None
    if tokens and tokens[-1].lower() in ("synonym", "antonym"):
        relation = tokens[-1].lower(); tokens = tokens[:-1]
    if tokens and tokens[-1].lower() == "save":  # allow `<word> save synonym` too
        save = True; tokens = tokens[:-1]
    word = " ".join(tokens).strip()

    # Instant ack: confirms the (new-build) handler fired and gives immediate feedback.
    # Everything after is wrapped so no failure can leave the DM silent. We send fresh
    # messages rather than edit — editing proved fragile ("message can't be edited").
    await message.reply_text(f"🔧 Принял: <b>{_html_escape(word)}</b>. Ищу в банке…",
                             parse_mode="HTML")
    try:
        await asyncio.to_thread(ensure_sprint_schema)
        item = await asyncio.to_thread(get_sprint_item_by_word, word, relation=relation)
        if not item:
            avail = await asyncio.to_thread(list_sprint_bank_words, relation=relation, limit=30)
            hint = ""
            if avail:
                words = " · ".join(f"{'🔴' if a['relation'] == 'antonym' else '🟢'} {_html_escape(a['wort'])}"
                                   for a in avail[:30])
                hint = f"\n\nЕсть в банке:\n{words}"
            else:
                hint = "\n\nБанк спринта пуст — сначала пул должен наполниться (ночной job/стартап)."
            await message.reply_text(
                f"В банке спринта нет слова «{_html_escape(word)}»"
                + (f" ({relation})" if relation else "")
                + "." + hint,
                parse_mode="HTML", disable_web_page_preview=True); return

        accepted = item.get("accepted") or []
        await message.reply_text(
            f"⏳ Гоняю пайплайн для <b>{_html_escape(str(item.get('wort')))}</b> "
            f"({'антонимы' if item.get('relation') == 'antonym' else 'синонимы'}, "
            f"{len(accepted)} правильных)…\nЭто минута-две — три модели по кругу.",
            parse_mode="HTML")

        from backend.sprint_distractors import build_trainer_distractors, trainer_json_from_result
        result = await build_trainer_distractors(
            target_word=str(item.get("wort")), relation=str(item.get("relation") or "synonym"),
            correct_pairs=accepted, hint_ru=str(item.get("hint_ru") or ""),
        )
        text = _fmt_distractor_preview(item, result)
        for chunk in _split_html_message(text):
            await message.reply_text(chunk, parse_mode="HTML", disable_web_page_preview=True)

        if save:
            if result.get("trainer_ready"):
                tj = trainer_json_from_result(result)
                await asyncio.to_thread(update_sprint_trainer_data, str(item.get("sprint_id")),
                                        trainer_json=tj, trainer_ready=True)
                await message.reply_text(
                    f"💾 Сохранено в банк: <b>{_html_escape(str(item.get('wort')))}</b> — "
                    f"{len(tj['distractors'])} дистракторов, {len(tj['correct_examples'])} примеров. "
                    f"Слово теперь доступно тренажёру.", parse_mode="HTML")
            else:
                await message.reply_text(
                    "⚠️ Не сохранил: слово не прошло гейт «≥2 чистых дистрактора». "
                    "Прогони ещё раз или возьми другое слово.")
    except Exception as exc:
        logging.warning("admin sprint distractors failed", exc_info=True)
        try:
            await message.reply_text(f"❌ Ошибка: <code>{_html_escape(str(exc))}</code>", parse_mode="HTML")
        except Exception:
            pass


from backend.quiz_leaderboard import (
    compute_quiz_leaderboard as _compute_quiz_leaderboard,
    get_leaderboard_rows_since as _get_leaderboard_rows_since,
)


def _build_group_daily_report(lb: dict, title: str | None, *, period: str = "day") -> str | None:
    leaders = lb.get("leaders") or []
    if not leaders:
        return None
    esc = lambda s: html.escape(str(s or ""))
    medal = lambda i: "🥇" if i == 0 else "🥈" if i == 1 else "🥉" if i == 2 else f"{i + 1}."
    champ = leaders[0]
    is_week = period == "week"
    period_paren = "итоги недели" if is_week else "итоги дня"
    champ_word   = "недели" if is_week else "дня"
    tasks_word   = "заданий недели" if is_week else "заданий дня"
    head = (
        f"🏁 <b>Групповой рейтинг — {esc(title)}</b>" if str(title or "").strip()
        else f"🏁 <b>Групповой рейтинг ({period_paren})</b>"
    )
    lines = [
        head,
        "<i>Только участники этой группы. Общий рейтинг по всем — в приложении.</i>",
        "",
        f"👥 Активных: <b>{lb.get('total_players', 0)}</b> · 🧩 заданий: <b>{lb.get('total_tasks', 0)}</b>",
        f"🏆 Чемпион {champ_word} в группе: <b>{esc(champ['name'])}</b> — {champ['points']} очк.",
        "",
    ]
    for i, l in enumerate(leaders[:5]):
        crown = "" if l.get("prize_eligible", True) else " ·💤"
        lines.append(f"{medal(i)} {esc(l['name'])} — {l['points']} очк. ({l['correct']}✓){crown}")
    mfp = int(lb.get("min_for_prize") or 0)
    if mfp:
        lines += ["", f"🏅 Призовые места — кто ответил ≥ {mfp} (≥50% {tasks_word})."]
    lines += ["", "🌍 Глобальный рейтинг и Кубок чемпиона — по кнопке ниже 👇"]
    return "\n".join(lines)


async def _dm_group_champion_fallback(context: CallbackContext, *, participants,
                                      poster, text, kb, served: set) -> int:
    """When a group champion post can't reach the GROUP chat (stale/migrated chat_id,
    bot kicked, missing rights), still deliver the same poster to that group's
    confirmed members in their DM. `served` dedups members shared across groups so
    nobody gets it twice in one run. Returns how many DMs went out."""
    dm = 0
    for uid in participants:
        uid = int(uid)
        if uid <= 0 or uid in served:
            continue
        try:
            if poster:
                m = await context.bot.send_photo(chat_id=uid, photo=io.BytesIO(poster),
                                                 caption=text, parse_mode="HTML", reply_markup=kb)
                await _preserve_system_message(m, "champion")
            else:
                await context.bot.send_message(chat_id=uid, text=text, parse_mode="HTML", reply_markup=kb)
            served.add(uid)
            dm += 1
        except Exception:
            logging.warning("champion DM fallback failed uid=%s", uid, exc_info=True)
    return dm


# Telegram errors that mean a group is gone for good (not a transient hiccup):
# the chat was deleted, the bot was kicked/blocked, or the group migrated to a new
# supergroup id. On these we retire the group's membership so its users become solo.
_DEAD_GROUP_SIGNS = (
    "chat not found", "group chat was deleted", "chat was upgraded",
    "group chat was upgraded", "bot was kicked", "bot is not a member",
    "not a member", "peer_id_invalid", "chat_id is empty", "the group chat was deleted",
)


def _is_dead_group_error(exc: Exception) -> bool:
    """True if `exc` from a group send means the group no longer exists / is unreachable
    permanently (vs. a transient network/timeout error worth retrying next run)."""
    try:
        from telegram.error import Forbidden, BadRequest
    except Exception:
        Forbidden = BadRequest = ()
    if Forbidden and isinstance(exc, Forbidden):
        return True
    msg = str(exc or "").lower()
    if BadRequest and isinstance(exc, BadRequest):
        return any(s in msg for s in _DEAD_GROUP_SIGNS)
    return any(s in msg for s in _DEAD_GROUP_SIGNS)


async def _send_group_daily_report_job(context: CallbackContext) -> None:
    """Evening champion-of-the-day, by audience:
      • GROUP chats → the group's champion poster + ranking button, into the chat.
      • dead groups → membership retired (deleted/kicked/migrated) so members reclassify.
      • SOLO users (not in any live group) who played today → the GLOBAL «кто лучший
        за день» грамота in DM (1-2-3 place + own rank via the ranking button).
    Personal "Итоги дня" stats stay in each user's DM (separate digest job)."""
    try:
        rows = await asyncio.to_thread(_get_leaderboard_rows_since, 24)
    except Exception:
        logging.warning("group daily report: fetch failed", exc_info=True)
        return
    if not rows:
        return
    user_ids = {int(r["user_id"]) for r in rows if r.get("user_id") is not None}
    raw_names = {int(r["user_id"]): str(r.get("name") or "") for r in rows if r.get("user_id") is not None}
    display_names = await _resolve_report_display_names(context, user_ids, raw_names)
    rows = [
        {**r, "name": display_names.get(int(r["user_id"])) or str(r.get("name") or "")}
        for r in rows
    ]
    # Group-scoped daily champion poster: DISABLED (2026-07-19). Replaced by the unified
    # daily group PULSE (backend_server._dispatch_daily_group_summary — tiny text: who
    # trained today + blame-free group streak + today's total). Posting this heavy poster
    # into the group too was a duplicate. The SOLO/global DM pass below is UNCHANGED —
    # group members are excluded from it via _collect_all_group_participant_ids, so nobody
    # is double-served.

    # Solo/global daily champion: users NOT in any live group who played today get the
    # GLOBAL "кто лучший за день" грамота in DM (1-2-3 place + their own rank via the
    # ranking button). This is what ex-group members now fall back to automatically.
    try:
        active_uids = {int(r["user_id"]) for r in rows if r.get("user_id") is not None}
        group_member_ids = await _collect_all_group_participant_ids(context)
        targets = await _collect_quiz_delivery_user_targets(context)
        solo_chat_ids: list[int] = []
        for t in targets or []:
            cid = int(t.get("chat_id") or 0)
            if cid <= 0:  # DM (private) chats only
                continue
            uids = [int(u) for u in (t.get("user_ids") or [])]
            if any(u in group_member_ids for u in uids):
                continue  # still a member of a live group → gets the group post
            if not any(u in active_uids for u in uids):
                continue  # didn't play today → don't DM a daily card
            solo_chat_ids.append(cid)
        if solo_chat_ids:
            solo_sent = await _post_champion_card(context, days=1, chat_ids=solo_chat_ids)
            logging.info("daily solo champion: sent=%d", solo_sent)
    except Exception:
        logging.warning("daily solo champion pass failed", exc_info=True)


def _build_champion_card(lb: dict, *, week_no: int, days: int) -> str | None:
    leaders = lb.get("leaders") or []
    if not leaders:
        return None
    medal = lambda i: "🥇" if i == 0 else "🥈" if i == 1 else "🥉" if i == 2 else f"{i + 1}."
    esc = lambda s: html.escape(str(s or "Student"))
    champ = leaders[0]
    period = "недели" if days == 7 else f"{days} дн."
    lines = [
        f"🏆🏆🏆  <b>ЧЕМПИОН {period.upper()} №{week_no}</b>  🏆🏆🏆",
        "",
        f"👑 <b>{esc(champ['name'])}</b>",
        f"🏅 {champ['points']} очков · {champ['correct']}/{champ['answered']} верно · {champ['golds']}× 🥇",
        "",
        "<b>📊 Топ игроков</b>",
    ]
    for i, l in enumerate(leaders[:7]):
        lines.append(f"{medal(i)} <b>{esc(l['name'])}</b> — {l['points']} очк. ({l['correct']}✓)")
    if len(leaders) > 7:
        lines.append("⋮")

    noms = []
    if lb.get("fastest"):
        f = lb["fastest"]
        noms.append(f"⚡ <b>Самый быстрый:</b> {esc(f['name'])} ({(f['ctime_sum'] / f['ctime_n'] / 1000):.1f} с в среднем)")
    if lb.get("accurate"):
        a = lb["accurate"]
        noms.append(f"🎯 <b>Самый точный:</b> {esc(a['name'])} ({round(a['correct'] / a['answered'] * 100)}%)")
    if lb.get("active"):
        ac = lb["active"]
        noms.append(f"🔥 <b>Самый активный:</b> {esc(ac['name'])} ({ac['answered']} заданий)")
    if noms:
        lines += ["", "✨ <b>Номинации</b>", *noms]
    lines += ["", f"🌍 Всего игроков: {lb.get('total_players', 0)} · заданий: {lb.get('total_tasks', 0)}",
              "Решай интерактивы — попади в топ! 🎮"]
    return "\n".join(lines)


async def _fetch_user_avatar_png(context: CallbackContext, user_id: int) -> bytes | None:
    """Best-effort: the user's Telegram profile photo as bytes (for the podium)."""
    try:
        photos = await context.bot.get_user_profile_photos(int(user_id), limit=1)
        if not photos or int(getattr(photos, "total_count", 0)) == 0 or not photos.photos:
            return None
        sizes = photos.photos[0]
        ph = sizes[min(len(sizes) - 1, 1)]  # a small/medium size is plenty for 104px
        f = await context.bot.get_file(ph.file_id)
        bio = io.BytesIO()
        await f.download_to_memory(bio)
        return bio.getvalue()
    except Exception:
        return None


async def _post_champion_card(context: CallbackContext, *, days: int, chat_ids: list[int] | None = None) -> int:
    rows = await asyncio.to_thread(_get_leaderboard_rows_since, days * 24)
    user_ids = {int(r["user_id"]) for r in (rows or []) if r.get("user_id") is not None}
    raw_names = {int(r["user_id"]): str(r.get("name") or "") for r in (rows or []) if r.get("user_id") is not None}
    display_names = await _resolve_report_display_names(context, user_ids, raw_names)
    rows = [
        {**r, "name": display_names.get(int(r["user_id"])) or str(r.get("name") or "")}
        for r in (rows or [])
    ]
    lb = _compute_quiz_leaderboard(rows or [])
    week_no = _get_quiz_schedule_now().isocalendar()[1]
    text = _build_champion_card(lb, week_no=week_no, days=days)
    if not text:
        return 0
    # Top-3 avatars for the podium (best-effort; falls back to initials).
    avatars: dict[int, bytes] = {}
    for ldr in (lb.get("leaders") or [])[:3]:
        av = await _fetch_user_avatar_png(context, int(ldr["user_id"]))
        if av:
            avatars[int(ldr["user_id"])] = av
    # Render the premium PNG poster (vector cup/podium). Falls back to the text card.
    poster = None
    try:
        from backend.champion_poster import render_champion_poster
        poster = await asyncio.to_thread(render_champion_poster, lb, week_no=week_no, days=days, avatars=avatars)
    except Exception:
        logging.warning("champion poster render failed", exc_info=True)
    champ = (lb.get("leaders") or [{}])[0]
    period_word = "недели" if days == 7 else ("дня" if days == 1 else f"{days} дн.")
    caption = (
        f"🏆 <b>Чемпион {period_word}</b>{'' if days == 1 else f' №{week_no}'} — "
        f"<b>{html.escape(str(champ.get('name') or ''))}</b>! 🎉\nРешай интерактивы — попади в топ 🎮"
    )
    if chat_ids is None:
        targets = await _collect_quiz_delivery_user_targets(context)
        chat_ids = [int(t.get("chat_id") or 0) for t in (targets or []) if int(t.get("chat_id") or 0)]
    kb = InlineKeyboardMarkup([[InlineKeyboardButton(
        text="🏅 Полный рейтинг", url=get_webapp_deeplink("lb" if days == 7 else f"lb{days}"))]])
    sent = 0
    for cid in chat_ids:
        try:
            if poster:
                champ_msg = await context.bot.send_photo(chat_id=int(cid), photo=io.BytesIO(poster),
                                             caption=caption, parse_mode="HTML", reply_markup=kb)
                await _preserve_system_message(champ_msg, "champion")  # winner keepsake, don't auto-delete
            else:
                await context.bot.send_message(chat_id=int(cid), text=text, parse_mode="HTML", reply_markup=kb)
            sent += 1
        except Exception:
            logging.warning("champion card: send failed chat_id=%s", cid, exc_info=True)
    return sent


async def _collect_all_group_participant_ids(context: CallbackContext) -> set[int]:
    """Union of confirmed participants across ALL known webapp group chats.
    Used to tell solo (non-group) users apart from group members."""
    ids: set[int] = set()
    try:
        groups = await asyncio.to_thread(list_known_webapp_group_chats, 500)
    except Exception:
        groups = []
    for g in groups or []:
        try:
            chat_id = int(g.get("chat_id") or 0)
        except Exception:
            continue
        if chat_id == 0:
            continue
        try:
            ids |= set(int(u) for u in await asyncio.to_thread(list_group_participants, chat_id))
        except Exception:
            continue
    return ids


async def _post_weekly_group_champions(context: CallbackContext, *, week_no: int) -> int:
    """Post each group's WEEKLY champion poster INTO the group, scoped to every
    member the bot has SEEN in that group (mirrors the daily group report, 7-day
    window; no button confirmation required). Outsiders / other-group users are
    never pulled in — the global ranking lives only behind the Mini-App button."""
    try:
        rows = await asyncio.to_thread(_get_leaderboard_rows_since, 7 * 24)
    except Exception:
        logging.warning("weekly group champion: fetch failed", exc_info=True)
        return 0
    if not rows:
        return 0
    user_ids = {int(r["user_id"]) for r in rows if r.get("user_id") is not None}
    raw_names = {int(r["user_id"]): str(r.get("name") or "") for r in rows if r.get("user_id") is not None}
    display_names = await _resolve_report_display_names(context, user_ids, raw_names)
    rows = [
        {**r, "name": display_names.get(int(r["user_id"])) or str(r.get("name") or "")}
        for r in rows
    ]
    try:
        groups = await asyncio.to_thread(list_known_webapp_group_chats, 500)
    except Exception:
        groups = []
    sent = 0
    dm_fallback = 0
    dead_groups = 0
    served: set[int] = set()  # members already reached this run (via group post or DM)
    for g in groups or []:
        try:
            chat_id = int(g.get("chat_id") or 0)
        except Exception:
            continue
        if chat_id == 0:
            continue
        try:
            participants = set(await asyncio.to_thread(list_group_participants, chat_id))
        except Exception:
            participants = set()
        if not participants:
            continue
        grows = [r for r in rows if int(r["user_id"]) in participants]
        if not grows:
            continue
        lb = _compute_quiz_leaderboard(grows)
        text = _build_group_daily_report(lb, g.get("chat_title"), period="week")
        if not text:
            continue
        kb = InlineKeyboardMarkup([[InlineKeyboardButton(
            text="🏅 Полный рейтинг", url=get_webapp_deeplink("lb"))]])
        poster = None
        try:
            avatars: dict[int, bytes] = {}
            for ldr in (lb.get("leaders") or [])[:3]:
                av = await _fetch_user_avatar_png(context, int(ldr["user_id"]))
                if av:
                    avatars[int(ldr["user_id"])] = av
            from backend.champion_poster import render_champion_poster
            poster = await asyncio.to_thread(
                render_champion_poster, lb, week_no=week_no, days=7, avatars=avatars,
                header="CHAMPION DER WOCHE", subtitle=f"№ {week_no}",
            )
        except Exception:
            logging.warning("weekly group champion: poster render failed chat_id=%s", chat_id, exc_info=True)
        try:
            if poster:
                champ_msg = await context.bot.send_photo(chat_id=chat_id, photo=io.BytesIO(poster),
                                             caption=text, parse_mode="HTML", reply_markup=kb)
                await _preserve_system_message(champ_msg, "champion")  # winner keepsake, don't auto-delete
            else:
                await context.bot.send_message(chat_id=chat_id, text=text, parse_mode="HTML", reply_markup=kb)
            sent += 1
            served |= {int(u) for u in participants}  # they saw it in the group
        except Exception as exc:
            if _is_dead_group_error(exc):
                # Group is gone → retire membership. Its members become solo and get
                # the GLOBAL weekly champion in DM via the solo pass in the caller.
                logging.warning("weekly group champion: group %s is dead (%s) → deactivating", chat_id, exc)
                try:
                    await asyncio.to_thread(deactivate_group_chat, chat_id)
                    dead_groups += 1
                except Exception:
                    logging.warning("deactivate_group_chat failed chat_id=%s", chat_id, exc_info=True)
            else:
                # Transient failure → DM the poster to members so they still get it now.
                logging.warning("weekly group champion send failed chat_id=%s — DM fallback", chat_id, exc_info=True)
                dm_fallback += await _dm_group_champion_fallback(
                    context, participants=participants, poster=poster, text=text, kb=kb, served=served)
    logging.info("weekly_group_champion sent=%d groups dm_fallback=%d dead_groups=%d", sent, dm_fallback, dead_groups)
    return sent


async def _send_mistake_review_reminders(context: CallbackContext) -> None:
    """Daily DM nudge: tell each user who has due 'работа над ошибками' items to
    review them (spaced repetition). Personal → straight to the user's DM."""
    if _is_quiet_hours_now():
        logging.info("quiet_hours: skip mistake review reminders")
        return
    try:
        from backend.database import list_users_with_due_mistakes
        users = await asyncio.to_thread(list_users_with_due_mistakes, min_count=1, limit=5000)
    except Exception:
        logging.warning("mistake reminders: list failed", exc_info=True)
        return
    kb = InlineKeyboardMarkup([[InlineKeyboardButton(
        "🧩 Разобрать ошибки", url=get_webapp_deeplink("ans_rv_0"))]])
    # Branded hero card (same for everyone) so the nudge stands out like other tasks.
    poster = None
    try:
        from backend.interactive_card import render_review_card
        poster = await asyncio.to_thread(render_review_card)
    except Exception:
        logging.warning("mistake reminder: card render failed", exc_info=True)
    sent = 0
    for u in users or []:
        uid = int(u.get("user_id") or 0)
        n = int(u.get("count") or 0)
        if uid <= 0 or n <= 0:
            continue
        caption = (
            f"🔁 <b>Работа над ошибками</b>\n\n"
            f"У тебя <b>{n}</b> на повтор — разбери их, пока не закрепились неправильно. "
            f"Это самый быстрый способ реально подтянуть грамматику 👇"
        )
        try:
            if poster:
                rev_msg = await context.bot.send_photo(chat_id=uid, photo=io.BytesIO(poster),
                                             caption=caption, parse_mode="HTML", reply_markup=kb)
            else:
                rev_msg = await context.bot.send_message(chat_id=uid, text=caption, parse_mode="HTML", reply_markup=kb)
            # Review has no per-dispatch id → key the inbox row by the day so the
            # daily card gets a ✅ once the user does any review work.
            try:
                day_id = int(_get_quiz_schedule_now().strftime("%Y%m%d"))
                await asyncio.to_thread(
                    record_interactive_inbox,
                    user_id=uid, kind="rv", dispatch_id=day_id, chat_id=uid,
                    telegram_message_id=int(rev_msg.message_id),
                    deeplink="ans_rv_0", title="🔁 Работа над ошибками",
                    keyboard_json=_inbox_kb_json(kb),
                )
            except Exception:
                logging.debug("review reminder: inbox record failed uid=%s", uid, exc_info=True)
            sent += 1
        except Exception:
            logging.warning("mistake reminder send failed uid=%s", uid, exc_info=True)
    logging.info("mistake_review_reminders sent=%d", sent)


