async def admin_review_makedue_command(update: Update, context: CallbackContext) -> None:
    """TEST: make YOUR review mistakes due right now (skip the 1-day SR wait).
    /review_makedue            → only your `artikel` mistakes
    /review_makedue all        → every format
    /review_makedue wofrage    → only that format (any format name works)
    Then open «🧩 Разобрать ошибки» (/review) to drill them immediately."""
    user = update.effective_user
    message = update.effective_message
    if not user or not message:
        return
    if not _is_admin_user(getattr(user, "id", None)):
        await message.reply_text("Admins only.")
        return
    args = [a.strip().lower() for a in (context.args or []) if a.strip()]
    if args and args[0] in ("all", "все", "всё"):
        fmt = None
    elif args:
        fmt = args[0]  # explicit format, e.g. wofrage / artikel / cloze
    else:
        fmt = "artikel"
    from backend.database import force_due_mistakes
    n = await asyncio.to_thread(force_due_mistakes, int(user.id), fmt=fmt)
    scope = "все форматы" if fmt is None else f"формат «{fmt}»"
    kb = InlineKeyboardMarkup([[InlineKeyboardButton(
        "🧩 Разобрать ошибки", url=get_webapp_deeplink("ans_rv_0"))]])
    await message.reply_text(
        f"✅ Готово: {n} ошибок ({scope}) созрели сейчас. Открой повторение 👇",
        reply_markup=kb,
    )


async def _send_weekly_champion_job(context: CallbackContext) -> None:
    """Weekly champion, split by audience:
      • GROUP chats  → a group-scoped poster (only that group's members).
      • SOLO users   → the GLOBAL champion poster in DM + button to the full
                       ranking (where their own place is highlighted).
    Group members are NOT also DM'd the global poster — they get the group one.
    """
    week_no = _get_quiz_schedule_now().isocalendar()[1]

    # 1) Group-scoped weekly poster: DISABLED (2026-07-19). Replaced by the unified weekly
    # group report (co-op "this week vs 4-week average" + merged standings), sent from
    # backend_server._dispatch_weekly_group_summary. Keeping two weekly group posts was a
    # duplicate. The SOLO global DM below is unchanged — solo users still get their recap.
    g_sent = 0

    # 2) Global poster to solo (non-group) users in their DM.
    s_sent = 0
    try:
        group_member_ids = await _collect_all_group_participant_ids(context)
        targets = await _collect_quiz_delivery_user_targets(context)
        solo_chat_ids: list[int] = []
        for t in targets:
            cid = int(t.get("chat_id") or 0)
            if cid <= 0:  # private DM chats only (groups have negative ids)
                continue
            uids = [int(u) for u in (t.get("user_ids") or [])]
            if any(u in group_member_ids for u in uids):
                continue  # this user already gets the group poster
            solo_chat_ids.append(cid)
        if solo_chat_ids:
            s_sent = await _post_champion_card(context, days=7, chat_ids=solo_chat_ids)
    except Exception:
        logging.warning("weekly_champion solo pass failed", exc_info=True)

    logging.info("weekly_champion posted: groups=%d solos=%d", g_sent, s_sent)


