async def adjektiv_battle_command(update: Update, context: CallbackContext) -> None:
    """Create an Adjektiv Sprint battle (Pro only) + broadcast the invite. /adjbattle"""
    user = update.effective_user
    message = update.effective_message
    if not user or not message:
        return
    if not await asyncio.to_thread(is_user_pro, int(user.id)):
        await message.reply_text(
            "⚔️ <b>Батлы создаёт Premium</b>\n\n"
            "Бросить вызов другим может только пользователь с «Полным доступом». "
            "Но <b>участвовать</b> можешь и ты — просто дождись приглашения "
            "от друга с Premium и играй наравне со всеми. 🛡",
            parse_mode="HTML")
        return
    from backend.database import (
        create_adjektiv_battle_with_set, add_adjektiv_sprint_battle_member,
    )
    # Battle set is built deterministically (rule engine) — no LLM top-up needed.
    deadline = datetime.now(ZoneInfo("Europe/Vienna")).replace(hour=23, minute=59, second=0, microsecond=0)
    creator_name = _display_user_name(user)
    bid, _set_id = await asyncio.to_thread(
        create_adjektiv_battle_with_set, creator_user_id=int(user.id),
        creator_name=creator_name, deadline=deadline)
    if not bid:
        await message.reply_text("Не удалось собрать набор батла — пул прилагательных пуст. Попробуй позже.")
        return
    await asyncio.to_thread(add_adjektiv_sprint_battle_member,
                            battle_id=bid, user_id=int(user.id), user_name=creator_name)
    # Reply to the creator INSTANTLY with the play buttons; the heavy part (render
    # the card + send invites to every user) runs in the background so the button
    # never makes the creator wait.
    play_kb = InlineKeyboardMarkup([
        [InlineKeyboardButton("⚔️ Играть свой батл (до 23:59)", url=get_webapp_deeplink(f"ans_adb_{bid}"))],
        [InlineKeyboardButton("📋 Мои батлы", url=get_webapp_deeplink("ans_adbl_0"))],
    ])
    instant_cap = (f"⚔️ <b>Твой Adjektiv-батл #{bid} брошен!</b>\n"
                   f"15 ситуаций на окончания прилагательных · дедлайн 23:59\n"
                   f"📨 Рассылаю приглашения соперникам…")
    status_mid = await _send_battle_status(context, chat_id=int(message.chat_id),
                                           caption=instant_cap, kb=play_kb)
    if _set_id:
        asyncio.create_task(_pin_battle_play_message(
            context, user_id=int(user.id), set_id=str(_set_id),
            chat_id=int(message.chat_id), message_id=status_mid, kind="adjektiv"))
    # Nudge the creator too if they don't get around to playing their own battle.
    asyncio.create_task(_schedule_battle_auto_nudge(
        kind="adjektiv", battle_id=bid, user_id=int(user.id), deadline=deadline))
    asyncio.create_task(_broadcast_adjektiv_battle_invites(
        context, battle_id=bid, creator_id=int(user.id), creator_name=creator_name,
        status_chat_id=int(message.chat_id), status_msg_id=status_mid))


async def _broadcast_adjektiv_battle_invites(context: CallbackContext, *, battle_id: int,
                                             creator_id: int, creator_name: str,
                                             status_chat_id: int, status_msg_id: int,
                                             target_ids: list[int] | None = None) -> int:
    """Off-critical-path: render the invite card once and DM every allowed user
    (or just ``target_ids`` when the wizard picked specific players), then land the
    creator's status as a hero-photo card. Returns the effective status message id
    (may change when a text wizard message is replaced by the photo card)."""
    invite_text = (
        f"⚔️ <b>{html.escape(creator_name)}</b> зовёт на <b>Adjektiv Sprint</b> батл!\n"
        f"15 ситуаций на окончания прилагательных, по 5 сек. Играй когда удобно <b>до 23:59</b>. Прими вызов:"
    )
    join_kb = InlineKeyboardMarkup([[InlineKeyboardButton(
        "✅ Принять вызов", callback_data=f"adb_join:{battle_id}")]])
    if target_ids is not None:
        targets = list(target_ids)
    else:
        try:
            targets = await asyncio.to_thread(list_allowed_telegram_user_ids)
        except Exception:
            targets = []
    sent, blocked, error = await _deliver_battle_invites(
        context, creator_id=int(creator_id), targets=list(targets),
        caption=invite_text, kb=join_kb, kind="adjektiv")
    play_kb = InlineKeyboardMarkup([
        [InlineKeyboardButton("⚔️ Играть свой батл (до 23:59)", url=get_webapp_deeplink(f"ans_adb_{battle_id}"))],
        [InlineKeyboardButton("📋 Мои батлы", url=get_webapp_deeplink("ans_adbl_0"))],
    ])
    final_cap = (f"⚔️ <b>Adjektiv-батл #{battle_id} в бою!</b>\n"
                 f"15 ситуаций на окончания прилагательных · дедлайн 23:59\n"
                 f"{_battle_delivery_caption_line(sent, blocked, error)}"
                 f"Сыграй первым — задай темп! 👇")
    return await _present_battle_status(context, chat_id=int(status_chat_id),
                                        old_msg_id=int(status_msg_id),
                                        caption=final_cap, kb=play_kb)


async def _create_and_broadcast_adjektiv_wizard(context: CallbackContext, *, creator_id: int,
                                                creator_name: str, ind_targets,
                                                status_chat_id: int, status_msg_id: int) -> None:
    """Wizard path for Adjektiv battles: create the battle + set, add the creator,
    then broadcast invites to the picked players (or everyone), editing the wizard
    status message when done. Mirrors _create_and_broadcast_artikel_wizard."""
    from backend.database import (
        create_adjektiv_battle_with_set, add_adjektiv_sprint_battle_member,
    )
    deadline = datetime.now(ZoneInfo("Europe/Vienna")).replace(hour=23, minute=59, second=0, microsecond=0)
    try:
        bid, set_id = await asyncio.to_thread(
            create_adjektiv_battle_with_set, creator_user_id=int(creator_id),
            creator_name=creator_name, deadline=deadline)
    except Exception:
        logging.warning("adjektiv wizard create failed creator=%s", creator_id, exc_info=True)
        bid, set_id = None, None
    if not bid:
        try:
            await context.bot.edit_message_text(
                chat_id=status_chat_id, message_id=status_msg_id,
                text="⚠️ Не удалось собрать набор батла — пул прилагательных пуст. Попробуй позже.")
        except Exception:
            pass
        return
    await asyncio.to_thread(add_adjektiv_sprint_battle_member,
                            battle_id=bid, user_id=int(creator_id), user_name=creator_name)
    eff_msg_id = await _broadcast_adjektiv_battle_invites(
        context, battle_id=bid, creator_id=int(creator_id), creator_name=creator_name,
        status_chat_id=int(status_chat_id), status_msg_id=int(status_msg_id),
        target_ids=ind_targets)
    if set_id:
        await _pin_battle_play_message(context, user_id=int(creator_id), set_id=str(set_id),
                                       chat_id=int(status_chat_id), message_id=int(eff_msg_id),
                                       kind="adjektiv")
    await _schedule_battle_auto_nudge(kind="adjektiv", battle_id=bid,
                                      user_id=int(creator_id), deadline=deadline)


async def adjektiv_battle_join_callback(update: Update, context: CallbackContext) -> None:
    """Accept an Adjektiv battle invite (adb_join:<id>) → join + play button."""
    q = update.callback_query
    if not q or not q.from_user:
        return
    try:
        bid = int(str(q.data or "").split(":", 1)[1])
    except (ValueError, IndexError):
        await q.answer()
        return
    from backend.database import get_adjektiv_sprint_battle, add_adjektiv_sprint_battle_member
    battle = await asyncio.to_thread(get_adjektiv_sprint_battle, bid)
    if (not battle or str(battle.get("status")) != "open"
            or (battle.get("deadline") and battle["deadline"] <= datetime.now(ZoneInfo("UTC")))):
        await q.answer("Этот батл уже закрыт.", show_alert=True)
        return
    name = _display_user_name(q.from_user)
    await asyncio.to_thread(add_adjektiv_sprint_battle_member,
                            battle_id=bid, user_id=int(q.from_user.id), user_name=name)
    await q.answer("Ты в батле! ⚔️")
    # Release the accepter instantly: offer play-now / remind-later, then ping the
    # creator OFF the critical path (same pattern as the Artikel battle).
    kb = InlineKeyboardMarkup([
        [InlineKeyboardButton("⚔️ Участвовать сейчас", url=get_webapp_deeplink(f"ans_adb_{bid}"))],
        [InlineKeyboardButton("⏰ Напомнить позже", callback_data=f"adb_later:{bid}")],
    ])
    await _edit_battle_invite(q, "✅ Вызов принят! Играй сейчас или запланируй на потом 👇", kb)
    set_id = str(battle.get("set_id") or "")
    if q.message and set_id:
        asyncio.create_task(_pin_battle_play_message(
            context, user_id=int(q.from_user.id), set_id=set_id,
            chat_id=int(q.message.chat.id), message_id=int(q.message.message_id), kind="adjektiv"))
    # Start the "не забыл про батл?" nudge loop (~3h) for this member until they play.
    asyncio.create_task(_schedule_battle_auto_nudge(
        kind="adjektiv", battle_id=bid, user_id=int(q.from_user.id),
        deadline=battle.get("deadline")))
    creator_id = int(battle.get("creator_user_id") or 0)
    if creator_id and creator_id != int(q.from_user.id):
        asyncio.create_task(_notify_creator_accepted_capped(
            context, kind="adjektiv", battle_id=bid,
            creator_id=creator_id, accepter_name=name))


async def adjektiv_battle_later_callback(update: Update, context: CallbackContext) -> None:
    """adb_later:<id> → show preset reminder times (mirror of the Artikel picker)."""
    q = update.callback_query
    if not q:
        return
    try:
        bid = int(str(q.data or "").split(":", 1)[1])
    except (ValueError, IndexError):
        await q.answer(); return
    kb = InlineKeyboardMarkup([
        [InlineKeyboardButton("➕1 час", callback_data=f"adb_rem:{bid}:60"),
         InlineKeyboardButton("➕2 часа", callback_data=f"adb_rem:{bid}:120")],
        [InlineKeyboardButton("➕3 часа", callback_data=f"adb_rem:{bid}:180"),
         InlineKeyboardButton("🌆 в 21:00", callback_data=f"adb_rem:{bid}:at21")],
        [InlineKeyboardButton("◀️ Назад", callback_data=f"adb_join:{bid}")],
    ])
    await _edit_battle_invite(q, "⏰ Когда напомнить о батле? (батл закроется в 23:59)", kb)
    await q.answer()


async def adjektiv_battle_remind_callback(update: Update, context: CallbackContext) -> None:
    """adb_rem:<id>:<code> → schedule a reminder before the deadline."""
    q = update.callback_query
    if not q or not q.from_user:
        return
    parts = str(q.data or "").split(":")
    if len(parts) != 3:
        await q.answer(); return
    try:
        bid = int(parts[1])
    except ValueError:
        await q.answer(); return
    code = parts[2]
    tz = ZoneInfo("Europe/Vienna")
    now = datetime.now(tz)
    if code == "at21":
        remind_at = now.replace(hour=21, minute=0, second=0, microsecond=0)
    else:
        try:
            remind_at = now + timedelta(minutes=int(code))
        except ValueError:
            await q.answer(); return
    from backend.database import get_adjektiv_sprint_battle
    battle = await asyncio.to_thread(get_adjektiv_sprint_battle, bid)
    deadline = battle.get("deadline") if battle else None
    if remind_at <= now:
        await q.answer("Это время уже прошло 🙂", show_alert=True); return
    if deadline and remind_at >= deadline:
        await q.answer("Не успеть — батл закроется в 23:59. Лучше сыграй сейчас!", show_alert=True)
        return
    await asyncio.to_thread(schedule_article_battle_reminder,
                            user_id=int(q.from_user.id), battle_id=bid,
                            remind_at=remind_at, kind="adjektiv")
    hhmm = remind_at.strftime("%H:%M")
    await q.answer(f"⏰ Напомню в {hhmm}")
    kb = InlineKeyboardMarkup([[InlineKeyboardButton(
        "⚔️ Всё же сыграть сейчас", url=get_webapp_deeplink(f"ans_adb_{bid}"))]])
    await _edit_battle_invite(q, f"⏰ Напомню в <b>{hhmm}</b>. До встречи на батле! ⚔️", kb)


async def _close_adjektiv_sprint_battles_job(context: CallbackContext) -> None:
    """Close only Adjektiv battles (kept for manual/standalone use)."""
    results = await _collect_battle_results(context, "adjektiv")
    await _flush_battle_results(context, results)
    if results:
        logging.info("adjektiv battles closed: %s", len(results))


