SPRINT_POOL_TARGET = max(3, int((os.getenv("SPRINT_POOL_TARGET") or "6").strip() or "6"))
SPRINT_COOLDOWN_DAYS = max(7, int((os.getenv("SPRINT_COOLDOWN_DAYS") or "21").strip() or "21"))


def _sprint_enabled() -> bool:
    return (os.getenv("SPRINT_ENABLED") or "true").strip().lower() not in ("0", "false", "no")


async def _sprint_topup(relation: str, want: int) -> int:
    """Generate up to `want` ready sprint items (rich accepted list) into the bank."""
    if want <= 0:
        return 0
    from backend.openai_manager import run_generate_aufgabe
    fmt = "synonym_sprint" if relation == "synonym" else "antonym_sprint"
    min_accepted = 8 if relation == "synonym" else 5
    try:
        items = await run_generate_aufgabe(fmt, count=max(2, want), level="B2")
    except Exception:
        logging.warning("sprint_topup: generation failed relation=%s", relation, exc_info=True)
        return 0
    from backend.answer_eval import accepted_pairs
    made = 0
    for it in (items or []):
        wort = str((it or {}).get("wort") or "").strip()
        pairs = accepted_pairs((it or {}).get("accepted"))  # [{de, ru}]
        if not wort or len(pairs) < min_accepted:
            continue
        slug = re.sub(r"[^a-z0-9]+", "_", wort.lower()).strip("_")[:40]
        sprint_id = f"sp_{relation}_{slug}"
        try:
            await asyncio.to_thread(upsert_sprint_item, {
                "sprint_id": sprint_id, "relation": relation, "wort": wort, "accepted": pairs,
                "erklaerung": str((it or {}).get("erklaerung") or ""),
                "tip": str((it or {}).get("tip") or ""),
                "hint_ru": str((it or {}).get("hint_ru") or ""), "level": "B2",
            })
            made += 1
        except Exception:
            logging.warning("sprint_topup: upsert failed id=%s", sprint_id, exc_info=True)
    if made:
        logging.info("sprint_topup relation=%s made=%s", relation, made)
    return made


async def prepare_sprint_pool_job(context: CallbackContext) -> None:
    """Startup + nightly: keep both sprint pools topped up."""
    try:
        await asyncio.to_thread(ensure_sprint_schema)
        for relation in ("synonym", "antonym"):
            have = await asyncio.to_thread(count_available_sprint_items, relation=relation, cooldown_days=0)
            if have < SPRINT_POOL_TARGET:
                await _sprint_topup(relation, SPRINT_POOL_TARGET - have + 1)
        logging.info("sprint_pool_job done")
    except Exception:
        logging.warning("sprint_pool_job failed", exc_info=True)


# How many words to build trainer data for per nightly run. The pipeline is ~12 full-
# model calls per word (setter + prosecutors + judge + examples), so we cap and drain the
# backlog over several nights rather than spiking cost/time in one run.
SPRINT_TRAINER_BUILD_PER_RUN = max(1, int((os.getenv("SPRINT_TRAINER_BUILD_PER_RUN") or "6").strip() or "6"))


async def _build_one_trainer_word(item: dict) -> str:
    """Build + store trainer data for one bank word. Returns a short status string.
    Stores even when the word misses the ≥2 gate (trainer_ready=False) so it is not
    rebuilt every night; only a TOTAL generation failure (transient) is left for retry."""
    from backend.sprint_distractors import build_trainer_distractors, trainer_json_from_result
    wort = str(item.get("wort") or "")
    result = await build_trainer_distractors(
        target_word=wort, relation=str(item.get("relation") or "synonym"),
        correct_pairs=item.get("accepted") or [], hint_ru=str(item.get("hint_ru") or ""),
    )
    if int((result.get("counts") or {}).get("generated") or 0) == 0:
        return f"{wort}: генерация пуста — оставил на ретрай"
    tj = trainer_json_from_result(result)
    await asyncio.to_thread(update_sprint_trainer_data, str(item.get("sprint_id")),
                            trainer_json=tj, trainer_ready=bool(result.get("trainer_ready")))
    flag = "✅" if result.get("trainer_ready") else "⚠️<2"
    return f"{wort}: {flag} {len(tj['distractors'])}д/{len(tj['correct_examples'])}пр"


async def build_sprint_trainer_job(context: CallbackContext, *, limit: int | None = None) -> list[str]:
    """Nightly (03:40): build trainer distractors + examples for bank words that don't
    have them yet, capped per run. Heavy LLM work — pool-build time only, off the hot
    path. Returns per-word status lines (for the manual admin trigger)."""
    statuses: list[str] = []
    try:
        await asyncio.to_thread(ensure_sprint_schema)
        cap = int(limit) if limit else SPRINT_TRAINER_BUILD_PER_RUN
        words = await asyncio.to_thread(list_sprint_words_needing_trainer, limit=cap)
        for item in words:
            try:
                statuses.append(await _build_one_trainer_word(item))
            except Exception:
                logging.warning("build_sprint_trainer_job: word failed wort=%s",
                                item.get("wort"), exc_info=True)
                statuses.append(f"{item.get('wort')}: ❌ ошибка")
        logging.info("build_sprint_trainer_job done built=%d", len(statuses))
    except Exception:
        logging.warning("build_sprint_trainer_job failed", exc_info=True)
    return statuses


async def send_sprint_to_chat(context: CallbackContext, *, entry: dict, relation: str,
                              slot_date, slot_hour: int, chat_id: int, target_user_id: int) -> bool:
    try:
        dispatch_id = await asyncio.to_thread(
            create_sprint_dispatch, sprint_id=str(entry["sprint_id"]), relation=relation,
            slot_date=slot_date, slot_hour=int(slot_hour),
            target_user_id=int(target_user_id), chat_id=int(chat_id),
        )
    except Exception:
        logging.warning("sprint_send: dispatch insert failed chat=%s", chat_id, exc_info=True)
        return False
    if dispatch_id is None:
        return False  # duplicate slot suppressed
    title = "Синонимы-спринт" if relation == "synonym" else "Антонимы-спринт"
    word_kind = "синонимов" if relation == "synonym" else "антонимов"
    emoji = "🟢" if relation == "synonym" else "🔴"
    hint = f" _{entry.get('hint_ru')}_" if entry.get("hint_ru") else ""
    caption = (
        f"{emoji} *{title} · B2+*\n\n"
        f"Слово: *{entry.get('wort')}*{hint}\n\n"
        f"За *60 секунд* напиши как можно больше {word_kind}!\n"
        f"🏆 Победитель — у кого больше правильных."
    )
    caption = _append_free_pro_teaser(caption, chat_id)
    keyboard = InlineKeyboardMarkup([[InlineKeyboardButton(
        "⚡ Играть (60 секунд)", url=get_webapp_deeplink(f"ans_sp_{dispatch_id}"))]])
    poster = None
    try:
        from backend.interactive_card import render_sprint_relation_card
        poster = await asyncio.to_thread(render_sprint_relation_card, relation)
    except Exception:
        logging.warning("sprint_send: card render failed chat=%s", chat_id, exc_info=True)
    try:
        if poster:
            msg = await context.bot.send_photo(
                chat_id=int(chat_id), photo=io.BytesIO(poster),
                caption=caption, parse_mode="Markdown", reply_markup=keyboard)
        else:
            msg = await context.bot.send_message(
                chat_id=int(chat_id), text=caption, parse_mode="Markdown", reply_markup=keyboard)
    except Exception as exc:
        logging.warning("sprint_send failed chat=%s: %s", chat_id, exc)
        return False
    try:
        await asyncio.to_thread(update_sprint_dispatch_message_id, dispatch_id, telegram_message_id=int(msg.message_id))
    except Exception:
        pass
    return True


# ── Synonym/Antonym recognition TRAINER delivery (the rail: trainer today → sprint +3d)
TRAINER_SLOT_TIMES = {(11, 0): "synonym", (16, 0): "antonym"}  # 1×/day each
# Second pass of the SAME training the NEXT day (spaced repetition): free to send (the
# game is already built), optional for the learner, and a BONUS — it never eats one of
# the daily N. The rail is untouched: the sprint still comes trainer_sent_date + 3 days,
# and it only requires the FIRST training, never this one.
TRAINER_REPEAT_SLOT_TIMES = {(13, 0): "synonym", (18, 0): "antonym"}
TRAINER_COOLDOWN_DAYS = max(7, int((os.getenv("TRAINER_COOLDOWN_DAYS") or "21").strip() or "21"))


def _trainer_enabled() -> bool:
    # OFF by default: nothing goes to users until the owner sets TRAINER_ENABLED=1.
    return (os.getenv("TRAINER_ENABLED") or "").strip().lower() in ("1", "true", "yes", "on")


async def send_trainer_to_chat(context: CallbackContext, *, entry: dict, relation: str,
                               slot_date, slot_hour: int, chat_id: int, target_user_id: int,
                               repeat: bool = False) -> bool:
    try:
        dispatch_id = await asyncio.to_thread(
            create_trainer_dispatch, sprint_id=str(entry["sprint_id"]),
            slot_date=slot_date, slot_hour=int(slot_hour),
            target_user_id=int(target_user_id), chat_id=int(chat_id),
        )
    except Exception:
        logging.warning("trainer_send: dispatch insert failed chat=%s", chat_id, exc_info=True)
        return False
    if dispatch_id is None:
        return False  # duplicate slot suppressed
    rel_ru = "синонимов" if relation == "synonym" else "антонимов"
    emoji = "🟢" if relation == "synonym" else "🔴"
    hint = f" _{entry.get('hint_ru')}_" if entry.get("hint_ru") else ""
    if repeat:
        caption = (
            f"🔁 *Повтор: тренировка {rel_ru}*\n\n"
            f"Слово: *{entry.get('wort')}*{hint}\n\n"
            f"Вчера ты его уже разбирал — второй заход на следующий день закрепляет лучше всего.\n"
            f"Это подарок сверх дневного плана: хочешь — играй, не хочешь — пропусти. "
            f"Послезавтра слово вернётся в спринте 🔥"
        )
    else:
        caption = (
            f"{emoji} *Тренировка {rel_ru}*\n\n"
            f"Слово: *{entry.get('wort')}*{hint}\n\n"
            f"Выбирай верный вариант из карточек — а через 3 дня это слово вернётся в спринте 🔥"
        )
    caption = _append_free_pro_teaser(caption, chat_id)
    keyboard = InlineKeyboardMarkup([[InlineKeyboardButton(
        "🔁 Пройти ещё раз" if repeat else "🎯 Открыть тренажёр",
        url=get_webapp_deeplink(f"ans_tr_{dispatch_id}"))]])
    poster = None
    try:
        from backend.interactive_card import render_trainer_relation_card
        poster = await asyncio.to_thread(render_trainer_relation_card, relation)
    except Exception:
        logging.warning("trainer_send: card render failed chat=%s", chat_id, exc_info=True)
    try:
        if poster:
            msg = await context.bot.send_photo(
                chat_id=int(chat_id), photo=io.BytesIO(poster),
                caption=caption, parse_mode="Markdown", reply_markup=keyboard)
        else:
            msg = await context.bot.send_message(
                chat_id=int(chat_id), text=caption, parse_mode="Markdown", reply_markup=keyboard)
    except Exception as exc:
        logging.warning("trainer_send failed chat=%s: %s", chat_id, exc)
        return False
    try:
        await asyncio.to_thread(update_trainer_dispatch_message_id, dispatch_id, telegram_message_id=int(msg.message_id))
    except Exception:
        pass
    # Ведомость дня. Первая тренировка — ОДНО из дневных заданий (make_rotation_gated),
    # значит факт выдачи обязан быть записан: по этой таблице «Следующее задание»
    # считает, сколько из дневного лимита уже потрачено. Без записи слот выглядит
    # неизрасходованным и человек получает лишнее задание сверх лимита.
    # Повтор на следующий день — подарок сверх плана (make_bonus_gated), он лимит не
    # тратит, поэтому в ведомость НЕ пишется.
    if not repeat and int(chat_id) == int(target_user_id):  # DM feed only
        try:
            await asyncio.to_thread(
                record_interactive_inbox,
                user_id=int(target_user_id), kind="tr", dispatch_id=int(dispatch_id),
                chat_id=int(chat_id), telegram_message_id=int(msg.message_id),
                deeplink=f"ans_tr_{dispatch_id}", title=f"{emoji} Тренировка {rel_ru}",
                keyboard_json=_inbox_kb_json(keyboard),
            )
        except Exception:
            logging.warning("trainer_send: inbox record failed dispatch_id=%s", dispatch_id, exc_info=True)
    return True


async def _send_scheduled_trainer(context: CallbackContext, relation: str,
                                  repeat: bool = False) -> None:
    """Daily trainer. `repeat=False` = the fresh word (counted rotation slot, stamps the
    rail). `repeat=True` = the SAME word one day later — a bonus second pass: already
    built, so it costs nothing, it doesn't move the rail, and the sprint never requires
    it. It goes only to the people who actually got yesterday's first pass."""
    if _is_quiet_hours_now():
        logging.info("quiet_hours: skip trainer")
        return
    if not _trainer_enabled():
        return
    slot_now = _get_quiz_schedule_now()
    slot_date = slot_now.date()
    slot_hour = int(slot_now.hour) * 100 + int(slot_now.minute)
    if repeat:
        entry = await asyncio.to_thread(
            pick_repeat_trainer, relation=relation, sent_date=slot_date - timedelta(days=1))
        if not entry:
            logging.info("trainer_repeat: nothing was trained yesterday relation=%s", relation)
            return
    else:
        entry = await asyncio.to_thread(pick_next_trainer, relation=relation, cooldown_days=TRAINER_COOLDOWN_DAYS)
        if not entry:
            logging.info("trainer_sched: no trainer-ready word relation=%s", relation)
            return
    targets = await _collect_quiz_delivery_user_targets(context)
    if not targets:
        return
    # The repeat is a REPEAT: only for DM users who received the first pass (groups have
    # no per-user tracking → exempt, same as the sprint rail gate).
    first_pass_recipients = (await asyncio.to_thread(
        get_trainer_recipient_ids, str(entry["sprint_id"]), since_days=2)) if repeat else set()
    sent = 0
    skipped = 0
    for t in targets:
        cid = int(t.get("chat_id") or 0)
        if cid == 0:
            continue
        if repeat and cid > 0 and cid not in first_pass_recipients:
            skipped += 1
            continue
        if await send_trainer_to_chat(context, entry=entry, relation=relation, slot_date=slot_date,
                                      slot_hour=slot_hour, chat_id=cid, target_user_id=cid,
                                      repeat=repeat):
            sent += 1
    if sent > 0:
        # Stamp the rail: the sprint picks this word `trainer_sent_date` + 3 days later.
        # The repeat passes sent_date=None → the anchor stays on the first pass.
        await asyncio.to_thread(mark_trainer_sent, str(entry["sprint_id"]),
                                sent_date=None if repeat else slot_date)
    logging.info("trainer_sent relation=%s repeat=%s sent=%s skipped=%s word=%s",
                 relation, repeat, sent, skipped, entry.get("wort"))


async def _admin_send_trainer_command(update: Update, context: CallbackContext) -> None:
    """/admin_send_trainer [synonym|antonym] [repeat] — preview the DAILY trainer message:
    auto-picks the next trainer-ready word and sends the card ONLY to you (no broadcast,
    no rail stamp). `repeat` previews the next-day second pass (bonus, optional copy).
    For the real broadcast, set TRAINER_ENABLED=1 (nightly cron)."""
    user = update.effective_user; message = update.effective_message
    if not user or not message:
        return
    if not _can_use_image_quiz_test_commands(getattr(user, "id", None)):
        await message.reply_text("Allowed users only."); return
    args = [a.strip().lower() for a in (context.args or [])]
    repeat = "repeat" in args
    rel_args = [a for a in args if a != "repeat"]
    relation = (rel_args[0] if rel_args else "synonym")
    if relation not in ("synonym", "antonym"):
        await message.reply_text("Использование: /admin_send_trainer [synonym|antonym] [repeat]"); return
    await asyncio.to_thread(ensure_sprint_schema)
    await asyncio.to_thread(ensure_trainer_schema)
    entry = await asyncio.to_thread(pick_next_trainer, relation=relation, cooldown_days=0)
    if not entry:
        await message.reply_text(
            f"Нет готовых слов тренажёра ({relation}). Собери: /admin_build_trainers."); return
    now = _get_quiz_schedule_now()
    slot_hour = int(now.hour) * 10000 + int(now.minute) * 100 + int(now.second)  # unique-ish preview
    ok = await send_trainer_to_chat(context, entry=entry, relation=relation, slot_date=now.date(),
                                    slot_hour=slot_hour, chat_id=int(message.chat_id),
                                    target_user_id=int(user.id), repeat=repeat)
    await message.reply_text(
        f"{'✅ Отправил превью' if ok else '❌ Не отправил'}: <b>{_html_escape(str(entry.get('wort')))}</b> "
        f"({'повтор' if repeat else 'первый заход'}, без рассылки и без отметки рельса).",
        parse_mode="HTML")


async def _send_scheduled_sprint(context: CallbackContext, relation: str) -> None:
    if _is_quiet_hours_now():
        logging.info("quiet_hours: skip sprint")
        return
    if not _sprint_enabled():
        return
    slot_now = _get_quiz_schedule_now()
    slot_date = slot_now.date()
    slot_hour = int(slot_now.hour) * 100 + int(slot_now.minute)
    # THE RAIL: prefer the word trained 3 days ago (so the trainer prepares the learner
    # for exactly this sprint). Falls back to the normal cooldown rotation — until the
    # trainer starts sending (TRAINER_ENABLED), the rail is empty and this is a no-op.
    entry = await asyncio.to_thread(pick_rail_sprint, relation=relation, target_date=slot_date, lag_days=3)
    if entry:
        logging.info("sprint_rail hit relation=%s word=%s", relation, entry.get("wort"))
    if not entry:
        entry = await asyncio.to_thread(pick_next_sprint, relation=relation, cooldown_days=SPRINT_COOLDOWN_DAYS)
    if not entry:
        await _sprint_topup(relation, SPRINT_POOL_TARGET)
        entry = await asyncio.to_thread(pick_next_sprint, relation=relation, cooldown_days=SPRINT_COOLDOWN_DAYS)
    if not entry:
        await _alert_admin_interactive(context, f"⚠️ Sprint «{relation}»: пул пуст, не отправлено.", throttle_key=f"sprint_empty_{relation}")
        return
    targets = await _collect_quiz_delivery_user_targets(context)
    if not targets:
        return
    # LEARNING-FLOW GATE (ALL DM users, Free AND Pro — it's pedagogy, not a paywall):
    # the sprint is RECALL, so it only goes to someone who got its trainer (RECOGNITION)
    # ~3 days earlier. A gated user simply doesn't receive THIS sprint slot (no dynamic
    # refill) — but the rail preference makes the sprint word == the just-trained word, so
    # active users almost always have the prep and rarely hit the gate. Groups are exempt
    # (no per-user trainer tracking). Active only while the trainer runs (TRAINER_ENABLED).
    apply_rail_gate = _trainer_enabled()
    trainer_recipients = (await asyncio.to_thread(
        get_trainer_recipient_ids, str(entry["sprint_id"]), since_days=5)) if apply_rail_gate else set()
    sent = 0
    gated = 0
    for t in targets:
        cid = int(t.get("chat_id") or 0)
        if cid == 0:
            continue
        if apply_rail_gate and cid > 0 and cid not in trainer_recipients:  # DM: prep required
            gated += 1
            continue
        if await send_sprint_to_chat(context, entry=entry, relation=relation, slot_date=slot_date,
                                     slot_hour=slot_hour, chat_id=cid, target_user_id=cid):
            sent += 1
    if sent > 0:
        await asyncio.to_thread(mark_sprint_sent, str(entry["sprint_id"]))
    logging.info("sprint_sent relation=%s sent=%s gated_free=%s word=%s", relation, sent, gated, entry.get("wort"))


async def admin_clearsprint_command(update: Update, context: CallbackContext) -> None:
    """Flush the sprint bank and regenerate (so accepted carries per-word RU).
    /admin_clearsprint [synonym|antonym]"""
    user = update.effective_user
    message = update.effective_message
    if not user or not message:
        return
    if not _can_use_image_quiz_test_commands(getattr(user, "id", None)):
        await message.reply_text("Allowed users only.")
        return
    args = context.args or []
    relation = args[0].strip().lower() if args else None
    if relation and relation not in ("synonym", "antonym"):
        await message.reply_text("Использование: /admin_clearsprint [synonym|antonym]")
        return
    status_msg = await message.reply_text("Чищу sprint-банк и регенерирую…")
    await asyncio.to_thread(ensure_sprint_schema)
    deleted = await asyncio.to_thread(delete_sprint_bank, relation=relation)
    made = 0
    for rel in ([relation] if relation else ["synonym", "antonym"]):
        made += await _sprint_topup(rel, SPRINT_POOL_TARGET)
    await status_msg.edit_text(f"✅ Удалено {deleted}, сгенерировано {made} (с переводами по словам).")


async def admin_sprint_command(update: Update, context: CallbackContext) -> None:
    """Send a sprint now. /admin_sprint [synonym|antonym] (default synonym)."""
    user = update.effective_user
    chat = update.effective_chat
    message = update.effective_message
    if not user or not chat or not message:
        return
    if not _can_use_image_quiz_test_commands(getattr(user, "id", None)):
        await message.reply_text("Allowed users only.")
        return
    args = context.args or []
    relation = (args[0].strip().lower() if args else "synonym")
    if relation not in ("synonym", "antonym"):
        await message.reply_text("Использование: /admin_sprint [synonym|antonym]")
        return
    status_msg = await message.reply_text(f"Готовлю {relation}-спринт…")
    await asyncio.to_thread(ensure_sprint_schema)
    entry = await asyncio.to_thread(pick_next_sprint, relation=relation, cooldown_days=0)
    if not entry:
        await status_msg.edit_text(f"Генерирую {relation}-спринт (LLM)…")
        await _sprint_topup(relation, SPRINT_POOL_TARGET)
        entry = await asyncio.to_thread(pick_next_sprint, relation=relation, cooldown_days=0)
    if not entry:
        await status_msg.edit_text("Не удалось подготовить спринт (см. логи).")
        return
    slot_now = _get_quiz_schedule_now()
    ok = await send_sprint_to_chat(
        context, entry=entry, relation=relation, slot_date=slot_now.date(),
        slot_hour=int(slot_now.hour) * 10000 + int(slot_now.second),
        chat_id=int(chat.id), target_user_id=int(user.id),
    )
    if ok:
        await asyncio.to_thread(mark_sprint_sent, str(entry["sprint_id"]))
        await status_msg.delete()
    else:
        await status_msg.edit_text("Не удалось отправить спринт — проверь логи.")


# ══════════════════════════════════════════════════════════════════════════════
# DAILY SEND-PLAN DASHBOARD (plan vs fact, pinned, live-updating in place)
# ══════════════════════════════════════════════════════════════════════════════

# Each group: (emoji, title, slots[(h,m)], dispatch_table, fact_kind). fact_kind:
#   "slotHM"   → dispatch slot_hour == h*100+m   (article quiz)
#   "slotH"    → dispatch slot_hour == h          (rebus/crossword/anagram/aufgabe)
#   "createdH" → local hour of created_at == h    (visual-riddle / image-quiz)
#   "listening"→ any row today                    (listening, once/day)
def _send_plan_groups() -> list[dict]:
    groups = [
        {"emoji": "🇩🇪", "title": "Артикль-квиз", "slots": [(h, m, "") for (h, m) in sorted(ARTICLE_QUIZ_SLOT_TIMES)],
         "table": "bt_3_article_quiz_dispatches", "kind": "slotHM"},
        {"emoji": "✏️", "title": "Aufgabe (B2+)",
         "slots": [(h, m, AUFGABE_FORMAT_SLOTS[(h, m)].capitalize()) for (h, m) in sorted(AUFGABE_FORMAT_SLOTS.keys())],
         "table": "bt_3_aufgabe_dispatches", "kind": "slotH"},
        {"emoji": "🧩", "title": "Ребус", "slots": [(h, m, "") for (h, m) in sorted(REBUS_SLOT_TIMES)],
         "table": "bt_3_rebus_dispatches", "kind": "slotH"},
        {"emoji": "🔤", "title": "Кроссворд", "slots": [(h, m, "") for (h, m) in sorted(CROSSWORD_SLOT_TIMES)],
         "table": "bt_3_crossword_dispatches", "kind": "slotH"},
        {"emoji": "🔀", "title": "Анаграмма", "slots": [(h, m, "") for (h, m) in sorted(ANAGRAM_SLOT_TIMES)],
         "table": "bt_3_anagram_dispatches", "kind": "slotH"},
        {"emoji": "🎧", "title": "Аудирование", "slots": [(LISTENING_SLOT_TIME[0], LISTENING_SLOT_TIME[1], "")],
         "table": "bt_3_listening_dispatches", "kind": "listening"},
        {"emoji": "🔢", "title": "Числа-диктант", "slots": [(h, m, "") for (h, m) in sorted(NUMDICT_SLOT_TIMES)],
         "table": "bt_3_numdict_dispatches", "kind": "slotHM"},
        {"emoji": "🏃", "title": "Спринт син/ант",
         "slots": [(h, m, "Синонимы" if SPRINT_SLOT_TIMES[(h, m)] == "synonym" else "Антонимы")
                   for (h, m) in sorted(SPRINT_SLOT_TIMES.keys())],
         "table": "bt_3_sprint_dispatches", "kind": "slotHM"},
        # Visual-riddle disabled: free-form image rebuses are too ambiguous.
        # {"emoji": "🖼", "title": "Визуал-ребус", "slots": [(h, m, "") for (h, m) in sorted(VISUAL_RIDDLE_SLOT_TIMES)],
        #  "table": "bt_3_visual_riddle_dispatches", "kind": "createdH"},
        {"emoji": "🎨", "title": "Картинка-квиз", "slots": [(h, m, "") for (h, m) in sorted(QUIZ_IMAGE_SLOT_TIMES)],
         "table": "bt_3_image_quiz_dispatches", "kind": "createdH"},
        {"emoji": "⚡", "title": "Artikel Sprint", "slots": [(ARTIKEL_SPRINT_SLOT[0], ARTIKEL_SPRINT_SLOT[1], "")],
         "table": "bt_3_article_sprint_dispatches", "kind": "slotH"},
    ]
    # image_quiz is retired by default (replaced by the Pin-Bild Aufgabe). Hide its
    # slots from the plan while off, so they don't sit forever as phantom "not sent".
    if not _image_quiz_enabled():
        groups = [g for g in groups if g["table"] != "bt_3_image_quiz_dispatches"]
    if not _artikel_sprint_enabled():
        groups = [g for g in groups if g["table"] != "bt_3_article_sprint_dispatches"]
    return groups


_PLAN_TABLE_TO_ROTATION_KIND = {
    "bt_3_article_quiz_dispatches": "article_quiz",
    "bt_3_aufgabe_dispatches": "aufgabe",
    "bt_3_rebus_dispatches": "rebus",
    "bt_3_crossword_dispatches": "crossword",
    "bt_3_anagram_dispatches": "anagram",
    "bt_3_listening_dispatches": "listening",
    "bt_3_numdict_dispatches": "numdict",
    "bt_3_sprint_dispatches": "sprint",
    "bt_3_article_sprint_dispatches": "artikel_sprint",
}


def _plan_slot_status(kind: str, h: int, m: int, dispatched: set, now_minute: int, *, grace: int = 8, rotated: bool = False) -> str:
    if kind == "listening":
        sent = bool(dispatched)
    elif kind == "slotHM":
        sent = (h * 100 + m) in dispatched
    else:  # slotH / createdH
        sent = h in dispatched
    if sent:
        return "sent"
    if rotated:  # thinned by the daily rotation → not a miss
        return "rotated"
    return "failed" if (h * 60 + m + grace) < now_minute else "planned"


def _build_send_plan_text() -> str:
    """Rebuild the plan-vs-fact dashboard from the schedule + dispatch tables."""
    from backend.database import (
        get_dispatched_slot_hours_today, get_dispatched_created_hours_today, listening_dispatched_today,
        get_rotation_skips_today,
    )
    now = _get_quiz_schedule_now()
    plan_date = now.date()
    now_minute = int(now.hour) * 60 + int(now.minute)
    ic = {"sent": "✅", "planned": "⏳", "failed": "🔴", "rotated": "⏸️"}
    try:
        rotation_skips = get_rotation_skips_today(plan_date)
    except Exception:
        rotation_skips = set()

    lines = [f"📋 <b>План отправок · {plan_date.strftime('%d.%m.%Y')}</b>", ""]
    total = done = failed = rotated = 0
    for g in _send_plan_groups():
        kind, table = g["kind"], g["table"]
        rkind = _PLAN_TABLE_TO_ROTATION_KIND.get(table)
        try:
            if kind == "listening":
                dispatched = listening_dispatched_today(plan_date)
            elif kind == "createdH":
                dispatched = get_dispatched_created_hours_today(table, plan_date)
            else:
                dispatched = get_dispatched_slot_hours_today(table, plan_date)
        except Exception:
            dispatched = set()
            logging.warning("send_plan: fact query failed table=%s", table, exc_info=True)
        toks = []
        for (h, m, label) in g["slots"]:
            is_rotated = bool(rkind and (rkind, h, m) in rotation_skips)
            st = _plan_slot_status(kind, h, m, dispatched, now_minute, rotated=is_rotated)
            total += 1
            done += (st == "sent")
            failed += (st == "failed")
            rotated += (st == "rotated")
            tag = f" {label}" if label else ""
            toks.append(f"{ic.get(st, '⏳')} {h:02d}:{m:02d}{tag}")
        lines.append(f"{g['emoji']} <b>{g['title']}</b>")
        lines.append("   " + "  ".join(toks))
    lines.append("")
    lines.append(f"Итого: ✅ {done} · ⏸️ {rotated} · 🔴 {failed} · ⏳ {total - done - failed - rotated} из {total}")
    lines.append(f"<i>Обновлено: {now.strftime('%H:%M')} · ✅ ушло · ⏸️ ротация · ⏳ ждём · 🔴 не ушло</i>")
    return "\n".join(lines)


def _send_plan_admin_chat_id() -> int | None:
    try:
        from backend.database import get_admin_telegram_ids
        ids = sorted(get_admin_telegram_ids() or [])
        return int(ids[0]) if ids else None
    except Exception:
        return None


async def _send_plan_link(context: CallbackContext) -> None:
    """Keep ONE pinned plan message in the admin DM: edit + re-pin the existing
    one (refreshing the date) instead of spamming a new message daily. The button
    opens the LIVE Mini-App table, which always shows the current day on open."""
    chat_id = _send_plan_admin_chat_id()
    if not chat_id:
        logging.info("send_plan: no admin chat id — skipping")
        return
    from backend.database import admin_kv_get, admin_kv_set
    today = _get_quiz_schedule_now().strftime("%d.%m.%Y")
    kb = InlineKeyboardMarkup([[InlineKeyboardButton(
        "📊 Открыть таблицу плана", url=get_webapp_deeplink("plan"))]])
    text = (
        f"📊 <b>План отправок · {today}</b>\n\n"
        "Открой таблицу — план и факт по каждому интерактиву, обновляется вживую 👇\n"
        "<i>Это сообщение закреплено и обновляется само — открывай его каждый день.</i>"
    )
    key = f"plan_pin:{int(chat_id)}"

    async def _pin(mid: int) -> None:
        try:
            await context.bot.pin_chat_message(
                chat_id=int(chat_id), message_id=int(mid), disable_notification=True)
        except Exception:
            logging.info("send_plan: pin failed mid=%s", mid, exc_info=True)

    stored = await asyncio.to_thread(admin_kv_get, key)
    mid = None
    if stored and "|" in stored:
        try:
            mid = int(stored.split("|", 1)[0])
        except ValueError:
            mid = None
    # Try to refresh the existing pinned message in place.
    if mid:
        try:
            await context.bot.edit_message_text(
                chat_id=int(chat_id), message_id=int(mid), text=text,
                parse_mode="HTML", reply_markup=kb)
            await _pin(mid)
            await asyncio.to_thread(admin_kv_set, key, f"{mid}|{today}")
            return
        except Exception as exc:
            if "not modified" in str(exc).lower():
                await _pin(mid)  # same text (called twice in a day) — just ensure pinned
                return
            # message deleted / uneditable → fall through and send a fresh one
    try:
        msg = await context.bot.send_message(
            chat_id=int(chat_id), text=text, parse_mode="HTML", reply_markup=kb)
        await _pin(int(msg.message_id))
        await asyncio.to_thread(admin_kv_set, key, f"{int(msg.message_id)}|{today}")
    except Exception:
        logging.warning("send_plan: link send failed", exc_info=True)


async def _send_plan_dashboard_job(context: CallbackContext) -> None:
    """Morning: DM the admin the link to today's live plan table."""
    await _send_plan_link(context)


