async def admin_aufgabe_all_command(update: Update, context: CallbackContext) -> None:
    """Send ONE task of EACH B2+ format (admin showcase). /admin_aufgabe_all
    Generates a missing format on the fly so all variants can be reviewed."""
    user    = update.effective_user
    chat    = update.effective_chat
    message = update.effective_message
    if not user or not chat or not message:
        return
    if not _can_use_image_quiz_test_commands(getattr(user, "id", None)):
        await message.reply_text("Allowed users only.")
        return

    status_msg = await message.reply_text("Отправляю по одному заданию каждого формата…")
    slot_now = _get_quiz_schedule_now()
    base_slot = int(slot_now.hour) * 100000 + int(slot_now.minute) * 100
    sent_formats: list[str] = []
    for idx, (fmt, level) in enumerate(_AUFGABE_FORMATS):
        try:
            have = await asyncio.to_thread(count_available_aufgaben, format=fmt)
            if have == 0:
                await _aufgabe_topup_format(fmt, level, 1)
            entry = await asyncio.to_thread(pick_next_aufgabe, cooldown_days=0, format=fmt)
            if not entry:
                logging.info("aufgabe_all: no item for format=%s", fmt)
                continue
            ok = await send_aufgabe_to_chat(
                context, entry=entry, slot_date=slot_now.date(),
                slot_hour=base_slot + idx,
                chat_id=int(chat.id), target_user_id=int(user.id),
            )
            if ok:
                await asyncio.to_thread(mark_aufgabe_sent, str(entry.get("aufgabe_id") or ""))
                sent_formats.append(fmt)
        except Exception:
            logging.warning("aufgabe_all: format=%s failed", fmt, exc_info=True)
    await status_msg.edit_text(
        "Отправлено: " + (", ".join(sent_formats) if sent_formats else "ничего (см. логи)")
        + f"\nВсего форматов: {len(_AUFGABE_FORMATS)}"
    )


# ─────────────────────────────────────────────────────────────
#  Daily pool inventory report (DM to admin at 07:00)
# ─────────────────────────────────────────────────────────────

async def build_pool_inventory_report(context: CallbackContext) -> str:
    """Per-game-type snapshot: how many items are in the DB now, the daily burn
    (1 item per send slot — the same item goes to every recipient), and how many
    tonight's top-up will add to reach target. One scannable DM."""
    from backend.database import (
        count_aufgaben_by_format, count_available_rebuses, count_available_article_quiz_entries,
        count_crossword_bank_entries, count_available_anagram_cards, count_listening_bank_entries,
        count_numdict_bank_entries,
        count_prepared_telegram_quizzes, count_ready_visual_riddle_templates,
        pool_demand_last_24h,
    )
    try:
        targets = await _collect_quiz_delivery_user_targets(context)
        n_targets = len(targets or [])
    except Exception:
        n_targets = 0

    def row(emoji, name, count, target, slots, enabled=True):
        off = "" if enabled else " <i>(off)</i>"
        tgt = f"/{target}" if target else ""
        warn = " ⚠️" if (target and count < target) else ""
        refill = max(0, (target or 0) - count)
        refill_s = f" · дозальём ~{refill}" if refill > 0 else ""
        slots_s = f"{slots}/д" if isinstance(slots, int) else str(slots)
        return f"{emoji} <b>{name}</b>: {count}{tgt}{warn} · слотов {slots_s}{refill_s}{off}"

    lines = [f"📊 <b>Пул интерактивов</b> — {_get_quiz_schedule_now().strftime('%d.%m.%Y')}"]
    lines.append(f"Получателей в рассылке: <b>{n_targets}</b>")
    lines.append("<i>1 слот = 1 задание из базы всем получателям; расход = слотов/день.</i>")
    lines.append("")

    # New B2+ Aufgabe engine — per format
    au = await asyncio.to_thread(count_aufgaben_by_format)
    au_target = AUFGABE_PER_FORMAT_TARGET
    au_fmts = [
        ("Lückentext", "cloze"), ("Wortbildung", "wortbildung"), ("Wortgruppe", "wortgruppe"),
        ("Satztransformation", "transform"), ("Fehler-finden", "error"),
        ("Hör-Lücke", "hoerluecke"), ("Pin-Bild", "pin"),
    ]
    au_sum = 0
    au_refill = 0
    lines.append(f"🆕 <b>Aufgabe (B2+)</b> · 1 слот/формат в день · цель {au_target}/формат{'' if _aufgabe_enabled() else ' <i>(off)</i>'}")
    for label, key in au_fmts:
        c = int(au.get(key, 0))
        au_sum += c
        au_refill += max(0, au_target - c)
        warn = " ⚠️" if c < au_target else ""
        lines.append(f"   • {label}: {c}/{au_target}{warn}")
    lines.append(f"   Σ в базе {au_sum} · ночью дозальём ~{au_refill}")
    lines.append("")

    # Older games
    rebus = await asyncio.to_thread(count_available_rebuses, cooldown_days=REBUS_COOLDOWN_DAYS)
    rebus_ready_total = await asyncio.to_thread(count_available_rebuses, cooldown_days=0)
    cross = await asyncio.to_thread(count_crossword_bank_entries, exclude_retired=True)
    artic = await asyncio.to_thread(count_available_article_quiz_entries, cooldown_days=14)
    anag = await asyncio.to_thread(count_available_anagram_cards, cooldown_days=ANAGRAM_COOLDOWN_DAYS)
    listen = await asyncio.to_thread(count_listening_bank_entries, exclude_retired=True)
    numdict = await asyncio.to_thread(count_numdict_bank_entries, exclude_retired=True)
    prep = await asyncio.to_thread(count_prepared_telegram_quizzes)
    # Visual-riddle disabled: keep the pool code available, but hide it from the
    # Telegram pool report and stop topping it up from the scheduler.
    # vr = await asyncio.to_thread(count_ready_visual_riddle_templates)

    # Rebus refills from cooldown, not generation (the bank is fully generated), so
    # show ready-total + currently-sendable instead of a misleading "дозальём ~N".
    rb_cd = max(0, int(rebus_ready_total) - int(rebus))
    rb_off = "" if _rebuses_enabled() else " <i>(off)</i>"
    lines.append(
        f"🧩 <b>Rebus</b>: готово {int(rebus_ready_total)} · доступно сейчас {int(rebus)}"
        f" (в cooldown {rb_cd}, {REBUS_COOLDOWN_DAYS}д) · слотов {len(REBUS_SLOT_TIMES)}/д{rb_off}"
    )
    lines.append(row("🔤", "Kreuzwort", cross, CROSSWORD_POOL_TARGET, len(CROSSWORD_SLOT_TIMES), _crosswords_enabled()))
    lines.append(row("🇩🇪", "Artikel-Quiz", artic, ARTICLE_QUIZ_POOL_TARGET, len(ARTICLE_QUIZ_SLOT_TIMES), _article_quiz_enabled()))
    lines.append(row("🔀", "Anagramm", anag, ANAGRAM_POOL_TARGET, len(ANAGRAM_SLOT_TIMES), _anagram_enabled()))
    lines.append(row("🎧", "Hörverständnis", listen, LISTENING_POOL_TARGET, 1, _listening_enabled()))
    lines.append(row("🔢", "Zahlen-Diktat", numdict, NUMDICT_POOL_TARGET, len(NUMDICT_SLOT_TIMES), _numdict_enabled()))
    lines.append(row("🃏", "Prepared-Quiz (poll)", prep, None, "—"))
    # lines.append(row("🖼", "Visual-Riddle", vr, VISUAL_RIDDLE_POOL_TARGET, len(VISUAL_RIDDLE_SLOT_TIMES), _visual_riddles_enabled()))
    lines.append("🖼 <b>Image-Quiz</b>: ретайрнут <i>(off)</i>")

    # Actual supply vs demand over the last 24h (sent items / answers given)
    try:
        demand = await asyncio.to_thread(pool_demand_last_24h)
        s = demand.get("sent", {})
        a = demand.get("answered", {})
        lines.append("")
        lines.append("📈 <b>За 24ч (факт)</b> — отправлено · отвечено")
        lines.append(f"🆕 Aufgabe: {int(s.get('aufgabe', 0))} · {int(a.get('au', 0))}")
        # Per-format breakdown under the Aufgabe aggregate (so Pin-Bild «найди объект на
        # картинке» и другие форматы видны по отдельности). Show only formats with any
        # activity in the last 24h.
        s_auf = demand.get("sent_aufgabe_by_format", {}) or {}
        a_auf = demand.get("answered_aufgabe_by_format", {}) or {}
        for label, key in au_fmts:
            sc = int(s_auf.get(key, 0))
            ac = int(a_auf.get(key, 0))
            if sc or ac:
                lines.append(f"   • {label}: {sc} · {ac}")
        lines.append(f"🧩 Rebus: {int(s.get('rebus', 0))} · {int(a.get('rb', 0))}")
        lines.append(f"🔤 Kreuzwort: {int(s.get('crossword', 0))} · {int(a.get('cw', 0))}")
        lines.append(f"🇩🇪 Artikel: {int(s.get('article', 0))} · —")
        lines.append(f"🔀 Anagramm: {int(s.get('anagram', 0))} · {int(a.get('ag', 0))}")
        lines.append(f"🎧 Hören: {int(s.get('listening', 0))} · {int(a.get('ls', 0))}")
        lines.append(f"🔢 Числа: {int(s.get('numdict', 0))} · {int(a.get('nd', 0))}")
        lines.append(f"✍️ Freeform: — · {int(a.get('qf', 0))}")
    except Exception:
        logging.warning("pool_report: demand block failed", exc_info=True)

    return "\n".join(lines)


async def _send_pool_inventory_report_job(context: CallbackContext) -> None:
    """07:00 cron: DM the pool inventory report to all admins."""
    try:
        admin_ids = [int(a) for a in (get_admin_telegram_ids() or []) if int(a) > 0]
        if not admin_ids:
            logging.info("pool_report: no admin ids configured")
            return
        text = await build_pool_inventory_report(context)
        for admin_id in admin_ids:
            try:
                await context.bot.send_message(chat_id=admin_id, text=text, parse_mode="HTML")
            except Exception:
                logging.warning("pool_report: send failed admin_id=%s", admin_id, exc_info=True)
    except Exception:
        logging.warning("pool_report job failed", exc_info=True)


async def admin_pool_report_command(update: Update, context: CallbackContext) -> None:
    """On-demand pool inventory report. /poolreport"""
    user = update.effective_user
    message = update.effective_message
    if not user or not message:
        return
    if not _can_use_image_quiz_test_commands(getattr(user, "id", None)):
        await message.reply_text("Allowed users only.")
        return
    try:
        text = await build_pool_inventory_report(context)
        await message.reply_text(text, parse_mode="HTML")
    except Exception as exc:
        await message.reply_text(f"❌ pool report failed: {exc}")


async def admin_crossword_health_command(update: Update, context: CallbackContext) -> None:
    """READ-ONLY diagnosis of WHY crosswords aren't going out. Breaks down the bank
    (ready / pending / failed / retired), shows how many are sendable RIGHT NOW vs
    blocked by cooldown, the last send, and whether the feature is enabled. /cw_health"""
    user = update.effective_user
    message = update.effective_message
    if not user or not message:
        return
    if not _can_use_image_quiz_test_commands(getattr(user, "id", None)):
        await message.reply_text("Allowed users only.")
        return
    try:
        h = await asyncio.to_thread(crossword_pool_health, cooldown_days=CROSSWORD_COOLDOWN_DAYS)
    except Exception as exc:
        await message.reply_text(f"❌ cw_health failed: {exc}")
        return

    enabled = _crosswords_enabled()
    slots = ", ".join(f"{hh:02d}:{mm:02d}" for (hh, mm) in sorted(CROSSWORD_SLOT_TIMES))
    last_sent = h.get("last_sent_at")
    last_sent_s = last_sent.strftime("%Y-%m-%d %H:%M") if last_sent else "никогда"
    frees = h.get("oldest_cooldown_sent_at")
    frees_s = (frees + timedelta(days=CROSSWORD_COOLDOWN_DAYS)).strftime("%Y-%m-%d %H:%M") if frees else None

    lines = [
        "🔤 <b>Kreuzwort — health</b>",
        f"• включено: {'✅ да' if enabled else '❌ НЕТ (CROSSWORDS_ENABLED=off)'}",
        f"• слоты: {slots} · cooldown {CROSSWORD_COOLDOWN_DAYS}д",
        f"• последняя отправка: <b>{last_sent_s}</b>",
        "",
        f"<b>Пул ({h['total']} всего):</b>",
        f"• ✅ ready (не retired): <b>{h['ready']}</b>",
        f"• ⏳ pending: {h['pending']}",
        f"• ❌ failed: {h['failed']}",
        f"• 🚫 retired: {h['retired']}",
        "",
        f"<b>➡️ отправляемо ПРЯМО СЕЙЧАС: {h['sendable_now']}</b>",
        f"• в cooldown (ready, но рано): {h['in_cooldown']}",
    ]
    if h["sendable_now"] == 0 and frees_s:
        lines.append(f"• ближайший выйдет из cooldown: {frees_s}")

    # Verdict — the single most-likely cause.
    if not enabled:
        verdict = "🔴 Фича выключена env-флагом CROSSWORDS_ENABLED → включи."
    elif h["sendable_now"] > 0:
        verdict = "🟢 Пул готов — есть что слать. Если тишина, проблема в cron/слоте, не в пуле (смотри логи cw_slot)."
    elif h["ready"] == 0 and h["total"] > 0 and (h["pending"] + h["failed"] + h["retired"]) > 0:
        if h["retired"] > 0:
            verdict = "🔴 Живых ready-карт нет, но есть retired. Оживи их: /admin_cw_revive (мгновенно, бесплатно)."
        elif h["failed"] > 0 or h["pending"] > 0:
            verdict = "🔴 Ни одной ready-картинки (застряли в pending/failed). Ре-рендер: /admin_cw_rerender, потом /admin_cw_pool."
        else:
            verdict = "🔴 Нет ready-записей — догенерируй пул: /admin_cw_pool 50."
    elif h["total"] == 0:
        verdict = "🔴 Банк пустой — сгенерируй пул: /admin_cw_pool 50."
    elif h["in_cooldown"] > 0:
        # Not a blackout anymore (send falls back to cooldown=0), but a small pool = early repeats.
        hint = " Есть retired — оживи /admin_cw_revive." if h["retired"] > 0 else " Долей: /admin_cw_pool 50."
        verdict = "🟠 Все ready-карты в cooldown — блэкаута не будет (fallback), но возможны ранние повторы." + hint
    else:
        verdict = "🟠 Отправлять нечего по неочевидной причине — проверь логи cw_slot."
    lines += ["", verdict]

    await message.reply_text("\n".join(lines), parse_mode="HTML")


async def admin_reader_public_status_command(update: Update, context: CallbackContext) -> None:
    """Diagnose WHY the reader «Классика» shelf shows 0 books: is the is_public column
    present, how many public rows exist, their target_lang spread, and how many match
    the shelf query (is_public · not archived · target_lang=de). Read-only.
    Pass 'ingest' to re-ingest the whole public-domain catalog: /reader_public_status ingest"""
    user = update.effective_user
    message = update.effective_message
    if not user or not message:
        return
    if not _can_use_image_quiz_test_commands(getattr(user, "id", None)):
        await message.reply_text("Allowed users only.")
        return
    # Tolerate trailing punctuation / whitespace (e.g. iOS autocorrect adds a ".").
    arg = (context.args[0].strip().strip(".!,;:").lower() if context.args else "")

    from backend.database import get_public_library_diagnostics
    diag = await asyncio.to_thread(get_public_library_diagnostics)
    if diag.get("error"):
        await message.reply_text(f"❌ status failed: {diag['error']}")
        return

    langs = ", ".join(f"{k}:{v}" for k, v in (diag.get("by_target_lang") or {}).items()) or "—"
    lines = [
        "🏛️ <b>Классика — статус</b>",
        f"• колонка is_public: {'✅ есть' if diag['column_exists'] else '❌ НЕТ'}",
        f"• всего публичных строк: <b>{diag['total_public']}</b>",
        f"• по target_lang: {langs}",
        f"• архивных публичных: {diag['archived_public']}",
        f"• попадает в полку (de, не архив): <b>{diag['de_shelf']}</b>",
    ]
    if diag["de_shelf"] == 0:
        if not diag["column_exists"]:
            lines.append("\n⚠️ Нет колонки is_public — схема не применилась. Перезапусти сервис, затем ingest.")
        else:
            lines.append("\n⚠️ Полка пуста. Залить каталог: <code>/reader_public_status ingest</code>")
    await message.reply_text("\n".join(lines), parse_mode="HTML")

    if arg == "ingest":
        # Optional slug → ingest ONE book. A full run re-downloads and re-extracts every
        # classic, which rewrites their page text and therefore the per-page text_hash the
        # warm audio cache is keyed on — i.e. it silently throws away everything the
        # nightly pre-gen has built. Fixing a single broken book must not cost that.
        slug = (context.args[1].strip().strip(".!,;:").lower() if len(context.args) > 1 else "")
        if slug:
            from backend.public_library_catalog import CATALOG_BY_SLUG
            if slug not in CATALOG_BY_SLUG:
                known = ", ".join(sorted(CATALOG_BY_SLUG))
                await message.reply_text(
                    f"❌ Нет такой книги в каталоге: <code>{html.escape(slug)}</code>\n\nДоступные: <code>{html.escape(known)}</code>",
                    parse_mode="HTML",
                )
                return
            await message.reply_text(f"⏳ Заливаю одну книгу: <code>{html.escape(slug)}</code>…", parse_mode="HTML")
        else:
            await message.reply_text(
                "⏳ Заливаю ВЕСЬ каталог классики (скачивание с Gutenberg) — это до пары минут.\n"
                "⚠️ Полный прогон перезаписывает текст всех книг, поэтому уже прогретое аудио "
                "теряет привязку и прогревается заново. Для одной книги: "
                "<code>/reader_public_status ingest &lt;slug&gt;</code>",
                parse_mode="HTML",
            )
        try:
            from backend.backend_server import ingest_public_library_catalog
            res = await asyncio.to_thread(
                ingest_public_library_catalog, slugs=[slug] if slug else None, dry_run=False
            )
        except Exception as exc:
            logging.exception("public library ingest via bot failed")
            await message.reply_text(f"❌ ingest failed: {exc}")
            return
        failed = [r for r in (res.get("results") or []) if not r.get("ok")]
        tail = ""
        if failed:
            names = ", ".join(f"{r.get('slug')} ({r.get('error')})" for r in failed[:8])
            tail = f"\n❌ не удалось: {names}"
        after = await asyncio.to_thread(get_public_library_diagnostics)
        await message.reply_text(
            f"✅ Ingest готов: {res.get('ok')}/{res.get('total')} книг."
            f"\nСейчас в полке (de): <b>{after.get('de_shelf')}</b>." + tail
            + "\n\nОткрой читалку заново — «Классика» должна заполниться.",
            parse_mode="HTML",
        )

    if arg == "pregen":
        # Cap per-invocation so the command RETURNS promptly with progress instead of
        # appearing hung while it synthesizes thousands of pages. Re-run to continue;
        # the nightly 04:45 job also keeps warming.
        pregen_cap = int((os.getenv("PUBLIC_LIBRARY_PREGEN_BOT_MAX_PAGES") or "120").strip() or "120")
        await message.reply_text(
            f"⏳ Прогреваю аудио классики (Standard-голос, из бесплатного бакета), "
            f"до {pregen_cap} страниц за запуск. Мгновенное проигрывание без холодного синтеза. "
            "Может занять пару минут — дождись отчёта…"
        )
        try:
            from backend.backend_server import run_public_library_audio_pregen
            res = await asyncio.to_thread(
                run_public_library_audio_pregen,
                max_pages=pregen_cap,
                dry_run=False,
                trigger="admin_command",
            )
        except Exception as exc:
            logging.exception("public library audio pregen via bot failed")
            await message.reply_text(f"❌ pregen failed: {exc}")
            return
        stopped = res.get("stopped")
        stopped_txt = {
            "budget_exhausted": "бюджет Standard на этот месяц исчерпан",
            "max_pages": f"дошёл до лимита {pregen_cap} стр. за запуск — запусти ещё раз, чтобы продолжить",
            "provider_blocked": "провайдер заблокировал синтез (бюджет)",
        }.get(stopped, "дошёл до конца — всё, что можно, прогрето")
        await message.reply_text(
            "🎧 <b>Прогрев аудио классики</b>\n"
            f"• озвучено новых страниц: <b>{res.get('generated_pages')}</b>\n"
            f"• уже было в кэше: {res.get('skipped_cached')}\n"
            f"• просмотрено страниц: {res.get('pages_visited')}\n"
            f"• потрачено символов: {res.get('spent_chars')} из бюджета {res.get('budget_chars')}\n"
            f"• ошибок синтеза: <b>{res.get('failed_pages') or 0}</b>\n"
            f"• итог: {stopped_txt}\n\n"
            "Проверить готовность книг: <code>/reader_public_status audio</code>. "
            "Прогрев идёт и сам ночью в 03:30.",
            parse_mode="HTML",
        )

    if arg == "audio":
        # Same builder as the 08:00 DM (full list instead of top-6), so the on-demand
        # report can never drift from the scheduled one.
        try:
            text = await asyncio.to_thread(build_classics_audio_readiness_text, partial_limit=None)
        except Exception as exc:
            await message.reply_text(f"❌ audio-status failed: {exc}")
            return
        await message.reply_text(
            text or "Пока нет данных (нет публичных книг?).", parse_mode="HTML"
        )


# ── Telegram Stars payments (Mini App digital purchases) ─────────────────────
async def on_stars_pre_checkout(update: Update, context: CallbackContext) -> None:
    """Approve the Stars pre-checkout. We validated price + payload when the invoice
    link was created, so accept; Telegram needs an answer within 10 seconds."""
    q = getattr(update, "pre_checkout_query", None)
    if not q:
        return
    try:
        await q.answer(ok=True)
    except Exception:
        logging.exception("stars pre_checkout answer failed")


async def on_stars_successful_payment(update: Update, context: CallbackContext) -> None:
    """Fulfil a completed Telegram Stars purchase. Idempotent by charge id, so a
    re-delivered update never double-grants. The invoice_payload tells us what was
    bought (purpose)."""
    msg = update.effective_message
    sp = getattr(msg, "successful_payment", None) if msg else None
    if not sp:
        return
    user = update.effective_user
    uid = int(getattr(user, "id", 0) or 0)
    charge_id = str(getattr(sp, "telegram_payment_charge_id", "") or "")
    stars = int(getattr(sp, "total_amount", 0) or 0)  # XTR total = number of Stars
    try:
        payload = json.loads(getattr(sp, "invoice_payload", "") or "{}")
    except Exception:
        payload = {}
    purpose = str(payload.get("purpose") or "").strip().lower()

    from backend.database import record_star_payment_once, grant_book_audio_unlock
    try:
        is_new = record_star_payment_once(
            telegram_payment_charge_id=charge_id, user_id=uid, purpose=purpose, stars=stars, payload=payload,
        )
    except Exception:
        logging.exception("record_star_payment_once failed charge=%s", charge_id)
        is_new = True  # fail-open: better to grant than to silently drop a paid purchase
    if not is_new:
        return  # already fulfilled

    if purpose == "book_audio":
        try:
            coverage_pct = int(payload.get("coverage_pct") or 100)
            if coverage_pct not in (25, 50, 100):
                coverage_pct = 100
            grant_book_audio_unlock(
                user_id=int(payload.get("user_id") or uid),
                document_id=int(payload.get("document_id") or 0),
                voice_tier=str(payload.get("voice_tier") or "neural"),
                currency="XTR",
                coverage_pct=coverage_pct,
            )
            if coverage_pct >= 100:
                await msg.reply_text(
                    "✅ Озвучка книги открыта! Вернись в читалку и нажми ▶ — теперь эту книгу можно слушать всю, без ограничений."
                )
            else:
                await msg.reply_text(
                    f"✅ Озвучка открыта на первые {coverage_pct}% книги! Вернись в читалку и нажми ▶. Захочешь дальше — можно докупить остальное, доплатив только разницу."
                )
        except Exception:
            logging.exception("book_audio grant failed charge=%s", charge_id)
    elif purpose == "pro":
        try:
            from backend.database import set_subscription_from_stripe
            from datetime import datetime, timezone, timedelta
            exp = getattr(sp, "subscription_expiration_date", None)
            if isinstance(exp, (int, float)):
                exp = datetime.fromtimestamp(int(exp), tz=timezone.utc)
            if not exp:
                exp = datetime.now(timezone.utc) + timedelta(days=31)
            set_subscription_from_stripe(
                user_id=int(payload.get("user_id") or uid),
                plan_code="pro",
                stripe_customer_id=None,
                stripe_subscription_id=f"stars_{charge_id}",
                status="active",
                current_period_end=exp,
            )
            await msg.reply_text(
                "✅ «Полный доступ» подключён — спасибо! Продлевается автоматически раз в месяц; отменить можно в любой момент в настройках Telegram."
            )
        except Exception:
            logging.exception("stars pro grant failed charge=%s", charge_id)
    elif purpose in ("support_coffee", "support_cheesecake"):
        # One-time "thank you" donation. Besides the sponsor badge + wall of thanks, it now GRANTS
        # bonus Pro days: coffee → 7, cheesecake → 14. grant_pro_days stacks on any active grant and
        # banks onto an active PAID period (so a Pro subscriber's days extend, not burn concurrently).
        # `purpose` IS the tier (kept out of the 128-byte Stars payload).
        _support_pro_days = {"support_coffee": 7, "support_cheesecake": 14}
        try:
            from backend.database import record_sponsorship, grant_pro_days
            _uid = int(payload.get("user_id") or uid)
            _name = str(getattr(user, "first_name", "") or "").strip() or None
            record_sponsorship(
                _uid,
                purpose,
                amount_minor=int(stars),          # magnitude in Stars (currency XTR)
                currency="XTR",
                display_name=_name,
                # Reuse the UNIQUE checkout-session column as the Stars idempotency key.
                stripe_checkout_session_id=f"stars_{charge_id}",
            )
            _days = _support_pro_days.get(purpose, 0)
            _pro_granted = False
            if _days > 0:
                # Link the grant to this charge so a refund can revoke exactly these days.
                _pro_granted = bool(grant_pro_days(_uid, days=_days, reason=purpose,
                                                   source_charge_id=charge_id))
            _thanks = ("Спасибо за кофе ☕️" if purpose == "support_coffee"
                       else "Спасибо за кофе и чизкейк ☕️🍰")
            if _pro_granted:
                await msg.reply_text(
                    f"{_thanks} В подарок — {_days} дней полного доступа (уже начислены), плюс ты в стене благодарностей. "
                    f"Это правда помогает оплачивать серверы. 🙏"
                )
            else:
                await msg.reply_text(
                    f"{_thanks} Ты в стене благодарностей — это правда помогает оплачивать серверы. 🙏"
                )
        except Exception:
            logging.exception("stars support grant failed charge=%s", charge_id)
    else:
        logging.warning("stars payment with unknown purpose=%r charge=%s", purpose, charge_id)


async def admin_reset_subs_command(update: Update, context: CallbackContext) -> None:
    """One-time Stripe→Stars reset. Moves every paid (pro) user back to Free (they get a fresh
    7-day Pro trial on their next Mini-App open), EXCEPT admins and any ids you keep. Dry-run
    by default — nothing changes until you add `confirm`.
      /admin_reset_subs                 → dry-run: list current Pro users (id + name)
      /admin_reset_subs confirm         → reset all except admins
      /admin_reset_subs confirm 111 222 → reset all except admins + ids 111, 222 (e.g. Alina)"""
    user = update.effective_user
    message = update.effective_message
    if not user or not message:
        return
    if not _is_admin_user(getattr(user, "id", None)):
        await message.reply_text("Только для админа.")
        return

    from backend.database import (
        list_active_pro_subscription_user_ids,
        list_active_pro_grant_users,
        reset_pro_subscriptions_except,
        get_display_names_for_users,
    )

    args = context.args or []
    confirm = bool(args) and str(args[0]).strip().lower() == "confirm"
    extra_keep: set[int] = set()
    for tok in args[1:] if confirm else args:
        try:
            extra_keep.add(int(str(tok).strip()))
        except ValueError:
            continue
    admin_ids = {int(a) for a in (get_admin_telegram_ids() or []) if int(a) > 0}
    keep = admin_ids | extra_keep

    pro_ids = await asyncio.to_thread(list_active_pro_subscription_user_ids)
    grant_rows = await asyncio.to_thread(list_active_pro_grant_users)  # [(uid, until, reason)]
    all_ids = list({*pro_ids, *[r[0] for r in grant_rows]})
    names = await asyncio.to_thread(get_display_names_for_users, all_ids) if all_ids else {}

    _reason_label = {
        "welcome_trial": "7-дн. триал",
        "admin_test": "выдан вручную",
        "streak": "за streak",
        "support_coffee": "донат ☕️",
        "support_cheesecake": "донат ☕️🍰",
    }

    def _fmt(uid: int) -> str:
        nm = names.get(int(uid)) or "—"
        tags = []
        if uid in admin_ids:
            tags.append("админ")
        if uid in extra_keep:
            tags.append("оставить")
        tag = f" [{', '.join(tags)}]" if tags else ""
        return f"• {uid} — {nm}{tag}"

    def _fmt_grant(row) -> str:
        uid, until, reason = row
        nm = names.get(int(uid)) or "—"
        label = _reason_label.get(reason, reason or "грант")
        until_s = until.strftime("%Y-%m-%d") if hasattr(until, "strftime") else str(until)[:10]
        return f"• {uid} — {nm} ({label}, до {until_s})"

    async def _send_lines(lines: list[str]) -> None:
        buf = ""
        for ln in lines:
            if len(buf) + len(ln) + 1 > 3500:
                if buf:
                    await message.reply_text(buf)
                buf = ln
            else:
                buf = f"{buf}\n{ln}" if buf else ln
        if buf:
            await message.reply_text(buf)

    targets = [u for u in pro_ids if u not in keep]

    if not confirm:
        total_pro = len({*pro_ids, *[r[0] for r in grant_rows]})
        head = [
            f"Всего Pro сейчас: {total_pro} чел.",
            "",
            f"💳 На платной подписке: {len(pro_ids)}  (только их трогает сброс — "
            f"оставим {len(pro_ids) - len(targets)}, сбросим {len(targets)})",
        ]
        head += [_fmt(u) for u in pro_ids] if pro_ids else ["  (никого)"]
        grant_block = [
            "",
            f"🎁 Подаренный/пробный Pro: {len(grant_rows)}  (сброс НЕ трогает)",
        ]
        grant_block += [_fmt_grant(r) for r in grant_rows] if grant_rows else ["  (никого)"]
        footer = [
            "",
            "Ничего не изменено (сухой прогон).",
            "Сбросить платные подписки, КРОМЕ админов:  /admin_reset_subs confirm",
            "Дополнительно оставить кого-то:  /admin_reset_subs confirm <id> <id>",
        ]
        await _send_lines(head + grant_block + footer)
        return

    res = await asyncio.to_thread(reset_pro_subscriptions_except, keep)
    reset_ids = res.get("reset") or []
    kept_extra = sorted(extra_keep) if extra_keep else "нет"
    await message.reply_text(
        f"✅ Готово. Сброшено на Free: {len(reset_ids)}. Оставлены: админы + {kept_extra}.\n"
        f"Сброшенные получат Free + 7-дневный Pro-trial при следующем открытии Mini-App."
    )


async def admin_subs_command(update: Update, context: CallbackContext) -> None:
    """/admin_subs — full roster of ALLOWED users with their current subscription status,
    grouped: 💳 Pro (paid subscription) / 🎁 Pro (trial or manual grant) / ⚪ Free. Read-only.
    (The whitelist is the source of truth; anyone Pro but not whitelisted is shown too.)"""
    user = update.effective_user
    message = update.effective_message
    if not user or not message:
        return
    if not _is_admin_user(getattr(user, "id", None)):
        await message.reply_text("Только для админа.")
        return

    from backend.database import (
        list_allowed_telegram_users,
        list_active_pro_subscription_user_ids,
        list_active_pro_grant_users,
        get_display_names_for_users,
    )

    allowed = await asyncio.to_thread(list_allowed_telegram_users, 500)
    allowed_name = {int(u["user_id"]): str(u.get("username") or "").strip() for u in allowed}
    allowed_ids = set(allowed_name)
    pro_ids = set(await asyncio.to_thread(list_active_pro_subscription_user_ids))
    grant_rows = await asyncio.to_thread(list_active_pro_grant_users)  # [(uid, until, reason)]
    grant_map = {int(r[0]): (r[1], str(r[2] or "")) for r in grant_rows}
    all_ids = allowed_ids | pro_ids | set(grant_map)
    dnames = await asyncio.to_thread(get_display_names_for_users, list(all_ids)) if all_ids else {}

    # Hide synthetic accounts (load/smoke/phase tests, load-runner, skill fixtures) so the
    # roster shows only real people. Matched by name/username marker or a negative id.
    _synth_re = re.compile(r"(load[ _]?test|smoke|phasec|postclaim|timeoutfix|skill_v2)", re.I)

    def _is_synthetic(uid: int) -> bool:
        if int(uid) < 0:
            return True
        blob = f"{allowed_name.get(int(uid), '')} {dnames.get(int(uid), '')}"
        return bool(_synth_re.search(blob))

    hidden = sum(1 for u in all_ids if _is_synthetic(u))
    all_ids = {u for u in all_ids if not _is_synthetic(u)}
    allowed_ids = {u for u in allowed_ids if not _is_synthetic(u)}

    _reason_label = {"welcome_trial": "7-дн. триал", "admin_test": "выдан вручную", "streak": "за streak", "support_coffee": "донат ☕️", "support_cheesecake": "донат ☕️🍰"}

    def _nm(uid: int) -> str:
        return dnames.get(int(uid)) or allowed_name.get(int(uid)) or "—"

    def _tag(uid: int) -> str:
        return " [нет в allowed]" if uid not in allowed_ids else ""

    paid = sorted(u for u in all_ids if u in pro_ids)
    granted = sorted(u for u in all_ids if u not in pro_ids and u in grant_map)
    free = sorted(u for u in all_ids if u not in pro_ids and u not in grant_map)

    lines = [
        f"Пользователей (allowed): {len(allowed_ids)}"
        + (f"   ⚙️ технических скрыто: {hidden}" if hidden else "")
        + (" ⚠️ показаны первые 500" if len(allowed) >= 500 else ""),
        f"💳 Pro-подписка: {len(paid)}   🎁 триал/грант: {len(granted)}   ⚪ Free: {len(free)}",
        "",
        f"💳 Pro — платная подписка ({len(paid)}):",
    ]
    lines += [f"• {u} — {_nm(u)}{_tag(u)}" for u in paid] or ["  (никого)"]
    lines += ["", f"🎁 Pro — триал/грант ({len(granted)}):"]
    for u in granted:
        until, reason = grant_map[u]
        label = _reason_label.get(reason, reason or "грант")
        until_s = until.strftime("%Y-%m-%d") if hasattr(until, "strftime") else str(until)[:10]
        lines.append(f"• {u} — {_nm(u)} ({label}, до {until_s}){_tag(u)}")
    if not granted:
        lines.append("  (никого)")
    lines += ["", f"⚪ Free ({len(free)}):"]
    lines += [f"• {u} — {_nm(u)}" for u in free] or ["  (никого)"]

    buf = ""
    for ln in lines:
        if len(buf) + len(ln) + 1 > 3500:
            if buf:
                await message.reply_text(buf)
            buf = ln
        else:
            buf = f"{buf}\n{ln}" if buf else ln
    if buf:
        await message.reply_text(buf)


