# One /admin_verify_wortbildung at a time: each run spends tokens on every pool item,
# so a second press while one is in flight would just double the bill.
_VERIFY_WORTBILDUNG_INFLIGHT = {"active": False}


async def admin_verify_wortbildung_command(update: Update, context: CallbackContext) -> None:
    """LLM-verify EXISTING «Wortbildung» items (pool + review queue) and retire the broken
    ones: carrier that doesn't agree with the derived noun ("eine große Interesse"), an
    invented noun ("Schützung"), a wrong governed preposition, or an ambiguous solution —
    the class no deterministic rule can catch. Costs tokens. Fail-safe: an item is removed
    ONLY on an explicit verdict, never on a verifier error. /admin_verify_wortbildung"""
    user = update.effective_user
    message = update.effective_message
    if not user or not message:
        return
    if not _can_use_image_quiz_test_commands(getattr(user, "id", None)):
        await message.reply_text("Allowed users only.")
        return
    if _VERIFY_WORTBILDUNG_INFLIGHT["active"]:
        await message.reply_text(
            "⏳ Проверка уже идёт — дождись результата. Не жми повторно: каждый запуск тратит токены."
        )
        return
    _VERIFY_WORTBILDUNG_INFLIGHT["active"] = True
    status = await message.reply_text("🔎 Проверяю «Wortbildung» верификатором…")
    try:
        from backend.database import fetch_aufgabe_items_by_format, remove_aufgabe_items
        from backend.openai_manager import run_check_wortbildung_batch
        lines: list[str] = []
        total_removed = 0
        for table, label in (("bt_3_aufgabe_bank", "пул"), ("bt_3_aufgabe_mistakes", "повторы")):
            rows = await asyncio.to_thread(fetch_aufgabe_items_by_format, table, "wortbildung")
            if not rows:
                lines.append(f"• {label}: проверено 0, убрано 0")
                continue
            bad_ids = []
            # Verify in small batches: one call per ~10 items keeps each response short
            # enough to stay valid JSON, and a failed batch only costs those 10 items.
            for start in range(0, len(rows), 10):
                chunk = rows[start:start + 10]
                verdicts = await run_check_wortbildung_batch(items=[pl for _rid, pl in chunk])
                if not verdicts or len(verdicts) != len(chunk):
                    continue  # verifier hiccup → keep this batch (never remove on error)
                bad_ids += [rid for (rid, _pl), v in zip(chunk, verdicts) if not v.get("ok")]
            removed = await asyncio.to_thread(remove_aufgabe_items, table, bad_ids) if bad_ids else 0
            total_removed += removed
            lines.append(f"• {label}: проверено {len(rows)}, убрано {removed}")
        await status.edit_text(
            "✅ <b>Проверка «Wortbildung» завершена</b>\n" + "\n".join(lines) +
            f"\n\nВсего убрано битых: <b>{total_removed}</b>.\n"
            "Пул доберётся при следующем пополнении (/admin_aufgabe_pool).",
            parse_mode="HTML",
        )
    except Exception as exc:
        logging.exception("admin verify wortbildung failed user_id=%s", getattr(user, "id", None))
        try:
            await status.edit_text(f"❌ Не удалось выполнить проверку: {exc}")
        except Exception:
            pass
    finally:
        _VERIFY_WORTBILDUNG_INFLIGHT["active"] = False


async def _error_key_selfcheck(payload) -> dict:
    """Focused second gate for a 'Finde den Fehler' item: does the item's OWN answer key
    actually produce a PERFECT sentence? Apply every correct_word to the tokens and check the
    result holistically. Catches what the 4-point verifier slips on: coupled prep/case ("auf
    dem" after warten) and unrepresentable contraction merges ("im das"→"ins", where the key's
    fix leaves a broken sentence). Returns {'correct': bool, 'errored': bool, 'reason': str} —
    'errored' distinguishes a transient LLM failure (never delete on that) from a definite no."""
    from backend.database import normalize_error_payload
    from backend.openai_manager import run_check_error_full
    woerter = [str(w) for w in (payload.get("woerter") or [])]
    errs = normalize_error_payload(payload)
    if not woerter or not errs:
        return {"correct": False, "errored": False, "reason": "no_errors"}
    original = " ".join(woerter)
    w2 = list(woerter)
    for e in errs:
        i = e["index"]
        if 0 <= i < len(w2):
            w2[i] = e["correct_word"]
    corrected = " ".join(w2)
    try:
        res = await run_check_error_full(original=original, corrected=corrected)
        return {"correct": bool(res.get("correct")), "errored": False,
                "reason": str(res.get("reason_ru") or "")}
    except Exception:
        logging.warning("_error_key_selfcheck failed", exc_info=True)
        return {"correct": False, "errored": True, "reason": ""}


async def _run_error_verify_sweep(tables, *, on_progress=None, limit: int = 300) -> tuple:
    """Shared LLM re-verify of existing 'Finde den Fehler' items, used by BOTH the manual
    /admin_verify_errors and the automatic one-shot startup sweep. For each (table, label),
    fetch up to `limit` error items, LLM-verify each (bounded concurrency), and delete ONLY
    those with an EXPLICIT 'invalid' verdict — never on a verifier error/timeout (fail-safe:
    a transient miss keeps the item). `on_progress(done, total)` is awaited per item if given.
    Returns (total_removed, [per-table report lines])."""
    from backend.database import fetch_aufgabe_error_items, delete_aufgabe_items, normalize_error_payload
    from backend.openai_manager import run_verify_aufgabe_error
    sem = asyncio.Semaphore(8)  # bound OpenAI concurrency; ~600 items finish in ~1–2 min
    progress = {"done": 0, "total": 0}
    fetched = []
    for table, label in tables:
        rows = await asyncio.to_thread(fetch_aufgabe_error_items, table, limit=int(limit))
        fetched.append((table, label, rows))
        progress["total"] += len(rows)

    async def _verify_one(payload) -> bool:
        async with sem:
            verdict = await run_verify_aufgabe_error(
                woerter=payload.get("woerter") or [],
                errors=normalize_error_payload(payload),
            )
            # Delete on an EXPLICIT invalid verdict (never on the fail-closed
            # 'verifier_error'/'unparseable' sentinel — a transient miss must not delete).
            invalid = (not verdict.get("valid")) and verdict.get("reason") not in (
                "verifier_error", "unparseable_verifier_output", "",
            )
            # Second gate: even a 'valid' item is broken if its OWN answer key doesn't yield a
            # perfect sentence (coupled case / contraction merge). Delete only on a DEFINITE
            # no — never on a transient LLM error.
            if not invalid:
                sc = await _error_key_selfcheck(payload)
                if (not sc.get("correct")) and not sc.get("errored"):
                    invalid = True
        progress["done"] += 1
        if on_progress is not None:
            try:
                await on_progress(progress["done"], progress["total"])
            except Exception:
                pass
        return invalid

    total_removed = 0
    lines: list[str] = []
    for table, label, rows in fetched:
        if not rows:
            lines.append(f"• {label}: проверено 0, удалено 0")
            continue
        # return_exceptions=True → a stray error yields a non-True result, so it is never
        # treated as 'invalid' and the item is kept (fail-safe preserved).
        results = await asyncio.gather(
            *[_verify_one(pl) for _rid, pl in rows], return_exceptions=True
        )
        bad_ids = [rid for (rid, _pl), res in zip(rows, results) if res is True]
        removed = await asyncio.to_thread(delete_aufgabe_items, table, bad_ids) if bad_ids else 0
        total_removed += removed
        lines.append(f"• {label}: проверено {len(rows)}, удалено {removed}")
    return total_removed, lines


# In-memory guard so only ONE /admin_verify_errors runs at a time: each run makes up to
# ~600 gpt-4.1-mini calls, so a second press while one is in flight would just double the
# token spend for nothing. Resets on process restart (a crashed run must not lock forever).
_VERIFY_ERRORS_INFLIGHT = {"active": False}


async def admin_verify_errors_command(update: Update, context: CallbackContext) -> None:
    """LLM-verify EXISTING 'Finde den Fehler' items (pool + review queue) and delete the
    grammatically invalid ones (fake case error / a second unflagged error) — the class the
    deterministic /admin_clean_bad_reviews can't catch. Costs tokens (gpt-4.1-mini per item).
    Fail-safe: an item is deleted ONLY on an explicit 'invalid' verdict, never on a verifier
    error. Verifies concurrently (bounded) and reports progress. /admin_verify_errors"""
    user = update.effective_user
    message = update.effective_message
    if not user or not message:
        return
    if not _can_use_image_quiz_test_commands(getattr(user, "id", None)):
        await message.reply_text("Allowed users only.")
        return
    if _VERIFY_ERRORS_INFLIGHT["active"]:
        await message.reply_text(
            "⏳ Верификация уже идёт — дождись результата. Не жми повторно: каждый запуск тратит токены."
        )
        return
    _VERIFY_ERRORS_INFLIGHT["active"] = True
    status = await message.reply_text("🔎 Проверяю «Fehler-finden» верификатором… (займёт ~минуту)")
    try:
        last_shown = {"n": 0}

        async def _on_progress(done: int, total: int) -> None:
            # Throttled progress ping (~every 40 items) so the user sees it's alive.
            if done - last_shown["n"] >= 40:
                last_shown["n"] = done
                try:
                    await status.edit_text(f"🔎 Проверяю «Fehler-finden»… {done}/{total}")
                except Exception:
                    pass

        total_removed, lines = await _run_error_verify_sweep(
            (("bt_3_aufgabe_bank", "пул"), ("bt_3_aufgabe_mistakes", "повторы")),
            on_progress=_on_progress,
        )

        await status.edit_text(
            "✅ <b>Верификация «Fehler-finden» завершена</b>\n" + "\n".join(lines) +
            f"\n\nВсего удалено битых: <b>{total_removed}</b>.",
            parse_mode="HTML",
        )
    except Exception as exc:
        logging.exception("admin verify errors command failed user_id=%s", getattr(user, "id", None))
        try:
            await status.edit_text(f"❌ Не удалось выполнить верификацию: {exc}")
        except Exception:
            pass
    finally:
        _VERIFY_ERRORS_INFLIGHT["active"] = False


