    # 3) APScheduler → вкидываем корутину в тот же loop
    # Per-job throttle for the submit_async completion heartbeat: high-frequency jobs
    # (drip */N, windowed inbox */20, battle reminders */5) must not write a DB row on
    # every tick. Failures always record (bypass the throttle) so a broken job surfaces.
    _bot_sched_hb_last: dict[str, float] = {}
    _BOT_SCHED_HB_MIN_INTERVAL = 55.0

    def submit_async(async_func, context=None, *args, **kwargs):
        if context is None:
            context = CallbackContext(application=application)

        # The rotation-gated interactive senders pass an inner '_wrapped' coroutine and
        # heartbeat themselves as deliver_<kind> — skip them here to avoid a useless
        # '_wrapped' key. Everything else keys the heartbeat by its function name so
        # ALL bot-loop scheduled jobs appear in /scheduler_health automatically.
        job_key = getattr(async_func, "__name__", "") or ""

        fut = asyncio.run_coroutine_threadsafe(
            async_func(context, *args, **kwargs),
            loop
        )
        def _log_scheduler_failure(future):
            crashed = False
            try:
                future.result()
            except Exception:
                crashed = True
                logging.exception("❌ APScheduler job crashed")
            if not job_key or job_key == "_wrapped":
                return
            try:
                now_ts = pytime.time()
                last = _bot_sched_hb_last.get(job_key, 0.0)
                if crashed or (now_ts - last) >= _BOT_SCHED_HB_MIN_INTERVAL:
                    _bot_sched_hb_last[job_key] = now_ts
                    loop.run_in_executor(
                        None,
                        _record_sched_heartbeat,
                        job_key,
                        "failed" if crashed else "completed",
                    )
            except Exception:
                logging.debug("submit_async heartbeat failed job_key=%s", job_key, exc_info=True)

        fut.add_done_callback(_log_scheduler_failure)

    def make_rotation_gated(kind, hour, minute, async_func, *extra):
        """Этап 0: wrap a scheduled interactive sender so it only fires when its
        (kind, slot) is in today's global rotation budget. Always-on kinds always
        pass; a thinned slot just skips delivery today (pool generation untouched).
        Fails OPEN on any gate error — an occasional over-send beats a silent
        blackout if the rotation ever misbehaves."""
        def _job():
            try:
                if not _is_global_slot_active_today(kind, hour, minute):
                    logging.info(
                        "rotation_skip kind=%s slot=%02d:%02d budget=%s",
                        kind, int(hour), int(minute), GLOBAL_DAILY_SEND_BUDGET,
                    )
                    # Record the skip so the send-plan dashboards show "ротация",
                    # not a false "не отправлено" (best-effort, never blocks).
                    try:
                        from backend.database import record_rotation_skip
                        record_rotation_skip(_get_quiz_schedule_now().date(), kind, int(hour), int(minute))
                    except Exception:
                        logging.debug("record_rotation_skip dispatch failed", exc_info=True)
                    # Heartbeat: the slot DID fire (rotation just thinned it) — scheduler alive.
                    _record_sched_heartbeat(f"deliver_{kind}", metadata={"skipped": True, "slot": f"{int(hour):02d}:{int(minute):02d}"})
                    return
            except Exception:
                logging.warning(
                    "rotation gate failed kind=%s slot=%02d:%02d — firing anyway",
                    kind, int(hour), int(minute), exc_info=True,
                )
            # Tag this send with its (kind, slot) so the shared delivery collector can
            # tier-filter DM recipients (Этап 1). ContextVar is per-task, so concurrent
            # sends don't clash; manual/force sends leave it unset → no filtering.
            async def _wrapped(ctx, *a):
                token = _current_scheduled_send.set((kind, int(hour), int(minute)))
                hb_status = "completed"
                try:
                    await async_func(ctx, *a)
                except Exception:
                    hb_status = "failed"
                    raise
                finally:
                    _current_scheduled_send.reset(token)
                    # Real-completion heartbeat off the hot loop (see _record_sched_heartbeat).
                    try:
                        await asyncio.to_thread(
                            _record_sched_heartbeat,
                            f"deliver_{kind}",
                            hb_status,
                            {"slot": f"{int(hour):02d}:{int(minute):02d}"},
                        )
                    except Exception:
                        logging.debug("deliver heartbeat failed kind=%s", kind, exc_info=True)
            submit_async(_wrapped, CallbackContext(application=application), *extra)
        return _job

    def make_bonus_gated(kind, hour, minute, async_func, *extra):
        """Fire UNCONDITIONALLY (no global-rotation gate) as a BONUS send: sets
        _current_scheduled_send (so the collector still applies the silent + window gates)
        AND _scheduled_send_bonus (so it SKIPS the per-user budget count). Used for the
        rail-sprint — it reaches every prepped, non-silent user ON TOP of their daily N,
        never consuming one of those N. Quiet-hours/enabled checks run inside the sender."""
        def _job():
            async def _wrapped(ctx, *a):
                token = _current_scheduled_send.set((kind, int(hour), int(minute)))
                btoken = _scheduled_send_bonus.set(True)
                hb_status = "completed"
                try:
                    await async_func(ctx, *a)
                except Exception:
                    hb_status = "failed"
                    raise
                finally:
                    _scheduled_send_bonus.reset(btoken)
                    _current_scheduled_send.reset(token)
                    # Отметка «слот отработал» — ровно как в make_rotation_gated. Без неё
                    # бонусная выдача уходила людям, а /scheduler_health показывал
                    # «ПРОТУХЛО»: спринт с 24.07 идёт этой веткой (TRAINER_ENABLED=1),
                    # и отчёт 12 дней ругался на живую задачу.
                    try:
                        await asyncio.to_thread(
                            _record_sched_heartbeat,
                            f"deliver_{kind}",
                            hb_status,
                            {"slot": f"{int(hour):02d}:{int(minute):02d}", "bonus": True},
                        )
                    except Exception:
                        logging.debug("bonus deliver heartbeat failed kind=%s", kind, exc_info=True)
            submit_async(_wrapped, CallbackContext(application=application), *extra)
        return _job

